window.__D("text/maamarei-admur-hazaken/c011",{"p":[[2101000085,"לומר שהשמש הוא אשר ממשיך ומשפיע זיו ואור אלא שהזיו ממילא הוא בא כידוע וכך למעלה בחי' אא\"ס ממילא ומאליו הוא בא בהיותו בלתי התלבשות העצמות כנ\"ל וא\"כ התהוות האצי' והבריאה כו' ג\"כ ממילא ומאליו נאצלו ונבראו כו' להיות כי אין שפע זאת נמשכת מעצמות כלל ולכך אינה פועלת שום שינוי כלל בעצמות כנ\"ל וזהו שאמר ונבראו ממילא ולא אמר ובראם ולא<sup data-n=\"402\">18</sup> שבאמת הבריאה היא ח\"ו ממילא ומאליו כי חלילה מלחשוב כן אלא הוא ית' הוא בורא ע\"י רצונו כמ\"ש<sup data-n=\"403\">19</sup> בע\"ח כשעלה ברצונו ור\"ל בעצמותו דוקא ובלעדו לא יהי' דבר אלא שהכוונה שהוא ית' מאיר וממשיך הארה ממנו להחיות העולמות באופן שהארה זו נערכת לגבי עצמותו ית' כמו הארה שמאירה ממילא מהמאור ולכן אין ההארה פועלת שינוי בעצמותו ח\"ו כי היא כמו אור השמש שמאיר מהשמש שאינו נוגע ההארה הזאת להשמש לפי שמאיר ממילא, ולמעלה אם שאינו ממילא רק ברצון ובחירה מ\"מ לענין זה הוא כמו ההארה שמאיר מהשמש שהוא ממילא ואינו פועל שינוי בשמש וכך הארה זו אינה פועלת שינוי ולפיכך יתכן ע\"ז לשון ונבראו להראות כוונה זו וד\"ל.\n<b>ובזה</b> יובן ג\"כ מה שאנו או' אתה הוא עד שלא נבה\"ע ולא אמר עד שלא בראת כו' כי בראת משמע שנמשך הבריאה מן העצמות (ובנוסחות<sup data-n=\"404\">20</sup> ראשונים כתוב עד שלא בראת אבל הנכון יותר כנוסח שלנו מטעם הנ\"ל), וזהו ג\"כ מארז\"ל עד שלא נבה\"ע הי' הוא ושמו בלבד פי' עד שלא נברא ממילא ע\"י בחי' גילוי אור וזיו כנ\"ל הי' הוא ושמו בלבד פי' האור הי' נכלל בעצמות (כי אין ענין אור זה ממש כאור השמש להיות הכרחי בהארה זו שא\"כ הי' ההשתלשלו' בבחי' חיוב המציאות שזהו ענין הקדמות כידוע אלא אור זה האיר ברצון ותחלה הי' כלול בעצמות) וזהו הוא שהוא עצמותו ושמו בחי' גילוי אור הכל הי' בבחי' אחה\"פ שבעצמותו שנק' בלבד כמ\"ש אין<sup data-n=\"405\">21</sup> עוד מלבדו כו' וד\"ל וזהו פי' מלכותך<sup data-n=\"406\">22</sup> מכ\"ע כי יש שני בחי' במלכות הא' מלכותך שהוא בחי' גילוי אא\"ס עצמו כנ\"ל בפי' הוא ושמו בלבד כו' והב' מה שמבחי' מל' דא\"ס נמשך התהוות כל העולמות וז\"ש מלכותך לנוכח להורות על בחי' גילוי העצמות ומבחי' מלכותך נמשך להיות מלכות כ\"ע (כידוע דמבחי' מל' דא\"ס נמשך ג\"ר דא\"ק ומבחי' מל' דא\"ק נעשה ג\"ר דע\"י וא\"א ועד\"ז הולך ויורד מעילה לעילה עד בחי' מל' דאצי' שנעשה ע\"י לבריאה וממל' דבריאה ע\"י דיצי' וממל' דיצי' ע\"י דעשי' כו') והיינו פי' מלך מלכי המלכים כמשי\"ת דקאי על בחי' מל' דא\"ס שנק' מלכותך שהוא מקור כל בחי' מל' שמעולם ועד עולם כו' וד\"ל)<sup data-n=\"407\">23</sup>.",[["402","18","<b>ולא. . להראות כוונה זו</b>: בכת\"י ב וכת\"י ג ליתא. וכנראה הוא דילוג המעתיק שם."],["403","19","<b>כמ\"ש בע\"ח כשעלה ברצונו</b>: ש\"א ענף ב. ובכ\"מ."],["404","20","<b>ובנוסחות ראשונים כתוב עד שלא בראת אבל הנכון יותר כנוסח שלנו</b>: ראה סה\"מ באתי לגני ח\"א ע' כד וע' ר."],["405","21","<b>אין עוד מלבדו</b>: דברים ד, לה."],["406","22","<b>מלכותך מכ\"ע</b>: תהלים קמה, יב."],["407","23","<b>כו'). . וד\"ל)</b>: כ\"ה בהכת\"י. וחסר התחלת המוסגר."]]],[2101000086,"<b>והנה</b> כ\"ז דרך כללות ההשתלשלות אך דרך פרט הנה כתיב כל<sup data-n=\"408\">24</sup> הנק' בשמי ולכבודי בראתיו יצרתיו אף עשיתיו שיש ג'<sup data-n=\"409\">25</sup> עולמות בי\"ע שהן מחדו\"מ כידוע וההפרש ביניהם הנה עולם הבריאה הוא עולם הנשמות כמו ג\"ע העליון שנהנין מזיו כו' והנשמות שרשם בבחי' אותיו' המח' כמארז\"ל ישראל<sup data-n=\"410\">26</sup> עלה במח' שהוא בחי' יש מאין כמו עד\"מ שאנו רואים התהוות אותיו' המח' מן השכל בא מאין ליש כי בהשכלת המושכל עצמו עדיין אין שם אותיות כלל ונתהוו מן ההעלם לגילוי מאין ליש וכנ\"ל בפי' כי הוא ציוה ונבראו כו', ועולם היצי' היינו עולם המלאכים שהן נמשכים מבחי' דיבור כמ\"ש וברוח<sup data-n=\"411\">27</sup> פיו כל צבאם וכמארז\"ל כל<sup data-n=\"412\">28</sup> דיבור ודיבור שיצא כו' ועד\"מ אותיות הדיבור שמתהווי' מאותיו' המח' כי א\"א לדבר רק מה שחושב כידוע (וכמ\"ש<sup data-n=\"413\">29</sup> בע\"ח דעקבי לאה נכנסי' תוך ראש רחל כו') והיינו כמו הצורה לחומר ההיולי שמגלה העלמו כך הדיבור מגלה את המח' ולכך נק' עולם היצי' וכמ\"ש יצרתיו וכידוע שהוא בחי' יש מיש מן המח' שהרי אין כל חדש בדיבור כו' משא\"כ אותיות המח' שלא היו במציאות תחלה במושכל עצמו כי ע\"כ נק' יש מאין וכמ\"ש במ\"א וד\"ל וע' שרים דעשי' שרש דצח\"מ דעשי' ע\"ז נאמר אף עשיתיו כו' וכמ\"ש במ\"א וד\"ל. וזהו שארז\"ל שלא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם ממ\"ה כו'. דהנה מבואר למעלה בפי' מלכותך מכ\"ע דבחי' מל' דא\"ס עצמו נק' מלכותך והיינו מארז\"ל דהי' הוא ושמו בלבד שהוא בחי' גילוי וזיו עצמותו ית' ואח\"כ נמשך הארה להוות כל העולמות שנק' מלכות כ\"ע וגם כאן מ\"ש מלך מלכי המלכי' היינו בחי' מל' דא\"ס עצמו ומלכי המלכים הוא מ\"ש מלכות כ\"ע וז\"ש לך<sup data-n=\"414\">30</sup> הוי' הממלכה כו', כי<sup data-n=\"415\">31</sup> לה' המלוכה וכיוצא, וכאשר נגלה עליהם מבחי' מל' דא\"ס עצמו שלמעלה מבחי' ההשתלשלו' אזי יצאו ממצרים כי ענין יציאת מצרים הוא לצאת מן המיצר והגבול שנמשך מבחי' הצמצום כידוע דכל התהוות עולמות יש מאין הוא בא ע\"י בחי' הצמצום דשם אלקי' המסתיר ומעלים עצמות אלקות בין באצי' בין בבריאה וע\"כ מתהווה בחי' גבול ומדה ג\"כ בנבראים כמו המלאכים והעולמות שהן באין בבחי' גבול מהלך<sup data-n=\"416\">32</sup> ת\"ק שנה וכיוצא וכן<sup data-n=\"417\">33</sup> בס\"י אמר בשיעור קומה של יוצר בראשי' בבחי' היצי'<sup data-n=\"418\">34</sup> אמר שיעור רל\"ו אלפים פרסאות כו' וגם בעולם הנשמות יש גבול ושיעור לכל נשמה במעלה ומדריגה שהרי כל<sup data-n=\"419\">35</sup> צדיק נכוה",[["408","24","<b>כל הנק' בשמי ולכבודי בראתיו</b>: ישעי' מג, ז."],["409","25","<b>ג' עולמות בי\"ע שהן מחדו\"מ</b>: ראה ג\"כ תו\"א עה, ב. ובארוכה באוה\"ת ואתחנן ע' ריז ואילך. ובכ\"מ."],["410","26","<b>ישראל עלה במח'</b>: ב\"ר בתחילתו. ובכ\"מ."],["411","27","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["412","28","<b>כל דיבור ודיבור שיצא</b>: חגיגה יד, א."],["413","29","<b>וכמ\"ש בע\"ח דעקבי לאה נכנסי' תוך ראש רחל</b>: ע\"ח של\"ח רפ\"ג. ועוד."],["414","30","<b>לך הוי' הממלכה</b>: דה\"א כט, יא."],["415","31","<b>כי לה' המלוכה</b>: תהלים כב, מט."],["416","32","<b>מהלך ת\"ק שנה</b>: חגיגה יג, א. ובכ\"מ."],["417","33","<b>וכן בס\"י אמר בשיעור קומה של יוצר בראשית</b>: מובא בכ\"מ בדא\"ח בשם פרקי היכלות: שעור קומה של יוצר בראשית רל\"ו אלפים כו'. ראה לקו\"ת שלח נ, ג. אוה\"ת וארא ע' קצז. וראה שוח\"ט משלי י, ג. ת\"ז תי' ע' (קכב, ב ואילך). ע\"ח שמ\"ב פ\"ב ושמ\"ד פ\"ז."],["418","34","<b>היצי'</b>: בכת\"י ב וכת\"י ג: האצי'."],["419","35","<b>כל צדיק נכוה מחופתו של חבירו</b>: ב\"ב עה, א."]]],[2101000087,"מחופתו של חבירו כו' כי כל ההשתלשלו' באה בבחי' הצמצום הנק' קו המדה וכמ\"ש מי מדד בשעלו מי<sup data-n=\"420\">36</sup>ם כו' וכידוע שהוא בחי' הקוה\"ח שנמשך מעצמות אא\"ס אחר הצמצום אבל בזמן יצי\"מ הרי נגלה עליהם מבחי' מל' דא\"ס שלפני הצמצום הראשון הנק' מלך מלכי המלכי' כנ\"ל אזי ממילא יצאו כל העולמות מבחי' המיצר והגבול דקו המדה הנ\"ל בהגלות נגלות עליהם אור עצמות א\"ס שלמעלה מכל ההשתלשלות וד\"ל.\nב) <b>ומ\"ש</b> שלא הספיק בצקת של אבותינו להחמיץ עד שנגלה כו' הנה הבצק הזה הוא אשר הוציאוהו ממצרים אחר חצות ואפוהו בדרך כנ\"ל והוא אשר לא הספיק להחמיץ עד שנגלה עליהם כו' אבל מצה הראשונה שאכלו קודם חצות עם הפסח כנ\"ל לא אמרו בו שלא הספיק להחמיץ כו' אלא שהי' נשמר מן החימוץ בידי אדם כמ\"ש ושמרתם את המצות כנ\"ל. והענין הוא כי הנה כדי שיוכלו לקבל בחי' גילוי גדול זה דמל' דא\"ס שלפני ההשתלשלות הוצרכו שיאכלו מצה שנשמרת מכל חימוץ כי ענין המצה<sup data-n=\"421\">37</sup> נק' בזוהר מיכלא דמהימנותא פי' ע\"י המצה נמשך בהם בחי' הדעת וההכרה באא\"ס עצמו כמ\"ש דע<sup data-n=\"422\">38</sup> את אלקי אביך כו' וידעת<sup data-n=\"423\">39</sup> היום כו' כמו התינוק<sup data-n=\"424\">40</sup> שאינו יודע לקרות אבא עד שיטעום טעם דגן דוקא והוא לפי שבחי' הדעת וההכרה הזאת להכיר את אביו עד שיודע לקרותו אבא כמו ידע<sup data-n=\"425\">41</sup> שור קונהו כו' תלוי בטעם דגן דוקא להיות שהלחם הוא בבחי' חכ' שהרי עד שלא טעם לחם אלא יונק חלב משדי אמו עדיין אין בו דעת להכיר את אביו לקרותו אבא ומשטעם לחם יודע לקרותו כו' א\"כ הרי נראה בחוש שע\"י טעם דגן יתהווה בתינוק בחי' הדעת וכך ע\"י המצה מתהווה בנה\"א בחי' הדעת וההכרה באור א\"ס (רק שעדיין אינו משיג בהשגה גמורה כמו התינוק שאינו רק מכיר לאביו בהכרה לבד ולא שיודע אותו בטוב טעם ושכל כו' כך המצה נק' לחם עוני בבחי' הקטנות והוא בחי' קטנות דאבא כמ\"ש בפע\"ח וכמבואר במ\"א). והנה בחי' מצה זאת היא צריכה שימור מן החימוץ מאד כי ענין החמץ והשאור ידוע שהוא בחי' ההגבהה וההתנשאות שנק' גסות הרוח וחוצפא<sup data-n=\"426\">42</sup> שנק' מלכותא בלא תגא כו' שממנו מקור הקליפות כמ\"ש אם<sup data-n=\"427\">43</sup> תגביהי כנשר כו' ונק' אבי אבות הטומאה כי פי' אבות הטומאה הן חו\"ב דקליפה המולידים המדות רעות והתאוות כו' ואבי אבות הטומאה הוא בחי' הגסות כו' שהוא מקור כל רע ונק'<sup data-n=\"428\">44</sup> בס\"י עומק רע ולכן<sup data-n=\"429\">45</sup> הוזהר מלהקריב כל שאור ומחמצת כו' וכמו ששנינו כל<sup data-n=\"430\">46</sup> המנחות באות מצה חוץ מתודה ושתי הלחם כו', אך המצה היא",[["420","36","<b>מי מדד בשעלו מים</b>: ישעי' מ, יב."],["421","37","<b>המצה נק' בזוהר מיכלא דמהימנותא</b>: ראה זח\"ב מא, א. וראה דרמ\"צ כב, ב."],["422","38","<b>דע את אלקי אביך</b>: דה\"א כח, ט."],["423","39","<b>וידעת היום</b>: דברים ד, לט."],["424","40","<b>התינוק שאינו יודע לקרות אבא. . טעם דגן</b>: ברכות מ, א."],["425","41","<b>ידע שור קונהו</b>: ישעי' א, ג."],["426","42","<b>וחוצפא שנק' מלכותא בלא תגא</b>: סנהדרין קה, א."],["427","43","<b>אם תגביהי כנשר</b>: ראה עובדי' פסוק ד."],["428","44","<b>ונק' בס\"י עומק רע</b>: ס\"י פ\"א מ\"ה."],["429","45","<b>ולכן הוזהר מלהקריב כל שאור ומחמצת</b>: ויקרא ב, יד."],["430","46","<b>כל המנחות באות מצה</b>: מנחות נב, ב."]]],[2101000088,"היפך בחי' גסות דחמץ כי הרי אין בה הגבהה וניפוח כמו בחמץ וגם אין בה טעם מורגש כמו בחמץ להיות כי בחי' המצה הוא רק בחי' הביטול לבטל הרצון כמאמר בטל רצונך וכו' ובחי' ביטול רצון בא מצד בחי' השפלות מפני העדר הרגשת עצמותו מכל וכל כידוע וע\"כ אין במצה טעם מורגש כמו ביטול רצון שאין בו טעם אלא מפני שאמר ונעשה רצונו כו' ומזה הענין יובן משארז\"ל בלע<sup data-n=\"431\">47</sup> מצה יצא בלע מרור לא יצא דבעי' טעם מרור כו' אבל במצה לא בעינן טעם כלל וד\"ל.\n<b>ונמצא</b> מובן מזה שבבחי' השפלות דביטול רצון שבמצה ממילא יבא מזה בחי' ביעור הרע מכל וכל לאכפי' לסט\"א כו' שנק' ביעור חמץ וכמ\"ש ובערת<sup data-n=\"432\">48</sup> הרע מקרבך, ולהיות כי אין ביעור הרע אלא בבחי' גבורו' ודינין כמשארז\"ל לעולם<sup data-n=\"433\">49</sup> ירגיז אדם יצ\"ט על יצה\"ר כו' ע\"כ יש בפי' מצה לשון כעס ומריבה כמו הן<sup data-n=\"434\">50</sup> לריב ומצה כו' כי<sup data-n=\"435\">51</sup> ינצו כו' כי צריך ללחום במריבה לבטל היש דגסות שהוא מקור כל רע כנ\"ל וד\"ל.\n<b>והנה</b> כתיב על<sup data-n=\"436\">52</sup> מצות ומרורים יאכלוהו שנכלל במצה זו ג\"כ בחי' מרור אך במרור בעינן טעם מרור ואם בלע מרור לא יצא כנ\"ל. והענין הוא כי א\"א לבא לבחי' ביטול רצון מכל וכל דמצה כ\"א ע\"י בחי' המרירות שיתמרמר בנפשו ויטעום טעם מרירות על עוצם ריחוקו מה' אחד והטעם הוא כי הנה ידוע דהמרור יש להניחו באמצע הקערה להיותו בבחי' קו האמצעי שהוא בחי' הת\"ת כידוע ולכאורה יש לתמוה שהרי המרור הוא בחי' מרירות וכעס ומריבה כנ\"ל שבא מבחי' קו השמאל שהוא בחי' הגבורות כידוע, אך הענין הוא משום דע\"י המרירות הזאת מתעורר למעלה בחי' ר\"ר שהוא בבחי' קו האמצעי כי הרחמים הוא בחי' תפארת כידוע. וביאור הדברי' הנה ידוע דאין מדת הרחמים מתפשטת רק על דבר שהוא בבחי' שפלות גדולה מאד או ביסורים גדולים כמו עני ודל או מדוכה וחולה וכיוצא אבל על מי שהוא בהגבהה במדריגה עליונה כמו בעושר ובגדולה וכיוצא לא תתפשט עליו מדה\"ר כלל, ונמצא שלעולם אין מציאות להתפעלו' מדת הרחמים כ\"א כאשר עבר תחלה מדה\"ד והעונש כמו על עני וחולה וכה\"ג שעבר עליהם מדה\"ד להשפילם בעוני ויסורים וכה\"ג אזי ע\"י מדה\"ר יושפע עליהם חסד להקימם ולהעלותם כו' וא\"כ הרי יש ברחמים הרכבה מב' מדות חסדי' וגבורו' והיינו הטעם שמדה\"ר הוא בבחי' הקו האמצעי הכולל לחו\"ג כו' וגם בענין המרור יובן שע\"י טעם מרירות שיתמרמר בנפשו על עוצם הריחוק כנ\"ל הנה בזה מעורר לבחי' ר\"ר למעלה שכולל לחו\"ג ויומשך מזה בחי' מצה הנ\"ל לאכפי' לדינין ששרשם בחמץ שהוא מקור כל רע כנ\"ל וד\"ל.",[["431","47","<b>בלע מצה יצא</b>: פסחים קטו, ב."],["432","48","<b>ובערת הרע מקרבך</b>: דברים יג, ו. יז, ז. ועוד."],["433","49","<b>לעולם ירגיז אדם יצ\"ט על יצה\"ר</b>: ברכות ה, א. וראה תניא פכ\"ט ופל\"א ובליקוט פירושים ומ\"מ שם."],["434","50","<b>הן לריב ומצה</b>: ישעי' נח, ד."],["435","51","<b>כי ינצו</b>: שמות כא, כב. דברים כה, יא."],["436","52","<b>על מצות ומרורים יאכלוהו</b>: במדבר ט, יא."]]],[2101000089,"<b>ובזה</b> יובן ג\"כ מה שאנו או' המלך<sup data-n=\"437\">53</sup> המרומם כו' המתנשא מימות כו' אלקי עולם ברחמיך הרבי' רחם עלינו ולכאורה אין לשני דברים אלו סמיכות וקשר אם הוא מלך מרומם ומתנשא כו' ע\"כ רחם ירחם כו', אך הענין הוא כנ\"ל דאין הרחמנות רק לפי ערך השפלות והדלות כו' ולהיותו הוא ית' מלך המרומם לבדו דהיינו בחי' מל' דא\"ס קודם הצמצום כנ\"ל דכל ההשתלשלות כלא חשיבי לגבי עצמותו כי לא נמשכו רק מבחי' הארה בעלמא משמו כו' כנ\"ל ע\"כ ממילא יש מקום למציאות התפעלות רחמים רבים עלינו על היותינו רחוקים מאד כי לפי ערך הרוממות כך ערך השפלות ולכך כל מלך שמרומם ביותר יותר יש בו מדה\"ר כידוע וד\"ל. והנה בחי' מצה הנ\"ל בבחי' ביטול רצון בלבד צריכה שימור שלא תבא לידי חמץ מיניקות החיצונים בהגבהה והתנשאות וז\"ש ושמרתם את המצות כנ\"ל וזאת המצה אכלו קודם חצות עם הפסח שהי' בבחי' אתדל\"ת כדי לעורר אתעדל\"ע שיתגלה עליהם מלך מלכי כו' שהוא בחי' מל' דא\"ס ואז לא הספיק בצקת שלהם להחמיץ כו' והיא בחי' מצה השנית שאכלו אחר חצות והיינו בחי' הביטול שבא מלמעלה למטה מצד בחי' גילוי אור עצמות הא\"ס וכמארז\"ל במורא<sup data-n=\"438\">54</sup> גדול זו גילוי שכינה כו' והוא בחי' ביטול אמיתי שלא יוכל לבא לבחי' הגבהה והתנשאו' כלל וא\"צ שימור כלל, וע\"כ לא היו צריכים לאכול מרור עם מצה זו השנית כי דוקא במצה הראשונה שלפני חצות היו צריכים לר\"ר כדי שיוכלו לאכפי' כו' בבחי' ביטול רצון אבל מצה זו השנית הרי נגלה עליהם מלמעלה למטה באופן שא\"צ שימור כלל ואין טעם מרור רק על הריחוק כמ\"ש מרור<sup data-n=\"439\">55</sup> זה שאנו אוכלים ע\"ש שמררו המצרי' את חיי אבותינו פי' אבותינו הן בחי' המדות דקדושה שגברו עליהם מדות דנש\"ט דמצרים ומיררו את חייהם כו' אבל בבחי' גילוי זה שאחר חצות ממילא יצאו מכל נש\"ט וכמ\"ש ועברתי<sup data-n=\"440\">56</sup> בארץ מצרים אני<sup data-n=\"441\">57</sup> ולא מלאך כו' וד\"ל.\nג) <b>וזהו</b> קול דודי הנה זה בא מדלג על ההרים כו', דהנה פסוק זה מדבר על זמן יצי\"מ דכתיב ופסח ה' על הפתח כו' כנ\"ל, וזהו מדלג על ההרים כו' ופי' קול דודי הנה קול זה הוא בחי' המשכה נעלמת ולא המשכה נגלית כמו קול הדיבור שנק' קלא דאשתמע פי' שנגלה בדיבור המשכות המדות שבלב<sup data-n=\"442\">58</sup> אהבה או יראה כו' אבל בחי' קול זה נק' קלא דלא משתמע בגילוי אלא הוא בחי' המשכה מן ההעלם בלבד ונק' קול<sup data-n=\"443\">59</sup> גדול ולא יסף פי' שאין לו שיעור ומדה כלל כמו ויהי<sup data-n=\"444\">60</sup> קול השופר הולך וחזק מאד וכל מקום שנאמר מאד הוא בלי שיעור וגבול, והענין הוא כי בחי'",[["437","53","<b>המלך המרומם כו'</b>: נוסח ברכת יוצר."],["438","54","<b>במורא גדול זו גילוי שכינה</b>: דברים כו, ח. נוסח ההגדה."],["439","55","<b>מרור זה שאנו אוכלים ע\"ש שמררו המצרי'</b>: נוסח ההגדה (פסחים קטז, ב)."],["440","56","<b>ועברתי בארץ מצרים</b>: שמות יב, יב."],["441","57","<b>אני ולא מלאך</b>: נוסח ההגדה (ספרי עה\"פ). וראה זח\"א קיז, א. לקו\"ת צו יב, ג. ובכ\"מ. וראה ג\"כ שמו\"ר פל\"ב, ח. תניא פמ\"ו."],["442","58","<b>שבלב אהבה או יראה</b>: בכת\"י ב וכת\"י ג: בלב אהוי\"ר."],["443","59","<b>קול גדול ולא יסף</b>: דברים ה, יט. וראה אוה\"ת וישב רסג, ב. ובכ\"מ."],["444","60","<b>ויהי קול השופר הולך וחזק מאד</b>: שמות יט, יט."]]],[2101000090,"המשכות המדות בלב יש לו גבול ושיעור למטה בדיבור אבל כאן מדבר בבחי' ההמשכה מבחי' העלם העצמו' של המאציל ב\"ה והוא בחי' מל' דא\"ס שלפני הצמצום שלמעלה מכל בחי' השתלשלות דע\"ס דהיינו למעלה גם מרצון וחכ' כו' וכנ\"ל בפי' נגלה עליהם מלך מלכי המלכים כו' מבחי' גילוי עצמות אא\"ס ב\"ה הוא הנק' קול גדול ולא יסף בבחי' א\"ס ממש וד\"ל, וזהו קול דודי בחי' קול גדול הנ\"ל מדלג על ההרים בבחי' דליגה שלא כסדר ההשתלשלות עו\"ע כמו עד\"מ השתלשלות הדיבור מן המחשבה והמח' מן המדות והמדות מן השכל והשכל מלמעלה מן השכל שכ\"ז הוא בחי' עו\"ע שיש ערך ושייכות זע\"ז כי בהכרח יש שכל למעלה מן השכל ואם לאו לא הי' נמשך שכל דוקא וכן יש מדות בשכל וא\"ל לא היו נולדי' מדות משכל וא\"כ ה\"ז בחי' יש מיש לכך יש ביניהם ערך כו' וכמ\"ש במ\"א אבל אור הנמשך שלא בסדר השתלשלות עו\"ע הוא בחי' יש מאין שאין ערך ביניהם כלל והוא דוקא בבחי' מל' דא\"ס שאין לנאצלים ערך עמו וע\"כ נק' בשם דילוג וז\"ש מדלג על ההרים פי' הרים הן בחי' מדריגות עליונות שבאין ונמשכין מעצמות המאציל (וכמ\"ש בצאת<sup data-n=\"445\">61</sup> ישראל ממצרים כו' הים ראה וינוס כו' ההרים רקדו כאילים כו' מלפני אדון כו') ועד\"מ הרץ במרוצה מדלג מהר אל הר לפי שההליכה קשה בין הר להר ובהכרח לדלג כי בדליגה יוכל להגיע מהר להר והנמשל מזה יובן שבחי' הארה הגדולה מבחי' עצמות אא\"ס מדלג על ההרים העליונים מהר להר כדי לבא למטה ואין האור הולך בסדר המשכה להיותו למעלה מסדר ההשתלשלות כנ\"ל וד\"ל.\n<b>וזהו</b> שארז\"ל ובמורא גדול זו גילוי שכינה פי' כי מורא גדול היינו מצד עוצם ההתגלות כמו לעתיד דכתיב ובאו<sup data-n=\"446\">62</sup> במערות צורים מפני פחד ה' כו' וכאן לפי שהי' בחי' גילוי שכינה שהוא בחי' מל' דא\"ס נק' מורא גדול לפי ערך התגלות גדולת עצמות אא\"ס שלגדולתו אין חקר וגילוי זה הי' כדי להוציאם ממצרים בלבד כמ\"ש או<sup data-n=\"447\">63</sup> הנסה אלקים לקחת לו גוי מקרב גוי במסות כו' ובמורא גדול כו' וד\"ל (ועוד<sup data-n=\"448\">64</sup> יש לפרש מדלג על ההרים בזכות האבות<sup data-n=\"449\">65</sup> שנק' הרים כידוע והיינו ע\"י שאכלו פסח מצה ומרור שג' דברים האלה הן בחי' ג' קוין פסח בקו השמאל להיותו בחי' גבורות כמשי\"ת בענין מקפץ על הגבעות כו' ומצה בקו הימין בחי' חכ' כו' ומרור בקו האמצעי כנ\"ל וג' קוין הללו היינו בחי' חג\"ת שהן האבות ובזכותם הוא מדלג כו' וד\"ל. והנה בשיר השירים נאמר מדלג על ההרים לשון דליגה ובתורה נאמר ופסח ה' על הפתח והוא ג\"כ ענין דילוג רק שבשה\"ש אינו מבואר להיכן הוא מדלג רק שמבואר אופן הדילוג שהוא על ההרים והגבעות אבל בתורה מבואר לאיזה מקום הוא מדלג והיינו מ\"ש ופסח ה' על הפתח שעל הפתח הוא פוסח ומדלג.",[["445","61","<b>בצאת ישראל ממצרים</b>: תהלים קיד, א."],["446","62","<b>ובאו במערות צורים מפני פחד ה'</b>: ראה ישעי' ב, יט."],["447","63","<b>או הנסה אלקים לקחת לו גוי מקרב גוי</b>: ראה דברים ד, לד."],["448","64","<b>(ועוד</b>: בהכת\"י חסר סיום המוסגר. ואולי צריך להיות אחר התיבות: מדלג כו' וד\"ל."],["449","65","<b>האבות שנק' הרים</b>: ראה ר\"ה יא, א. ירושלמי סנהדרין פ\"י ה\"א. שמו\"ר פט\"ו, ד. ויק\"ר ספל\"ו. ספרי דברים לג, טו. תו\"א שמות נא, ג. לקו\"ת תצא מ, א."]]],[2101000091,"<b>וביאור</b> ענין ובחי' הפתח היינו בחי' מל' דאצי' שנק' פתח ושער כמ\"ש זה<sup data-n=\"450\">66</sup> השער להוי' כו' וכמ\"ש<sup data-n=\"451\">67</sup> בזהר ע\"פ והוא יושב פתח האוהל וכן ותשב<sup data-n=\"452\">68</sup> בפתח עינים והיינו<sup data-n=\"453\">69</sup> בחי' מלכות כ\"ע שמהווה מאין<sup data-n=\"454\">70</sup> ליש ממש כידוע ולהיותו בחי' התגלות לחוץ מבחי' אלקים בעולמות הנפרדי' מאין ליש ע\"כ נק' פתח ושער שבו יוצאין לחוץ ובו נכנסים לפנים כו' וכאן שהי' בחי' דילוג מבחי' מל' דא\"ס על ההרים העליונים שלפני האצי' הנה בתורה מבאר להיכן הי' הדילוג הזה לבחי' המל' דאצי' שנק' פתח ושער להוי' וז\"ש ופסח ה' על הפתח לפי שנעוץ<sup data-n=\"455\">71</sup> תחב\"ס כידוע דהמל' הוא בחי' יראה תתאה קבלת מ\"ש שזהו ראשית העבודה כמ\"ש ראשית<sup data-n=\"456\">72</sup> חכ' יראת ה' כו' ונק' תרעא<sup data-n=\"457\">73</sup> לדרתא כו' ודחילו עילאה הוא בחי' מל' דא\"ס שנק' מורא גדול, ובדילוג זה נמשך יראה עילאה ביראה תתאה שלא כסדר המדריגות דחילו ורחימא רחימו ודחילו וז\"ש מדלג על ההרים שהן המדות אהבה כו' ויש בדילוג זה ב' פי' כנ\"ל א' שמדלג בזכות הרים והב' שמדלג למעלה מן ההרים כו' וד\"ל.\nד) <b>מקפץ</b> על הגבעות. הנה ההפרש<sup data-n=\"458\">74</sup> אשר בין דליגה לקפיצה ידוע במשנה וגמרא שהדילוג הוא ברגל א' בלבד והקפיצה הוא ממקום למקום בשתי רגלים דוקא. וביאור הענין למעלה הנה האבות נק' הרים והאמהות<sup data-n=\"459\">75</sup> נק' גבעות כמ\"ש כי<sup data-n=\"460\">76</sup> מראש צורים אראנו ומגבעות כו' וכן ארז\"ל הרים אלו האבות כמ\"ש שמעו הרים<sup data-n=\"461\">77</sup> את ריב ה' כו' ופי' הדליגה על ההרים והקפיצה על הגבעות והן אבות ואמהות היינו בחי' אהבה רבה ויראה עילאה שנק' מורא גדול כי האבות שרשם הן בבחי' האה\"ר שלפני האצי' (כמ\"ש אשר<sup data-n=\"462\">78</sup> נשבעת לאבותינו שהן ההרים עליונים חג\"ת דאצי' מימי קדם מבחי' אה\"ר שבעצמו' המאציל שנק' קדמון כו') והאמהות שרשם בבחי' יראה עילאה שבעצמות שנק' מורא גדול ובבחי'<sup data-n=\"463\">79</sup> הדילוג הנ\"ל שהוא בחי' המשכת מל' דא\"ס שלפני הצמצום הי' בזה ב' מדריגות אוי\"ר שהן שרשי האבות והאמהות שנק' הרים וגבעות כנ\"ל, והנה בבחי' האה\"ר הי' בחי' דילוג רק ברגל א' הימנית שהוא בבחי' החסד כמ\"ש וימינו<sup data-n=\"464\">80</sup> תחבקני אך בבחי' התגלות היראה עילאה שנק' מורא גדול הוצרך להיות בקפיצה בב' רגלים כי כדי שיהי' גילוי",[["450","66","<b>זה השער לה'</b>: תהלים קיח, כ."],["451","67","<b>וכמ\"ש בזוהר ע\"פ והוא יושב פתח האהל</b>: ראה זח\"א צח, א ואילך. זח\"ב לו, א. זח\"ג עא, ב. וראה אוה\"ת בא כרך ז' ע' ב'תרלח ואילך. אוה\"ת שה\"ש ע' רסו."],["452","68","<b>ותשב בפתח עינים</b>: בראשית לח, יד."],["453","69","<b>והיינו בחי' מלכות כ\"ע [ כתר עליון]</b>: ראה לקו\"ת שה\"ש טו, ב."],["454","70","<b>מאין ליש</b>: בכת\"י ב וכת\"י ג: יש מאין."],["455","71","<b>שנעוץ תחלתן בסופן</b>: ס\"י פ\"א מ\"ז."],["456","72","<b>ראשית חכ' יראת ה'</b>: תהלים קיא, י. וראה תניא פמ\"ג."],["457","73","<b>תרעא לדרתא</b>: שבת לא, ב."],["458","74","<b>ההפרש אשר בין דליגה לקפיצה ידוע במשנה וגמרא</b>: אהלות פ\"ח מ\"ה. וראה לקו\"ת שה\"ש הנסמן לעיל בריש המאמר."],["459","75","<b>והאמהות נק' גבעות</b>: ראה בהנסמן לעיל: האבות שנק' הרים."],["460","76","<b>כי מראש צורים אראנו</b>: במדבר כג, ט."],["461","77","<b>הרים אלו האבות כמ\"ש שמעו הרים</b>: שמו\"ר פט\"ו, ד. מיכה ו, ב."],["462","78","<b>אשר נשבעת לאבותינו</b>: מיכה ז, כ."],["463","79","<b>ובבחי'</b>: בכת\"י ב וכת\"י ג: והוא בבחי'."],["464","80","<b>וימינו תחבקני</b>: שה\"ש ב, ו."]]],[2101000092,"מורא גדול צריך להיות בב' רגלים וזהו הכלל דכל ירידה שלא לפי ערך אינו בא רק מבחי' האחרונה שהוא בחי' נו\"ה שנק' רגלים כמ\"ש והארץ<sup data-n=\"465\">81</sup> הדום רגליו וכן כתיב ועמדו<sup data-n=\"466\">82</sup> רגליו ביום ההוא על הר הזיתים, והטעם להתגלות יראה עילאה שרש האמהות שצ\"ל בקפיצה בשתי רגלים, הנה עפ\"י פשוט אנו רואים שבנקל יותר לאדם להגיע לדביקות באהבה יותר משיגיע ליראה שבאה בקושי גדול כו' ושרש הדברים הנה הגם שלמטה האהבה גדולה מיראה אבל למעלה היראה גדולה מן האהבה ויובן זה בהקדים מה שיש להפלא לכאורה על מה שמצינו שנאמר לאברהם כל<sup data-n=\"467\">83</sup> אשר תאמר אליך שרה שמע בקולה והלא אברהם הוא בחי' משפיע ושרה בחי' מקבל ואיך ישמע אברהם לקבל משרה וכן ברבקה כתיב ותרד<sup data-n=\"468\">84</sup> העיינה וידוע דעין זה הוא בחי' ח\"ע ואוריי'<sup data-n=\"469\">85</sup> מח\"ע נפקת וז\"ש ותמלא<sup data-n=\"470\">86</sup> כדה כ\"ד ספרים דאוריי' וכתיב ותרד שזהו ירידה אצלה והלא רבקה בחי' נוקבא וכן כתיב בה טובת<sup data-n=\"471\">87</sup> מראה מאד בלי גבול כו', אך הענין הוא דבאמת למטה היו האבות בחי' משפיעי' והאמהות בחי' מקבלים אבל למעלה היו האמהות למעלה מבחי' האבות כמו לעתיד דכתיב א\"ח<sup data-n=\"472\">88</sup> ע\"ב, נקבה<sup data-n=\"473\">89</sup> תסובב גבר, שבחי' המקבל יתעלה למעלה מבחי' דכר ויהיו האבות מקבלי' מן האמהות, ובאברהם יצחק ויעקב ארז\"ל שהטעימן<sup data-n=\"474\">90</sup> הקב\"ה מעין העוה\"ב דלעתיד שנאמר בהן בכל מכל כל כו' וע\"כ גם עכשיו הי' מדריגה באמהות שלמעלה מן האבות ולכך נאמר כל אשר תאמר לך שרה שמע בקולה וכן ברבקה ותרד העיינה כו' וד\"ל.\n<b>וביאור</b> הדבר היינו לפי שיש ב' מדריגות הא' בבחי' או\"י מלמעלה למטה והב' בבחי' או\"ח מלמטה למעלה כמ\"ש בע\"ח והנה בבחי' השתלשלות שבבחי' או\"י מלמעלה למטה היו האבות בחי' משפיעי' והאמהות בחי' מקבלי' אבל בבחי' או\"ח מלמטה למעלה נהפוך הוא שבחי' האמהות למעלה מבחי' האבות לפי שסוף מעשה עלה במח\"ת וכמ\"ד<sup data-n=\"475\">91</sup> בגמרא דארץ קדמה כו' ואעפ\"י שבסדר ההשתלשלות בבחי' א\"י הוא סוף כל המדריגות אך בבחי' או\"ח עולה ראשונה כו', וכן הוא כל המדות שבקדושה שנעוץ<sup data-n=\"476\">92</sup> תחב\"ס וסוב\"ת כמ\"ש בס\"י שיש בסוף מבחי' התחלה ובתחלה יש מבחי' הסוף כו' וד\"ל. ובזה יובן הטעם למה נאמר קפיצה בשתי רגלים באמהות אעפ\"י שהאבות הן בחי' משפיעים, כי בבחי' או\"ח האמהות למעלה וכאן הי'",[["465","81","<b>והארץ הדום רגליו</b>: ראה ישעי' סו, א."],["466","82","<b>ועמדו רגליו ביום ההוא</b>: זכרי' יד, ד."],["467","83","<b>כל אשר תאמר אליך שרה שמע בקולה</b>: בראשית כא, יב."],["468","84","<b>ותרד העיינה</b>: בראשית כד, טז. וראה לעיל ד\"ה מים רבים."],["469","85","<b>ואוריי' מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["470","86","<b>ותמלא כדה כ\"ד ספרים דאוריי'</b>: ת\"ז תכ\"א (מו, ב). וראה בהנסמן לעיל בד\"ה מים רבים."],["471","87","<b>טובת מראה מאד</b>: בראשית כד, טז."],["472","88","<b>א\"ח ע\"ב</b>: משלי יב, ד. וראה אוה\"ת בראשית מ, ב."],["473","89","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["474","90","<b>שהטעימן הקב\"ה מעין העוה\"ב</b>: ב\"ב טז, ב."],["475","91","<b>וכמ\"ד בגמרא דארץ קדמה</b>: חגיגה יב, א. וראה תו\"א ויגש מד, ג. ובכ\"מ."],["476","92","<b>שנעוץ תחב\"ס וסוב\"ת כמ\"ש בס\"י</b>: ס\"י פ\"א מ\"ז."]]],[2101000093,"בחי' או\"ח כמ\"ש ופסח ה' על הפתח דוקא לפי שסוף מעשה עלה כו' וזהו מקפץ על הגבעות שהוא בחי' האמהות והיינו בחי' מורא גדול שיורד ביראה תתאה כנ\"ל וד\"ל.\n<b>והנה</b> כמו שיש בחי' אבות ואמהות למטה שהן בחי' גבעות והרים הנ\"ל כך יש למעלה ג\"כ בחי' אבות ואמהות והוא בענין תומ\"צ, דהנה ידוע שפעמים משמע ששרש התורה גבוה מן שרש המצות וכמשמעות דרז\"ל דתלמוד<sup data-n=\"477\">93</sup> גדול שמביא לידי מעשה וכן אמרו דת\"ת<sup data-n=\"478\">94</sup> כנגד כולם לפי שהתורה מורה איך שתעשה המצוה באופנים פרטיי' ואם לאו אינו מצוה כלל דהיינו שאינו רצה\"ע כלל וא\"כ מוכרח ששרש התורה למעלה מן המצות, ולפעמים משמע שהמצות גבוהים מן שרש התורה לפי שאין ענין התורה רק ביאור ופי' למצות כטפל לגבי העיקר וכמשמעו' הטעם דתלמוד גדול לפי שמביא לידי מעשה א\"כ המעשה עיקר וכמ\"ש דלא<sup data-n=\"479\">95</sup> המדרש עיקר אלא המעשה והלומד<sup data-n=\"480\">96</sup> ואינו עושה נוח לו כו'. אך הענין הוא דשניהם אמת כידוע דשרש<sup data-n=\"481\">97</sup> המצות הוא בבחי' כתר עליון בגי' תר\"ך שהן תרי\"ג מצות דאוריי' וז' דרבנן והן הנק' תר\"ך עמודי אור שבהן מתחבר אא\"ס באצי' לפי שבחי' הכתר<sup data-n=\"482\">98</sup> ממוצע בין אא\"ס לנאצלים כמ\"ש בע\"ח והיינו להיותם בחי' רצה\"ע ממש כידוע אבל שרש התורה הוא מבחי' חכמה דאוריי'<sup data-n=\"483\">99</sup> מח\"ע נפקת כידוע וכתיב והחכ'<sup data-n=\"484\">100</sup> מאין תמצא מאין דכתר וע\"כ שרש המצות גבוהים משרש התורה, אבל הנה כתיב והחכ'<sup data-n=\"485\">101</sup> תחי' בעליה פי' בעליה דחכ' הוא בחי' אור הכתר שרש המצות והחכ' דתורה תחי' לבעליה שהן המצות לפי שבבחי' א' התורה גבוה מן המצות כנ\"ל. והענין הוא כנ\"ל שיש ב' מדריגות בחי' או\"י כמו האה\"ר הנ\"ל ושרש התורה ג\"כ מבחי' או\"י שהולך מלמעלה למטה כי ע\"י התורה נמשך אא\"ס בחכ'<sup data-n=\"486\">102</sup> שהוא בקו הימין חח\"נ כו' ומצד טעם זה שרש התורה גבוה מן המצות כמ\"ש והחכ' תחי' בעליה כי מוספת אור א\"ס בכתר שרש המצות, והמדריגה הב' בבחי' או\"ח הוא שרש המצות למטה שהמה נעשי' בדברי' גשמיי' ומתברר מחשוכא לנהורא ע\"י מ\"ע ול\"ת כידוע ומפני שנעוץ תחב\"ס כנ\"ל וע\"כ בחי' האמהות גבוהים לעתיד כנ\"ל באורך א\"כ גם המצות גבוהים משרש התורה להיותם בבחי' או\"ח מלמטה למעלה שמעורר בחי' הארת מל' דא\"ס שלפני הצמצום שנק' מורא גדול כנ\"ל וד\"ל. וזהו ענין שהתו\"מ נק' ג\"כ הרים וגבעות שהוא בחי' אבות ואמהות כנ\"ל. דהנה כתיב ישאו<sup data-n=\"487\">103</sup> הרים שלום וגבעות בצדקה פי' התורה נק'",[["477","93","<b>דתלמוד גדול שמביא לידי מעשה</b>: קדושין מ, ב."],["478","94","<b>דת\"ת כנגד כולם</b>: פאה פ\"א מ\"א."],["479","95","<b>דלא המדרש עיקר אלא המעשה</b>: אבות פ\"א מי\"ז."],["480","96","<b>והלומד ואינו עושה נוח לו כו'</b>: ירושלמי ברכות פ\"א ה\"ב."],["481","97","<b>דשרש המצות הוא בבחי' כתר עליון בגי' תר\"ך</b>: ראה אגה\"ק סכ\"ט. פרדס ש\"ח פ\"ג."],["482","98","<b>הכתר ממוצע בין אא\"ס לנאצלים כמ\"ש בע\"ח</b>: שמ\"ב פ\"א."],["483","99","<b>דאוריי' מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["484","100","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["485","101","<b>והחכ' תחי' בעליה</b>: קהלת ז, יב."],["486","102","<b>בחכ' שהוא בקו הימין חח\"נ</b>: ראה זח\"ג קנג, ב. פרדס ש\"ו פ\"א."],["487","103","<b>ישאו הרים שלום</b>: ראה תהלים עב, ג."]]],[2101000094,"שלום כמ\"ש או<sup data-n=\"488\">104</sup> יחזיק במעוזי יעשה שלום לי כו' שלום<sup data-n=\"489\">105</sup> בפשמ\"ע כו' וכמ\"ש ורב<sup data-n=\"490\">106</sup> שלום כו' וכידוע (ונק' ג\"כ הרים כי התורה ניתנה בהר סיני שנק'<sup data-n=\"491\">107</sup> הר אלקים וכמשמעות הלשון משה<sup data-n=\"492\">108</sup> קיבל תורה מסיני, ולרב<sup data-n=\"493\">109</sup> יוסף קראו סיני וכן הלשון הלכה למשה מסיני) וז\"ש ישאו הרים שלום שע\"י התורה נמשך בחי' שלום והוא בחי' חיבור אא\"ס באצי' שנק' פשמ\"ע ובבריאה שנק' פשמ\"ט כידוע, אבל המצות נק' צדקה כמ\"ש וצדקה<sup data-n=\"494\">110</sup> תהי' לנו כי נשמור כו' וכן לעשות<sup data-n=\"495\">111</sup> צדקה ומשפט כמו הצדקה ליתן לעני כו' דכתיב אשרי<sup data-n=\"496\">112</sup> משכיל אל דל כו' וכן המצות מעלין כל העלאו' רפ\"ח כו' שנק' דל כמ\"ש מקימי<sup data-n=\"497\">113</sup> מעפר דל כו'. וזהו וגבעות בצדקה שהן המצות שנק' גבעות בחי' מקבל מן התורה כמ\"ש והחכ'<sup data-n=\"498\">114</sup> תחי' בעליה כנ\"ל, אך שרשם למעלה מן התורה מפני שהן בחי' או\"ח ונעוץ תחב\"ס כנ\"ל בבחי' האמהות. וזהו ג\"כ מדלג על ההרים בזכות התורה והוא ברגל א' הימני' כנ\"ל באבות ומקפץ על הגבעות בזכות המצות בשתי רגלים כנ\"ל באמהות וד\"ל.\nה) <b>ובכ\"ז</b> יובן בתוס' ביאור מ\"ש קול דודי הנה זה בא כו'. דהנה לכאורה אינו מובן מ\"ש הנה זה בא לשון עתיד דוקא והלא כבר הי' הדילוג הזה ביצי\"מ. אך הענין הוא דכתיב כימי<sup data-n=\"499\">115</sup> צאתך מארץ מצרים אראנו נפלאות דמשמע שיהי' לעתיד ג\"כ בחי' דילוג ההארה מבחי' מל' דא\"ס שנק' מלך מלכי כו' וכמ\"ד כל<sup data-n=\"500\">116</sup> ימי חייך להביא לימוהמ\"ש כו' וזהו כימי צאתך כו' ופי' אראנו נפלאות כי פי' פלא הוא בחי' פנימי'<sup data-n=\"501\">117</sup> אור הכתר שנק' פלא עליון כמ\"ש בפרדס וכן<sup data-n=\"502\">118</sup> במדרש רבה אמון מופלא מכוסה כו' כמו כי<sup data-n=\"503\">119</sup> יפלא ממך כו' לשון הפלאה והעלם להיות כי בחי' מל' דא\"ס למעלה מכל ההשתלשלו' דאבי\"ע שנמשך מבחי' הקו כנ\"ל ונוגע לכולם בשוה ונק' נפלאות שתים לפי שנק' בחי' סתימא דכ\"ס וכמ\"ש עושה<sup data-n=\"504\">120</sup> פלא וכמ\"ש ביאור זה במ\"א באריכות וז\"ש כימי צאתך ממצרים שהי' אז בחי' גילוי מל' דא\"ס עצמו כנ\"ל אראנו למטה בבחי' גילוי גמור לעתיד כמ\"ש ונגלה<sup data-n=\"505\">121</sup> כבוד ה'",[["488","104","<b>או יחזיק במעוזי יעשה שלום לי</b>: ישעי' כז, ה."],["489","105","<b>שלום בפשמ\"ע כו'</b>: סנהדרין צט, ב."],["490","106","<b>ורב שלום</b>: ישעי' נד, יג. וראה ברכות סד, א. ובכ\"מ."],["491","107","<b>שנק' הר אלקים</b>: ראה שמות יח, ה."],["492","108","<b>משה קיבל תורה מסיני</b>: אבות פ\"א מ\"א."],["493","109","<b>ולרב יוסף קראו סיני</b>: ברכות סד, א. ובכ\"מ."],["494","110","<b>וצדקה תהי' לנו כי נשמור</b>: דברים ו, כה."],["495","111","<b>לעשות צדקה ומשפט</b>: בראשית יח, יט."],["496","112","<b>אשרי משכיל אל דל</b>: תהלים מא, ב."],["497","113","<b>מקימי מעפר דל</b>: תהלים קיג, ז."],["498","114","<b>והחכ' תחי' בעליה</b>: קהלת ז, יב."],["499","115","<b>כימי צאתך מארץ מצרים אראנו נפלאות</b>: מיכה ז, טו."],["500","116","<b>כל ימי חייך להביא לימוהמ\"ש</b>: ברכות יב, ב."],["501","117","<b>פנימי' אור הכתר שנק' פלא עליון כמ\"ש בפרדס</b>: ראה פרדס שער ערה\"כ ע' פלא. וראה ת\"ז תי' כ\"א (נט, א). תי' ע' (קלה, א). תקוני ז\"ח צח, ד. ביאוה\"ז להצ\"צ כרך א' ע' תקכז ואילך."],["502","118","<b>וכן במד\"ר אמון מופלא מכוסה</b>: ב\"ר בתחילתו. וראה תו\"ח ח\"ש קלג, ב."],["503","119","<b>כי יפלא ממך</b>: דברים יז, ח."],["504","120","<b>עושה פלא</b>: שמות טו, יא. ועוד."],["505","121","<b>ונגלה כבוד ה' וראו כל בשר</b>: ישעי' מ, ה."]]],[2101000095,"וראו כל בשר כו' עין בעין<sup data-n=\"506\">122</sup> נראה כו' והיינו ע\"י תו\"מ שנק' הרים וגבעות והעיקר הוא בשביל המצות כמ\"ש בצדקה<sup data-n=\"507\">123</sup> תיכונני וכמ\"ש וגבעות בצדקה כנ\"ל והוא ענין מקפץ על הגבעות כנ\"ל רק עכשיו זאת ההארה למעלה בהעלם ולעתיד תתגלה למטה וז\"ש ולא<sup data-n=\"508\">124</sup> יכנף עוד מוריך כמו עכשיו ע\"י המצות שנק' לבוש אלא והיו עיניך רואות כו' וע\"כ אנו מבקשים עכשיו גלה כבוד מלכותך כו' וז\"ש הנה זה בא לעתיד וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ שני הפסוקים שאחר פסוק זה דקול דודי כו' והוא מ\"ש דומה דודי לצבי או לעופר האיילים כו' ענה דודי ואמר לי קומי לך רעייתי כו' דהנה ארז\"ל ע\"פ זה דומה דודי לצבי מה<sup data-n=\"509\">125</sup> צבי מחזיר ראשו לאחוריו כו' פי' משל זה למעלה הנה יובן ע\"ד הנ\"ל בענין תומ\"צ להיות כי שרש המצות הוא בבחי' הכתר שנק' קרקפתא והוא למעלה מבחי' חכ' שנק' מוחא כי הקרקפתא חפיא על מוחא כדמיון הגלגולת באדם שחופפת על המוחין שבתוכה וכך למעלה הנה בחי' חכ' דאצי' שנק' חכים ולא בחכ' ידיעא היא למטה מבחי' הכתר עליון שהוא בחי' רצה\"ע ששורה בבחי' קרקפתא וע\"כ הקרקפתא חפי' על מוחא כו', והנה המצות למטה הן נעשי' בדברים גשמיי' דנוגה כמו צמר דציצית וקלף דתפילין וכיוצא ששרשם רק מבחי' אחוריי' דשם אלקים כידוע אך שרש המצות למעלה הוא בחי' הכתר שהן תר\"ך עמודי אור כנ\"ל ומפני שנעוץ תחב\"ס כנ\"ל ע\"כ אמר כמשל הצבי שמחזיר ראשו לאחוריו כך בחי' ראש העליון שהוא בחי' כתר מחזיר להתמשך למטה לבחי' אחוריו שהן מעשה המצות בפ\"מ ששרשם רק בבחי' אחוריי' דשם ב\"ן כידוע לפי שסוף מעשה עלה במח\"ת כנ\"ל בבחי' האמהות ע\"כ נתלבש רצה\"פ שלמעלה מבחי' חכ' בדברי' גשמיי' דנוגה כו' וז\"ש דומה דודי לצבי כו' אחר שאמר קול דודי הנה זה בא מדלג כו' ששניהם עולה לענין א' וכונה אחת וד\"ל.\n<b>ענה</b> דודי ואמר לי קומי לך רעייתי כו' דהנה ביום א' דפסח הי' בחי' דילוג הנ\"ל שנגלה עליהם מלך מלכי כו' מעצמו ומאליו בלי אתדל\"ת כלל כי לא היו ראויים להעלות מ\"נ באתדל\"ת להיותם משוקעים במצרים וכמ\"ש ואראך<sup data-n=\"510\">126</sup> מתבוססת בדמיך כו' רק שלא הספיק בצקת כו' מפני בחי' התגלות עצמות אא\"ס שלפני ההשתלשלו' כנ\"ל באריכות אבל ביום ב' דפסח ציוה ה' לספור ספירת העומר כמ\"ש ממחרת<sup data-n=\"511\">127</sup> השבת תספרו כו' שהוא בחי' אתדל\"ת דוקא ע\"י בירור הז' מדות רעות דנוגה ששרשם בעומר שעורים מאכל בהמה ובמ\"ט ימים יש העלאה ובירור לנש\"ט שיש בז' מדות רעות ליכלל בנש\"ב דקדושה בכל יום מתברר מדה א' באמרו היום יום כו' וכמ\"ש במ\"א והטעם הוא כי היו צריכים להיות בחי' כלי בית קיבול",[["506","122","<b>עין בעין נראה</b>: ראה במדבר יד, יד."],["507","123","<b>בצדקה תיכונני</b>: ישעי' נד, יד."],["508","124","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["509","125","<b>מה צבי מחזיר ראשו לאחוריו</b>: ראה זח\"ב יד, א. וראה לקו\"ת שה\"ש טו, ד."],["510","126","<b>ואראך מתבוססת בדמיך</b>: יחזקאל טז, ו."],["511","127","<b>ממחרת השבת תספרו</b>: ויקרא כג, טו."]]],[2101000096,"לגילוי אור א\"ס שבזמן מ\"ת דכתיב וירד<sup data-n=\"512\">128</sup> ה' על הר סיני וידבר אלקים כו' אנכי ה' כו' מי שאנכי שהוא סתימו דכל סתימין הנ\"ל וכתיב במ\"ת פב\"פ<sup data-n=\"513\">129</sup> דיבר ה' כו' דמשמע שגם בחי' ומדריגת כנ\"י היו בבחי' פנים הראויים לקבל מבחי' פנים העליונים כמו התלמיד הראוי לקבל המשכת השפע הפנימי' כו' ולא הי' באפשרי אם לא שיטהרו א\"ע בבירור כל ז' מדות רעות כנ\"ל, וע\"כ אמר בחג השבועות בשתי הלחם חמץ<sup data-n=\"514\">130</sup> תאפינה כו' משום דבפסח שהי' הדילוג מעצמו נאסר החמץ מפני שישראל לא נבררו אז עדיין כנ\"ל אבל בשבועות שכבר נבררו מכל סיג ע\"י הספירה שאחר הפסח כנ\"ל ע\"כ ציוה ה' שיאפו לשתי הלחם בחמץ דוקא להעלותו ג\"כ לקדושה העליונה כמ\"ש במ\"א וד\"ל. וזהו ענה דודי פי' אחר שקול דודי זה בא בדילוג בפסח כנ\"ל וכמ\"כ בענין המצות דומה דודי לצבי כנ\"ל אח\"כ ענה דודי לבחי' מל' דאצי' שרש כנ\"י שנק' רעייתי כו' קומי לך פי' שתתעורר מצד עצמך מלמטה למעלה באתדל\"ת דוקא שנק' קימה בבחי' העלאה מלמטה למעלה כדי שתהי' כלי בית קיבול לקבל פב\"פ בזמן מ\"ת, וכמ\"כ ע\"י המצות דעכשיו נזכה לקבל בחי' גילוי דילוג האור הגדול הנ\"ל בבחי' פב\"פ כמ\"ש אראנו נפלאות עין בעין כו' וכנ\"ל וד\"ל.",[["512","128","<b>וירד ה' על הר סיני וגו'</b>: שמות יט, כ ואילך."],["513","129","<b>פב\"פ דיבר ה'</b>: דברים ה, ד."],["514","130","<b>חמץ תאפינה</b>: ויקרא כג, יז."]]],[2101000097,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה ביאור על הנ\"ל</b>\nא) <b>להבין</b><sup data-n=\"515\">1</sup> שרשי הדברי' הנ\"ל, הנה להבין שרש ענין מצה זו שאנו אוכלים ע\"ש שלא הספיק כו' שעדיין לא ניתרצה הקושי' הגדולה הנ\"ל, הנה תחלה יש להקדים שרש ענין חג הפסח מהו ומהו ההפרש בין שאר יו\"ט לחג הפסח, דהנה כתיב ואמרתם<sup data-n=\"516\">2</sup> זבח פסח הוא אשר פסח ה' וכן ופסח<sup data-n=\"517\">3</sup> ה' על הפתח כו' וי\"ל מהו ענין פסיחה זו ולמה על הפתח דוקא. אך הנה עיקר ההפרש בין חג הפסח לשאר המועדים כחג השבועות וחג הסוכות שכל הרגלים הן בחי' עליות העולמות מלמטה למעלה בבחי' העלאת מ\"נ ועי\"ז נמשך אתדל\"ע מלמעלה למטה הנק' המשכת מ\"ד כמו מו' יומין דחול לשבת שגם הוא ענין העלאה מלמטה למעלה בבחי' הבירורי' דרפ\"ח כו' בכל ו' ימי המעשה כידוע בענין ל\"ט מלאכות חורש וזורע ואח\"כ בליל שבת נאמר כי<sup data-n=\"518\">4</sup> בו שבת מכל מלאכתו בבחי' ההעלאה כללית וביום השבת נמשך עי\"ז תוס' אור עליון מלמעלה למטה כו' וכך בכל יו\"ט יש בחי' עליות באתדל\"ת",[["515","1","<b>להבין שרשי הדברים</b>: חלק מביאור זה (אות א' וקטע מאות ב') נדפס בתוס' הגהות באוה\"ת שה\"ש ע' רנח. וראה גם סה\"מ אעת\"ר ע' סו ואילך."],["516","2","<b>ואמרתם זבח פסח הוא</b>: ראה שמות יב, כז."],["517","3","<b>ופסח ה' על הפתח</b>: שמות יב, כג."],["518","4","<b>כי בו שבת מכל מלאכתו</b>: בראשית ב, ג. וראה לעיל ד\"ה זכור את יום השבת."]]],[2101000098,"תחלה ועי\"ז נמשך בחי' תוס' גילוי אור עליון מלמעלה למטה כמו בחג השבועות שנמשך ונתגלה בחי' אור הכתר דאנכי כו' ע\"י העלאת מ\"נ כל ימי הספירה באמרו היום יום כו' וע\"י שמקריבין העומר כידוע וכן בסוכות מתגלה מבחי' מקיפים דכתר וכמ\"ש<sup data-n=\"519\">5</sup> וימינו תחבקני ע\"י העלאת מ\"נ בעשי\"ת כו' ובפרט ביו\"כ עצמו שיש עלי' כללית בנעילה ע\"י העלאת מ\"נ דעי\"ת וע\"י ה' תפלות וה' עינויים כו' וכיוצא בזה הרי מובן עכ\"פ שאינו נמשך תוס' גילוי אור עליון מלמעלה רק בסיבת ההעלאה בתחלה וא\"כ מוכרח שלפי ערך ההעלאה דוקא יהי' ערך ההמשכה וכמשל תלמיד המחכים את רבו שלפי אופן שאלתו כך יהי' אופן תשובתו וכמ\"כ כתיב ימלא<sup data-n=\"520\">6</sup> ה' כל משאלותינו בהעלאת מ\"נ וכן יענינו<sup data-n=\"521\">7</sup> ביום קראינו וכידוע, וזה ידוע שיש בבחי' העלאת מ\"נ באתדל\"ת כמה חילוקי מדריגו' שונות וכך יהי' חילוקי מדריגות שונות בבחי' המשכות מ\"ד, ומאחר שנמשך רק לפי אופן מדריגת ההעלאה א\"כ יבא ערך הגילוי מלמעלה לכל א' כפי מדריגת העלאתו, ולזה הטעם יש בכל יו\"ט בחי' גילוי אלקות בכ\"א מישראל לפי אופן מדריגתו דהיינו לפי אופן שרש העלאת נשמתו ולכך נק' מועדי<sup data-n=\"522\">8</sup> הוי' שנודע ונגלה לכל חד לפום שיעורי' דילי' כמ\"ש נודע<sup data-n=\"523\">9</sup> בשערים כו', אך הנה חג הפסח מובדל משאר המועדי' שאין בחי' תוס' גילוי אור א\"ס באבי\"ע עד נשמ\"י באה ע\"י העלאת מ\"נ לפי ערך ההעלאה כשאר המועדי' אלא נמשך בחי' גילוי אא\"ס מצד עצמו כי חפץ חסד הוא ולא מצד אתעדל\"ת בהעלאת מ\"נ כלל והוא הנק' בחי' דילוג שלא בהדרגה, כי האור הנמשך ע\"י ההעלאה הוא בא בהדרגה אבל האור הנמשך שלא ע\"י ההעלאה נמשך שלא בהדרגה הנק' דילוג, וביאור הענין הוא כי זה האור אשר בא מצד עצמו' אא\"ס הנה הוא בא ממקום ומדריגה היותר עליונה שלמעלה מבחי' המשכה הבאה בסדר ההשתלשלו' מעילה לעילה דהיינו שבא מבחי' עצמותו ממש שלמעלה מהיות מקור למקבלי' לגמרי עד דאצי' ועשי' שוין לגבי' וגם<sup data-n=\"524\">10</sup> חושך לא יחשיך כו' כי<sup data-n=\"525\">11</sup> חשיכה ואורה שוין כו' וע\"כ נק' דילוג להיותו למעלה מסדר והדרגת השתלשלו' דאבי\"ע.\n<b>אך</b> י\"ל הטעם לבחי' דילוג זה למה נמשך אור עליון כזה שאינו בגדר השתלשלו' בהדרגה מעילה לעילה כו', הענין הוא לפי שע\"י אתדל\"ת דוקא יוכל לבא אא\"ס בהדרגת ההשתלשלו' אבל בזמן שהיו ישראל בגלות מצרים היו משועבדי' בעמקי הקליפות בנש\"ט דקליפת מצרים כידוע ולא הי' ביכולתם להעלות מ\"נ מצד עצמם כלל<sup data-n=\"526\">12</sup> כי היו מושקעי' ומובלעי' מאד בנש\"ט וע\"כ הוצרך להיות בחי' גילוי אא\"ס שלמעלה מאור הנמשך בסדר והדרגה כי ע\"י אור כזה הנמשך בהדרגה לא הי' ביכולת להוציאם ולהעלותם משם אחר שאינו מתגלה רק אחר ההעלאה ולהם לא הי' ביכולת להתעלות כנ\"ל אבל ע\"י בחי' גילוי אא\"ס שבעצמותו שלמעלה מסדר",[["519","5","<b>וכמ\"ש וימינו תחבקני</b>: שה\"ש ב, ו. וראה לקו\"ת נצבים מח, ג. ובכ\"מ."],["520","6","<b>ימלא ה' כל משאלותינו</b>: ראה תהלים כ, ו."],["521","7","<b>יעננו ביום קראנו</b>: תהלים כ, י."],["522","8","<b>מועדי ה'</b>: ויקרא כג, ב ואילך."],["523","9","<b>נודע בשערים</b>: משלי לא, כג. וראה זח\"א קג, א."],["524","10","<b>וגם חושך לא יחשיך</b>: ראה תהלים קלט, יב."],["525","11","<b>כי</b>: בכת\"י ב וכת\"י ג: כו'."],["526","12","<b>כלל</b>: בכת\"י ב וכת\"י ג: כנ\"ל."]]],[2101000099,"השתלשלות כנ\"ל הרי גם חושך לא יחשיך לפניו כנ\"ל דקמי' כחשיכה כאורה וגם רוחניות כגשמיות שוין כמו אצי' ועשי' כנ\"ל וע\"י נתעלו ויצאו מנש\"ט, וזהו הכלל שכל אור היותר עליון יכול יותר להשפיל א\"ע עד למטה ביותר גם שלא לפי ערך ההעלאה דהיינו גם בלא אתדל\"ת כלל ובבחי' אור זה הכל שוין קטן וגדול וכמארז\"ל ראתה<sup data-n=\"527\">13</sup> שפחה על הים כו' מאחר שאינו בא בכל חד לפום שעו\"ד להיותו אינו בערך הדרגה שיבא לפי ערך ההעלאה כנ\"ל וע\"כ כולם קיבלו בנפשם בחי' גילוי זה בהשוואה וכמ\"ש בע\"ח דבחי' מל' דא\"ס הוא בחי' מקיף הכללי להקיף כל ההשתלשלו' דאבי\"ע ונוגע לכולם בהשוואה א' כו' וד\"ל.\n<b>וזהו</b> שארז\"ל ובמורא<sup data-n=\"528\">14</sup> גדול זו גילוי שכינה פי' גילוי שכינה הוא בחי' מל' דא\"ס עצמו שלמעלה מבחי' הקו\"ח שיורד בהדרגה באצי' כו' ונק' גילוי שכינה להיותו בחי' התגלות עצמות הא\"ס וע\"כ נק' מורא גדול דוקא כי ידוע דכל יראה הוא בחי' התגלות אור ואמנם בחי' מקור כל התגלות אור שבא בקו הנ\"ל דהיינו בהי' מל' דא\"ס עצמו קודם הצמצום הנק' מקו\"פ כו' נק' מורא גדול מפני שכולל כל מיני יראה ועד\"מ מלך גדול שאימתו כוללת ריבוי מיני יראה ופחד לפי שאימתו גדולה מאד והיינו דוקא כאשר הוא מתגלה כמו שהוא בעצמו' רוממותו משא\"כ כשאינו מתגלה רק אפס קצה גדולתו כו' שאז היראה היא חלק מצומצם לפי אופן הגילוי הזה ואינו נק' מורא גדול אלא כשמתגלה כמו שהוא גדול בעצמותו כו' וכך בחי' מל' דא\"ס עצמו דוקא נק' מורא גדול לפי שהוא התגלות גדולת עצמות הא\"ס ולכך נק' גילוי שכינה, ובבחי' גילוי אור זה הגדול דוקא שנק' מורא גדול וגילוי שכינה הוא שהי' ביכולת להאיר לכללות נש\"י גם בהיותם משוקעים בנש\"ט בתכלית החושך לפי שגם חושך כו' כנ\"ל, וכמשל הידוע בעיגול הכדורי שאין בו מעלה ומטה ועליונו ותחתיתו שוה רק מצד הקו העובר מעליונו לתחתיתו יש מעלה ומטה כו', וכך מצד מל' דא\"ס שנק' כתר ומקיף הכללי להקיף כל ההשתלשלו' דאבי\"ע שע\"י הקו הנ\"ל הכל שוין אור היותר עליון שבהשתלשלות הקו עם קציהו התחתון ביותר וכמ\"ש ומתחת זרועות עולם דהיינו גם חושך הקליפות דנש\"ט וכמ\"ש אציעה<sup data-n=\"529\">15</sup> שאול הנך כו' רק מצד בחי' הקו הנ\"ל יש מעלה ומטה, אבל בחג הפסח הי' בחי' דילוג שהוא המשכת אור א\"ס מלפני הקו הנ\"ל שאין שם מעלה ומטה כלל אלא נוגע לכולם בשוה כנ\"ל וד\"ל. וזהו ג\"כ שרש ענין מארז\"ל עד<sup data-n=\"530\">16</sup> שלא נבה\"ע הי' הוא ושמו בלבד פי' הוא היינו עצמות הא\"ס ושמו הוא בחי' גילוי עצמותו ממש שנאמר גם בו אני<sup data-n=\"531\">17</sup> ה' לא שניתי כמבואר למעלה והיינו בחי' מל' דא\"ס שלפני הקו כנ\"ל (ומ\"ש קודם שנברא ה\"ה<sup data-n=\"532\">18</sup> קודם שנאצל כי ד' עולמות אצי' ובריאה כו' נמשכו כולם מבחי' הקו הנ\"ל בסדר השתלשלות כידוע).",[["527","13","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. זח\"ב סד, ב. צד, א. זח\"ג כב, ב."],["528","14","<b>ובמורא גדול זו גילוי שכינה</b>: נוסח ההגדה."],["529","15","<b>אציעה שאול הנך</b>: תהלים קלט, ח."],["530","16","<b>עד שלא נבה\"ע הי' הוא ושמו בלבד</b>: פדר\"א פ\"ג. וראה סה\"מ באתי לגני ח\"א ע' כד וע' ר. אוה\"ת יתרו ע' תתלט."],["531","17","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["532","18","<b>ה\"ה</b>: בכת\"י ג: הפי'."]]],[2101000100,"<b>ובכ\"ז</b> מובן ג\"כ שרש ענין מארז\"ל עד שנגלה עליהם ממ\"ה הקב\"ה וגאלם כו' פי' מלך מה\"מ הוא בחי' מל' דא\"ס שלפני הקו הנ\"ל, ומה שנק' מלך מלכי המלכי' דמשמע שיש הרבה בחי' מלכיות והוא נק' מלך על הכל כו' הענין הוא כי ידוע בסדר ההשתלשלות דכל בחי' מל' שבעליון נעשה כתר לתחתון בכל עו\"ע כמו מכתר לחכ' ומחכ' לבינה כו' ועד\"ז דרך כלל מפרצוף עליון לתחתון הימנו כמו מבחי' מל' דא\"ק נעשה כתר לע\"י וא\"א ומבחי' ע\"י וא\"א נמשך בחי' מל' להיות כתר לאו\"א<sup data-n=\"533\">19</sup> כו' עד ממל' דאצי' נעשה כתר לבריאה וממל' דבריאה נעשה כתר ליצי' וממל' דיצי' נעשה כתר לעשי', וזהו דרך פרטות אבל דרך כללות ד' מלכיות הן מל' דאצי' מל' דבריאה מל' דיצי' מל' דעשי' והן נק' מלכים ומלכי המלכים הן בחי' או\"א ומלך מלכי כו' הוא בחי' הכתר לנאצלים שבו שורה בחי' מל' דא\"ס וע\"כ נק' מלך מלכי המלכים (והרי ידוע שיש ג' מדריגות בי\"ע גם באצי' ולפני האצי' והוא ג' מדריגו' מלך מלכי המלכים) וכללות הכל מל' דא\"ס שהוא פנימי' הכתר וכמ\"ש בתיקונים <sup data-n=\"534\">20</sup> אא\"ס מלגיו כתרא עילאה מלבר כו' (ומ\"ש ב' דברים מלך מלכי כו' הקב\"ה הכל ענין א' שהוא מל' דא\"ס שנק' קדוש כמו עצמות הא\"ס כמאמר אתה קדוש ושמך קדוש וכמאמר הנ\"ל דהי' הוא ושמו בלבד כו').\n<b>והנה</b> כאשר נגלה עליהם מלך מלכי המלכים שהוא בחי' מל' דא\"ס הוא הנק' בחי' דילוג להיותו למעלה מבחי' הדרגת ההשתלשלות כנ\"ל וזהו שרש ענין חג הפסח כמ\"ש ואמרתם זבח פסח הוא אשר פסח ה' כו' בפסיחה ודילוג וכמ\"ש קול דודי הנה זה בא מדלג על ההרים כו' כמבואר למעלה וד\"ל. ומ\"ש ופסח ה' על הפתח ענין הפסיחה הזאת כבר מבואר אך למה על הפתח דוקא הנה יובן בהקדים מ\"ש זה<sup data-n=\"535\">21</sup> השער להוי' ואמרו<sup data-n=\"536\">22</sup> בזוהר דא תרעא לאעלאה כו' כמ\"ש בזאת<sup data-n=\"537\">23</sup> יבא אהרן בזאת<sup data-n=\"538\">24</sup> דוקא וכמ\"ש בזוהר בכמה דוכתי, והענין הוא שהמל' נק' פתח ושער להוי' וכמ\"ש<sup data-n=\"539\">25</sup> בזוהר ע\"פ ותשב בפתח עינים וכן<sup data-n=\"540\">26</sup> והוא יושב פתח האוהל כו' לפי שכמו הפתח והשער הוא מקום שבו יצאו אנשים שבפנים לחוץ ובו יכנסו אנשים שבחוץ לפנים והכל יכולים ליכנס והכל יכולים לצאת אך לא כל מי שחפץ ליכנס יכנס אלא הראוי לכך ולא כל מי שרוצה לצאת כ\"א ברשות כו' וכך יובן בדוגמא למשכיל למעלה שבחי' מל' דאצי' נק' פתח ושער להוי' לפי שכל הנשמות ומלאכים בע\"ג שבחוץ עולין בבחי' העלאת מ\"נ דרך השער ההוא לבחי' שם הוי' דאצי' לאשתאבא<sup data-n=\"541\">27</sup> בגופא דמלכא כו' או ליכנס לבחי' היכלות דאצי' כו' וסדר העליות יש",[["533","19","<b>לאו\"א</b>: בכת\"י ב וכת\"י ג: לאו\"א ומאו\"א לזו\"נ."],["534","20","<b>וכמ\"ש בתיקונים אוא\"ס מלגאיו כתרא עלאה מלבר</b>: ת\"ז סוף תי' כב."],["535","21","<b>זה השער לה'</b>: תהלים קיח, כ."],["536","22","<b>ואמרו בזוהר דא תרעא לאעלאה</b>: ראה זח\"א יא, ב. זח\"ג רנג, ב."],["537","23","<b>בזאת יבא אהרן</b>: ויקרא טז, ג."],["538","24","<b>בזאת דוקא וכמ\"ש בזוהר בכמה דוכתי</b>: זח\"ג נו, ב."],["539","25","<b>וכמ\"ש בזוהר ע\"פ ותשב בפתח עינים</b>: ראה זח\"ג עא, ב. ובכ\"מ."],["540","26","<b>וכן והוא יושב פתח האוהל</b>: בראשית יח, א."],["541","27","<b>לאשתאבא בגופא דמלכא</b>: זח\"א ריז, א."]]],[2101000101,"בהן פרטים רבים כי עליות הנשמות ומלאכים דעשי'<sup data-n=\"542\">28</sup> עולין בפתח ושער שהוא מל' דעשי' ועד\"ז נשמות ומלאכים דיצי'<sup data-n=\"543\">29</sup> עולין בפתח ושער שהוא מל' דיצי' וכן מבריאה לאצי' עולין דרך פתח ושער דהיינו מל' דבריא' ומלאכים ונשמות שבבחי' אצי' כו' (שהוא אצי' שבבריאה) עולין דרך מל' דאצי' להוי' שהוא ז\"א כו' ועד\"ז יש עליות עד רום המעלות אך כל עלי' הוא דרך פתח ושער דוקא שהוא בחי' מל' שבעולם ההוא ועד\"ז כל בחי' ירידה והמשכה מעליון לתחתון ג\"כ דרך הפתח והשער כו' (כמ\"ש שאו שערים והנשאו<sup data-n=\"544\">30</sup> פתחי עולם ויבא מלך הכבוד כו') (וז\"ש בזאת יבא אהרן כו') ועד\"ז הולך ונמשך אור העליון מעילה לעילה מגבוה לנמוך הכל ע\"י פתחים, ובכלל בחי' מל' דאצי' הוא בחי' פתח כללי ונק' פתח האהל כו', אך בזמן יצי\"מ כתיב ופסח ה' על הפתח שהי' בחי' דילוג על הפתח דהיינו בחי' הארת מל' דא\"ס שהי' מאיר גם למטה כמו למעלה כנ\"ל שא\"א שיהי' זה בא מלמעלה דרך הפתח שהוא בחי' המל' אלא בדילוג ופסיחה על הפתח דהיינו שיהיו יכולים הכל לעלות גם העומדי' למטה בתחתית המדריגה כמו נשמות ישראל אז שהיו משוקעים במצרים שנק' ערות הארץ ודביקים בנש\"ט וכמ\"ש<sup data-n=\"545\">31</sup> ביחזקאל הנגלה<sup data-n=\"546\">32</sup> נגלתי לבית אביך במצרים כו' אביך<sup data-n=\"547\">33</sup> האמורי ואמך חיתית כו' כידוע שאהרן הי' מוכיחם תמיד בעודם בגלות כידוע, וע\"כ נק' יציאת מצרים שיצא מן המיצר והגבול כו', ולמעלה היינו יציאת האור מן הכלי המגבילה והיינו ע\"י הארת מל' דא\"ס שלפני הקו כנ\"ל שלמעלה מבחי' ירידת אור בהדרגה בכלים מכלים שונים כנ\"ל וד\"ל. ובכ\"ז מובן ג\"כ מה שארז\"ל אני ולא מלאך וכו' פי' כי מלאכים ושרפים הן בחי' אורו' הנמשכים ובאים בסדר השתלשלות מבחי' הקו הנ\"ל כי ידוע דג' מדריגות הן בי\"ע בכל עולם ועולם עד רם המעלות (ודרך כללות א\"ק נק' אדם דבריאה וע\"י וא\"א נק' אדם דיצי' כו' והוא כללות כל הקו כידוע) וזהו מלאך ושרף ושליח, מלאך בבחי' עשי' ושרף בבחי' יצי' ושליח בבחי' בריאה, ולהיות כי ביצי\"מ הי' בחי' דילוג אור עליון מבחי' עצמות אא\"ס שלפני הקו ע\"כ אמר ועברתי בארץ מצרים אני ולא מלאך כו' אני הוא בחי' מל' דא\"ס שנק' מלך מלכי המלכים כו' שלמעלה מג' מדריגות בי\"ע שבקו\"ח שנק' מלך ושרף ושליח כו' אלא הקב\"ה בכבודו ובעצמו פי' כבודו הוא בחי' זיו יקרי' בלבד דהיינו גילוי אא\"ס כמ\"ש מלכותך<sup data-n=\"548\">34</sup> כו' וכנ\"ל ובעצמו היינו עצמו' א\"ס ולפי שהוא ושמו בלבד קודם שנאצל כו' כנ\"ל ע\"כ אמר לשון הקב\"ה גם על בחי' האור כו' וכמו שאו' אתה קדוש ושמך קדוש כו' כנ\"ל וד\"ל.",[["542","28","<b>דעשי'</b>: בכת\"י ב וכת\"י ג: דעשי' ליכנס ולהכלל ביצי'."],["543","29","<b>דיצי'</b>: בכת\"י ב וכת\"י ג: ליכנס ולהכלל בבריאה."],["544","30","<b>שאו שערים והנשאו פתחי עולם</b>: ראה תהלים כד, ז."],["545","31","<b>וכמ\"ש ביחזקאל הנגלה נגליתי</b>: כ\"ה בהכת\"י. וכנראה כוונתו להפסוק אביך האמורי כו'."],["546","32","<b>הנגלה נגליתי לבית אביך במצרים</b>: ראה שמואל-א ב, כז. ובפירש\"י שם. וראה פירש\"י שמות ד, י. ומדרשים שם."],["547","33","<b>אביך האמורי ואמך חתית כו'</b>: ראה יחזקאל קאפיטל טז ואילך ומפרשים שם."],["548","34","<b>מלכותך כו'</b>: תהלים קמה, יג."]]],[2101000102,"ב) <b>ומעתה</b> י\"ל שרש ענין בחי' מצה ומהו ענין ב' המצות הנ\"ל שלפני חצות ושלאחר חצות כו'. הנה תיבת מצה בה\"א מורה על בחי' המל' שהוא בחי' ה\"א אחרונה דשם הוי' אך הנה ידוע דכל ה\"א המילוי שלה ג\"כ אות ה\"א<sup data-n=\"549\">36</sup> כזה ה\"ה (כמו שם ס\"ג שהוא במילוי הה\"א<sup data-n=\"550\">35</sup> כידוע) וידוע דכל מילוי הוא בא בבחי' ההעלם דוקא וכמו מילוי דיו\"ד אותיות ו\"ד שבו הן בהעלם כי עצם היו\"ד אינו אלא נקודה א' רק כשצריך לפרש אותו צריך לומר גם אותיות ו\"ד וכך הה' השנית הבאה במילוי באות הה' היא באה בהעלם כי עצם אות הה\"א אינו אלא אות ה\"א ולא שתים וכך יובן למעלה דבבחי' אות ה' דמל' דאצי' כמ\"ש בהבראם<sup data-n=\"551\">37</sup> בה' בראם כו' כידוע הנה ודאי יש בה בהעלם אות ה\"א שנית והיינו בחי' מל' דא\"ס שנק' ה\"א ג\"כ לגבי עצמות א\"ס כנ\"ל שנק' שמו בבחי' התגלות בלבד אך בחי' מל' דא\"ס הוא מאיר רק בהעלם על כל העולמות בבחי' מקיף ומפני שנעוץ תחב\"ס דוקא כידוע לפי שסוף מעשה דוקא עלה במח\"ת ע\"כ דוקא בה' אחרונה דשם הוי' שהוא בחי' מל' דאצי' שמה שוכן בהעלם בחי' מל' דא\"ס דהיינו ה' השנית שהוא בחי' המילוי דה' ה\"ה כנ\"ל וד\"ל<sup data-n=\"552\">38</sup>.\n<b>ולהבין</b> ביאור זה הנה ידוע שיש ב' מיני יראה הא' נק' יראה עילאה והוא בחי' מל' דא\"ס שנק' מורא גדול כנ\"ל והב' בחי' יראה תתאה שהוא בחי' מל' דאצי' (וע\"כ נק' המל' כתר מל' לפי שנעוץ תחב\"ס יראה עילאה ביראה תתאה כו') והענין הוא כי הנה בחי' יראה תתאה הוא רק בחי' ביטול היש בלבד בבחי' אתכפי' ואתהפכ' כו' כמו שום<sup data-n=\"553\">39</sup> תשים עליך מלך להיות עושה בנפשו בחי' ביטול היש ע\"י קבלת מ\"ש מפני ההתבוננו' ביחו\"ע ויחו\"ת כידוע, אך אין זה בחי' ביטל אמיתי מכל וכל שהרי במעט רגע חוזר לבחי' התפשטו' יש נפרד כשכלה כח קבלתו בנפשו ע\"י היסח הדעת או ע\"י שמתנשא בלבבו בגסות הרוח וחוצפא מעניני' הגשמיי' שהוא הגבהת והתנשאות דקליפה כו' שנק' חמץ כמשי\"ת, אבל בחי' יראה עילאה הוא בחי' ביטול האמיתי שנעשה בנפש האדם מלמעלה ולא מצד עצמו והיינו ע\"י בחי' גילוי אא\"ס מלמעלה מכפי המדה והצמצום הבאה בהשתלשלות כנ\"ל שנק' מורא גדול זו גילוי שכינה שהוא בחי' מל' דא\"ס עצמו שנק' מלך מלכי המלכים כנ\"ל ולביטול זה אין צריך הכנת אדם כלל רק מאליו בא עד\"מ הנכנס לפני מלך גדול שיש כאן ב' יראות הא' כשמכין א\"ע לכנס ועדיין לא נכנס שעושה בנפשו יראה וביטול לפי ההתבוננות שלו ברוממות המלך ואימתו כו' ונק' ביטול היש שנעשה מצד עצמו אבל כאשר כבר נכנס שרואה את המלך הנה אימת המלך מתפשטת עליו עד שמתבטל ביטול אמיתי שא\"א לו לבא לבחי' התפשטות כלל כו' (אך עכ\"ז הכנת ביטול היש שלפני הכניסה גורמת שיקבל האימה מן המלך בתוס' יותר כו') וכנ\"ל בענין מורא גדול שתלוי' לפי עצמות<sup data-n=\"554\">40</sup> רוממות המלך. והנה בחי' יראה ואימה זאת המתפשטת",[["549","36","<b>אות ה\"א</b>: באוה\"ת שם: אות ה' א'."],["550","35","<b>הה\"א</b>: בכת\"י ב וכת\"י ג: ההי\"ן."],["551","37","<b>בהבראם בה' בראם</b>: מנחות כט, ב. ב\"ר פי\"ב, ב. ובכ\"מ. וראה לקו\"ת ר\"פ פקודי ובכ\"מ."],["552","38","<b>וד\"ל</b>: ע\"כ נדפס באוה\"ת."],["553","39","<b>שום תשים עליך מלך</b>: דברים יז, ט."],["554","40","<b>לפי עצמות</b>: בכת\"י ב: לפי ערך."]]],[2101000103,"מן המלך נק' מורא ל' זכר ולא יראה ל' נוק' אך האדם המקבלה בנפשו הוא בחי' נוק' כו' וז\"ש במורא גדול ל' זכר אך המקבל ממורא גדול זה הוא בחי' נוק' והוא בחי' גילוי שכינה הנגלה במקבלי' דוקא והיינו הארת מל' דא\"ס הנגלה למטה שנק' יראה עילאה ל' נוק' וכמארז\"ל שנגלה עליהם מלך מלכי כו' וד\"ל.\n<b>והנה</b> בחי' מל' דא\"ס שנגלה עליהם אחר חצות לילה וגאלם ממצרים נש\"ט כו' כמו שאמר נגלה עליהם מלך כו' וגאלם ממש הוא בחי' יראה עילאה שקיבלו בנפשם מבחי' מורא גדול הנ\"ל שלמעלה מכל ההשתלשלו' דאבי\"ע וע\"כ גם הקליפות שנק' חושך לא יחשיך כו' וכנ\"ל בפי' ועברתי בארץ מצרים אני ולא מלאך כו' והוא בחי' המצה שאכלו אחר חצות בדרך כמ\"ש ויאפו<sup data-n=\"555\">41</sup> את הבצק אשר הוציאו כו' וכנ\"ל, אך לא הי' ביכולתם לקבל בחי' יראה עילאה זו מבחי' מל' דא\"ס אם לא שהכינו בנפשם תחלה קודם חצות בחי' יראה תתאה שהוא קבלת מ\"ש בביטול היש מצד אתדל\"ת כנ\"ל (וכפי משל הנ\"ל דאימה שעושין בנפשו קודם כניסתו לפני המלך היא הכנה שיקבל אימת המלך בעצמו כו'), והגם שמבואר למעלה דגילוי שכינה ממלך מלכי כו' הי' שלא ע\"י אתדל\"ת כלל וכלל אך מ\"מ הי' תחלה איזה הכנה רק שיוכלו לקבל בחי' גילוי שכינה בבחי' יראה עילאה הנ\"ל והוא ענין המצה שאכלו עם הפסח קודם חצות כו' וד\"ל.\n<b>וזהו</b> שארז\"ל על בחי' מצה השנית שלאחר חצות שלא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם כו' דהנה במצה אין בה טעם כלל ונק' לחם עוני ובזהר<sup data-n=\"556\">42</sup> אמר שנק' מיכלא דהימנותא פי' כמו<sup data-n=\"557\">43</sup> התינוק שאינו יודע לקרות אבא עד שיטעום טעם דגן והיינו שאינו מכיר לאביו לקרותו אבא ולמשוך אחריו אלא לאחר שיטעום טעם לחם שאז יש בו דעת ושכל להכיר אביו גם שאינו משיג בהסבר דברים איך שהולידו וכיוצא מ\"מ מכירו שהוא אביו עכ\"פ וקודם שיטעום לחם אינו מכירו כך ע\"י המצה נעשה בנה\"א בחי' ההכרה להכיר את בוראו בבחי' ביטול היינו בחי' ביטול היש הנ\"ל באתכפי' ואתהפכא כו' אך צריך שימור תמיד שלא יחזור להיות יש ודבר כנ\"ל ולכך המצה נק' לחם עוני בעניות ושפלות בלתי הגבהה והתנשאות כשאור וחמץ שהוא בחי' הגבהת הקליפה כמ\"ש אם<sup data-n=\"558\">44</sup> תגביהי כנשר בחוצפא<sup data-n=\"559\">45</sup> שנק' מלכותא בלא תגא כו' וגם שלא להיות יש מי שאוהב כו' אלא רק בטל<sup data-n=\"560\">46</sup> רצונך מפני רצונו בלבד כידוע ולכן נק' מצה בה\"א שהוא בחי' מל' שנק' יראה תתאה כנ\"ל וז\"ש ושמרתם<sup data-n=\"561\">47</sup> את המצות כו', אבל מצה הב' שלאחר חצות הוא בחי' מילוי ה' השנית שבמצה שלפני חצות והיינו בחי' יראה עילאה דמל' דא\"ס שנמשך מצד כח עצמות אא\"ס שנק' מורא גדול ל' דכר כו' שהוא בחי' ביטול אמיתי שלא יוכל לבא לבחי' יש",[["555","41","<b>ויאפו את הבצק אשר הוציאו</b>: שמות יב, לט."],["556","42","<b>ובזהר אמר שנק' מיכלא דמהימנותא</b>: זח\"ב מא, א. וראה דרמ\"צ כב, ב."],["557","43","<b>כמו התינוק שאינו יודע לקרות אבא</b>: ברכות מ, ב."],["558","44","<b>אם תגביהי כנשר</b>: עובדי' פסוק ד."],["559","45","<b>בחוצפא שנק' מלכותא בלא תגא</b>: סנהדרין קה, א."],["560","46","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב מ\"ד."],["561","47","<b>ושמרתם את המצות</b>: שמות יב, יז."]]],[2101000104,"כלל כנ\"ל באריכות וע\"ז אמרו שלא הספיק בצקת של אבותינו להחמיץ פי' שלא הספיק לבא לבחי' יש ודבר בהתנשאות דשאור וחמץ דקליפה מפני שנפל עליהם יראה עילאה ובחי' מורא גדול דעצמות א\"ס כו' והיינו שנגלה עליהם מלך מלכי כו' וגאלם מן הקליפות כי גם חושך לא יחשיך כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> מובן ביאור ענין מילוי ה' הב' שבה' דמצה שהוא בחי' מל' דא\"ס שנק' יראה עילאה וה' הזאת באה בהעלם כמ\"ש שנגלה עליהם כו' דוקא אחר גילוי יראה תתאה בתחלה שהוא ה' דמצה הראשונה כנ\"ל והוא ענין ב' המצות הנ\"ל מצה שלפני חצות הוא בחי' יראה תתאה עלמא דאתגלי' ביטול היש שצריכה שימור כנ\"ל ומצה הב' שלאחר חצות א\"צ שימור כלל והוא מצה הנילושה ביין ושמן ודבש שמבחי' עלמא דאתכסי' כו' שנק' מצה עשירה כו'. וביאור הענין הנה יש להקדי' תחלה שרש ענין הלחם מהו דהנה לחם בגי' ע\"ח והוא בגי' במזלא כמארז\"ל בני<sup data-n=\"562\">48</sup> חיי ומזונא לאו במזלא תלי' והוא גי' הוי' ג\"פ כו' שעולה ע\"ח כמספר לחם ומזלא כידוע, ופי' מזלא ל' מפעיל שמזיל וממשיך מן ההעלם לגילוי דוקא וכמו מזל ונוצר<sup data-n=\"563\">49</sup> חסד לאלפים שהוא בחי' מזל הח' דא\"א שלפני האצי' שנק' צינור הממשיך מבחי' ההעלם שלפני האצי' לעולם האצי' ומתחלק לאלפים מדריגות והיינו פי' ונוצר<sup data-n=\"564\">50</sup> אותיות צנור שהן צינורות השפע המתחלק לאלפים כו' וע\"כ יש בכח הלחם שנמשך מבחי' מזלא לסעוד את הלב ולהחזיק כח השכל יותר משאר מין כמו פירות ובשר גם שטעמן מרובה יותר מן הלחם כי שרשו למעלה מן החכ' דהיינו בבחי' הכתר שהוא מזלא דא\"א שהחכ' נמשך משם וכמ\"ש והחכ'<sup data-n=\"565\">51</sup> מאין תמצא וכמ\"ש<sup data-n=\"566\">52</sup> בע\"ח דאור אבא יונק ממזל הח' ונוצר כו' ולכך אמרו דאין התינוק יודע לקרות אבא דוקא שהוא בחי' החכ' שנק' אב כמ\"ש כי<sup data-n=\"567\">53</sup> אתה אבינו כו' כי ע\"י הלחם יתוסף אור החכ' ויודע לקרות אבא עכ\"פ בבחי' הכרה דדעת כנ\"ל כי ע\"י בחי' הדעת הוא מרגיש ומכיר כו' ובעבודת ה' הוא מ\"ש דע<sup data-n=\"568\">54</sup> את אלקי אביך כו' ושרש הדעת הזה הוא בחי' ד\"ע שבכתר שלמעלה מן החכ' כמ\"ש במ\"א באריכות, אך הנה כשהלחם הוא בחמץ שהוא בחי' הגבהה דקליפה אז נמשך מדעת להרגיש א\"ע לבחי' יש ולכך נק' אכילה גסה כו' וזהו שרש המן מדעת דקליפה כמ\"ש מי<sup data-n=\"569\">55</sup> הגיד לך כי עירום אתה כו' להרגיש א\"ע, ובהיפוך בלא הגבהה כמו מצה נמשך בו דעת עליון בבחי' ביטול היש כמו התינוק שקורא אבא בבחי' ביטול כו' והוא בחי' מצה עשירה שנילושה ביין ושמן ודבש שהן מבחי' עלמא דאתכסי' דהיינו בבחי' ההעלם דכתר שלמעלה מן ההשגה שבחו\"ב שנק' מים כו' והטעם",[["562","48","<b>בני חיי ומזונא לאו במזלא תלי'</b>: ראה מו\"ק כח, א. ובכ\"מ."],["563","49","<b>ונוצר חסד לאלפים</b>: שמות לד, ז."],["564","50","<b>ונוצר אותיות צנור</b>: מק\"מ לזח\"ב קנו, א. וראה הערת כ\"ק אדמו\"ר זי\"ע בתשובות וביאורים סט\"ו."],["565","51","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["566","52","<b>וכמ\"ש בע\"ח דאור אבא יונק ממזל הח'</b>: ע\"ח שער או\"א ספ\"ח. ש' הזווגים ספ\"ב. ש' הולדת או\"א וזו\"ן פ\"ו. ש' העבורים פ\"ב. ש' הנסירה ספ\"ג."],["567","53","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["568","54","<b>דע את אלקי אביך</b>: דה\"א כח, ט."],["569","55","<b>מי הגיד לך כי עירום אתה</b>: בראשית ג, יא."]]],[2101000105,"שנק' מצה עשירה כי בחי' העשירות הוא בדעת כי<sup data-n=\"570\">56</sup>דוע ושרש מצה זו שנילושה ביין ושמן כו' הוא בבחי' דעת עליון שבהעלם הכתר שאינו בא לעולם לבחי' יש וא\"צ שימור כלל שהרי הכתר נק' אין כמ\"ש<sup data-n=\"571\">57</sup> בזוהר ע\"פ היש הוי' בקרבינו אם אין כו', ועל מצה זו שנק' מצה עשירה אמרו שלא הספיק בצקת של אבותינו להחמיץ כו' כי איננו בא לידי חימוץ כלל ומטעם הנ\"ל (ודוגמא לדבר בחי' מ\"ה דמשה שאמר ונחנו מ\"ה<sup data-n=\"572\">58</sup> וכמ\"ש במ\"א).\n<b>ומעתה</b> י\"ל התירוץ הקושי' הנ\"ל איך אנו אומרי' מצה זו שאנו אוכלי' לפני חצות ע\"ש שלא הספיק בצקת כו' שהיא הייתה מצה שלאחר חצות כנ\"ל. דהנה מבואר למעלה בענין ב' מצות הללו שהן ב' יראות יר\"ע ויר\"ת והוא ב' ההי\"ן שבה' דמצה כו' כי תחלה היו צריכים לבחי' יראה תתאה ביטול היש במצה שלפני חצות להיות כמו הכנה כדי שיוכלו לקבל בחי' יראה עילאה במצה הב' שלאחר חצות כו', אך הנה כ\"ז דוקא בזמן שהיו ישראל אז בגלות מצרים שהיו מושרשי' מאד בנש\"ט דקליפת מצרים וגם לא קיבלו עדיין תורה ומצות ע\"כ הוצרכו שיהי' להם הכנה במצה שקודם חצות כדי שיוכלו לקבל הגילוי הגדול דמל' דא\"ס במצה שלאחר חצות אבל לאחר שקיבלו ישראל תורה ומצות בהר סיני וניתנה לנו למורשה כמ\"ש תורה<sup data-n=\"573\">59</sup> ציוה לנו משה מורשה כו' אז א\"צ לבחי' הכנה כלל לקבל לבחי' הגילוי דמל' דא\"ס אלא גם במצה זו שאנו אוכלי' לפני חצות יכולים אנחנו לקבל בחי' גילוי שכינה ממל' דא\"ס שנק' מורא גדול כנ\"ל. והטעם הוא כי הנה שרש<sup data-n=\"574\">60</sup> המצות הוא מבחי' כתר עליון שהן תר\"ך עמודי אור דהיינו תרי\"ג מצות דאוריי' וז' דרבנן כידוע ותר\"ך עמודי' הללו הן בחי' אורות ממוצעים בין עצמות המאציל עם הנאצלים כידוע וא\"כ בכל מצוה שהוא בחי' פנימי' רצה\"ע שבפנימי' הכתר שנק'<sup data-n=\"575\">61</sup> תרי\"ג ארחין דגלגלתא כו' כבר נמשך בחי' גילוי אא\"ס שלפני הקו וכידוע בפי' ועתה<sup data-n=\"576\">62</sup> ישראל מה ה' שואל מעמך כ\"א ליראה כו' וארז\"ל א\"ת מ\"ה אלא מאה והיינו מאה ברכות שחייב אדם לברך בכל יום כו', והענין הוא כי בחי' הכתר כלול מע\"ס וי' פעמים יו\"ד הוא ק' ברכות והיינו ק' המשכות מבחי' מל' דא\"ס שמאיר בפנימית הכתר וגם ע\"י המצות נמשך הארת מל' דא\"ס שבפנימית הכתר, ומה שאמרו א\"ת<sup data-n=\"577\">63</sup> מה אלא מאה כו' הענין הוא כי בחי' יראה תתאה שהוא בחי' מל' דאצי' נק' מה כידוע וא\"ת מה בבחי' יראה תתאה בלבד אלא מאה שהוא בחי' הכתר ששם מאיר מל' דא\"ס שהוא בחי' מילוי דה' בהעלם כנ\"ל לפי שנעוץ תחב\"ס דוקא כנ\"ל.",[["570","56","<b>כי בחי' העשירות הוא בדעת כידוע</b>: ראה נדרים מא, א. ובכ\"מ."],["571","57","<b>כמ\"ש בזוהר ע\"פ היש ה' בקרבנו אם אין</b>: זח\"ב סד, ב."],["572","58","<b>ונחנו מה</b>: שמות טז, ז."],["573","59","<b>תורה ציוה לנו משה מורשה</b>: דברים לג, ד."],["574","60","<b>שרש המצות. . תר\"ך עמודי אור</b>: ראה אגה\"ק סכ\"ט. פרדס ש\"ח פ\"ג."],["575","61","<b>שנק' תרי\"ג ארחין דגלגלתא</b>: ראה זח\"ג קכט, א. ובביאור האריז\"ל שם. מ\"ח מס' א\"א ספ\"ד. ובכ\"מ."],["576","62","<b>ועתה ישראל מה ה\"א שואל מעמך</b>: דברים י, יב."],["577","63","<b>א\"ת מה אלא מאה</b>: מנחות מג, ב (ורש\"י ותוס' שם). זח\"ג קעט, א. ובכ\"מ."]]],[2101000106,"<b>ואמנם</b> אעפ\"י שעיקר הכונה לבחי' מל' דא\"ס אעפ\"כ הרי כל ההמשכות שמן הכתר באין ומתלבשי' בבחי' מל' שנק' מ\"ה כי נעוץ תחב\"ס וכמ\"ש כל<sup data-n=\"578\">64</sup> הנחלים הולכים אל הים כו' וע\"כ אמר מ\"ה ה' אלוקיך שואל מעמך כ\"א ליראה כו' בבחי' יראה תתאה דמל' כמ\"ש בזאת<sup data-n=\"579\">65</sup> יבא אהרן וכן זה<sup data-n=\"580\">66</sup> השער להוי' כו' והיא הכנה לקבל בחי' יראה עילאה דמל' דא\"ס שבכתר והיינו א\"ת מה אלא מאה כו' כנ\"ל וד\"ל, אך בפסח הרי בחי' דילוג ממל' דא\"ס על הפתח שהוא בחי' יראה תתאה דמל' רק שמ\"מ היו צריכים קצת להכנה ביראה תתאה מפני שלא קיבלו עדיין תו\"מ אבל עכשיו שקבלנו תומ\"צ ששרשם במל' דא\"ס שבכתר וכבר כל השנה אנו מקיימים המצות בבחי' קבלת מ\"ש ביראה תתאה בבחי' ביטול היש בטל רצונך מפני רצונו כו' א\"כ אין אנו צריכים לבחי' הכנה זאת כי כבר יש הכנה זו דיר\"ת ע\"י קיום תומ\"צ ששרשם בפנימית הכתר ונעשים בבחי' יר\"ת כמ\"ש מה ה' אלקיך שואל מעמך כו' וכנ\"ל, והגם שהמצות כמו שהן בשרשן בפסח לא נתגלו עדיין למטה רק לעתיד יתגלו כידוע מ\"מ בבחי' ההעלם הארת הכתר הנק' מאה ברכות מאיר בבחי' יראה תתאה דקבלת מ\"ש וא\"כ כבר יש הכנה ולכך אנחנו יכולים לומר מצה זו שאנו אוכלים הגם שהיא רק בחי' יר\"ת לחם עוני כו' שהיא כמו מצה שאכלו אחר חצות שלא הספיק בצקת כו' דהיינו מפני שנגלה בחי' מל' דא\"ס גם במצה שאנו אוכלים לפני חצות כמו שנגלה עליהם במצה שלאחר חצות ע\"י תו\"מ שעסקנו כל השנה (וזהו שאו' מה נשתנה הלילה הזה כו' שבכל השנה ג\"כ אנו אוכלים חמץ ומצה כו' פי' מצה הוא אתדל\"ת ביר\"ת ע\"י מעשה המצות ולמה עכשיו כולו מצה כו' וד\"ל).\nג) <b>ומעתה</b> צ\"ל שרש ענין הפסוק דקול דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות כו' כנ\"ל דהנה פי' קול דודי הוא בחי' המשכה מן ההעלם לגילוי כמו הקול הגשמי שיוצא מהבל הלב לדיבור שנק' קלא דמשתמע בדיבור שמתגלה מהעלם המדות שבלב מהעלם המח' שבמוח כך למעלה הנה בחי' גילוי ההמשכה בדיבור העליון נק' קול ה' כמ\"ש קול<sup data-n=\"581\">67</sup> ה' בכח כו' אך זהו הנק' קול סתם ויש שנק' קול גדול ולא יסף והוא בחי' גילוי המשכה מהעלם עצמות אא\"ס שנק' סתימו דכ\"ס והיינו בחי' מל' דא\"ס שהוא פנימי' הכתר כנ\"ל ושורה ומתגלה במל' דאצי' שנק' דיבור העליון וכנ\"ל בענין מילוי דה\"ה הוא ענין ב' יראות הנ\"ל יראה עילאה דמל' דא\"ס שמתלבש ביר\"ת בחי' דיבור וכמ\"ש מה ה' אלקיך שואל מעמך א\"ת מה אלא מאה כו' וכנ\"ל והטעם שנק' קול גדול לפי שבחי' מל' דא\"ס הוא בחי' א\"ס ממש שלגדולתו אין חקר ומטעם זה נק' ג\"כ בשם מורא גדול כנ\"ל. ומ\"ש כאן קול דודי הכוונה על בחי' מל' דא\"ס שבפנימי' הכתר שנק' דודי להיותו בהעלם גדול ונק' סתימו דכ\"ס וכאשר מתגלה לפרקים הוא אומר קול דודי הנה זה בא שבא ומתגלה בבחי' דיבור העליון וע\"ד הנ\"ל בבחי' גילוי שכינה דמורא גדול דמל' דא\"ס שמתגלה בפסח בכאו\"א מישראל קטן וגדול בשוה כמ\"ש ופסח ה' על הפתח שהוא בחי' דילוג כנ\"ל והיינו מ\"ש הנה זה בא מדלג על ההרים. ומ\"ש הנה זה בא דמשמעו",[["578","64","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["579","65","<b>בזאת יבא אהרן</b>: ויקרא טז, ג."],["580","66","<b>זה השער לה'</b>: תהלים קיח, כ."],["581","67","<b>קול ה' בכח</b>: תהלים כט, ד."]]],[2101000107,"ל' הוה, לפי שבכל פסח הוא מדלג ובא מן ההעלם כמו שפסח ודילג בזמן יציאת מצרים כו' וד\"ל.\n<b>ומעתה</b> י\"ל מהו ענין הדליגה על ההרים ומהו ההפרש בין דליגה לקפיצה ולמה בדליגה אמר על ההרים ובקפיצה אמר על הגבעות כו', והנה תחלה י\"ל כללות ענין הדליגה והקפיצה שהוא ברגלים דוקא כידוע, והענין הוא כידוע בכתבי האריז\"ל בפי' אם תשיב משבת רגליך כו' שבחי' נה\"י דא\"ק מתלבשים בבי\"ע כו' וכמשל הרגלים באדם שהן בתחתית גופו להיות שמעמידן בארץ לילך גם במקום מטונף ולא איכפת לי' כלל אם יטנפם כדי שיוכל לעבור את כל גופו עי\"ז משא\"כ הידים לא ירצה לטנף בשביל העברת גופו ומכ\"ש הפה והעינים וכיוצא ששומרם מכל מקום מטונף כו', והנמשל מכ\"ז יובן למעלה בהיות שבחי' גילוי זה דבחי' כתר עליון ממל' דא\"ס הנה הוא יורד כ\"כ למטה עד נש\"י שבגופי' גשמיי' שהן בבחי' עשי' גשמי' וגם מלבד שהן בבחי' גבול יש נפרד אשר ערכם רחוק מאד מאד מבחי' גילוי אלקות כזה כמו ערך מקום מטונף לגבי אדם וע\"כ דומה דבר זה כמו אדם שיעמיד רגלו בארץ כך בחי' נה\"י מאור א\"ס מדלג ויורד למטה בארץ כמ\"ש הארץ<sup data-n=\"582\">68</sup> הדום רגלי והן כללות נש\"י שבגופים כו' אבל מבחי' ומדריגה היותר עליונה מבחי' נה\"י דא\"ק לא ירד כ\"כ למטה כו' (וגם מטעם אחר לפי שבחי' דילוג כזה שלא כפי המדה בסדר ההשתלשלו' אינו אלא ברגלי' דוקא כמו עד\"מ הדולג מן הגובה לנמוך שא\"א כ\"א ברגל דוקא שיש בכחו לדלוג ולהניע את הגוף יותר מכפי כח האדם בגופו בעצמו כו' וד\"ל).\n<b>והנה</b> ההפרש בין דליגה לקפיצה ידוע שהדליגה היא ברגל א' והקפיצה היא בשתי רגליו כמו אדם הקופץ מגג לארץ שקופץ בב' רגליו, והענין למעלה מבואר למעלה דבחי' אהבה לבדה הוא הדליגה ברגל א', ושרש הדברים הנה יש להקדים תחלה הידוע בזוהר בכמה דוכתי שיש בחי' טורי חשוכא ובחי' טורי דנהורא כמו בלידת המל' דנק' איילתא<sup data-n=\"583\">69</sup> דאזלת לטורי חשוכא כו' דהיינו שהמל' עולה עד בחי' המדות שבא\"א שנק' טורי חשוכא וכמ\"ש ותנח<sup data-n=\"584\">70</sup> התיבה בחודש הז' על הרי אררט כו' דהיינו בחודש תשרי שעולה המל' שנק' תיבה במדות שבכתר, וענין בחי' מדות שבכתר הנה ידוע שיש ב' מיני מדות הא' המדות הנולדי' מן השכל וההתבוננות והוא הנק' טורי נהורא כי המדות נק' הרים וכמו האבות שהן בחי' מרכבה לחג\"ת דאצי' נאמר בהן שמעו<sup data-n=\"585\">71</sup> הרים כו' וכמו ההר שהוא בגובה על הארץ כך מדת האהבה הרי בחי' צומח היא לגבי הדיבור שהוא בחי' דומם כו' וכמארז\"ל לא<sup data-n=\"586\">72</sup> כאברהם שקראו הר כו', אך בחי' המדות שמכוסים בהתבוננו' נק' טורי חשוכא בערך המדות שנולדי' בגילוי גמור שנק' טורי נהורא, ולמעלה יותר דהיינו בבחי' הרצון שנק' כתר שמה המדות אוי\"ר הן בבחי' הרצון ממש שנעלם מאד ונק' חושך",[["582","68","<b>הארץ הדום רגלי</b>: ישעי' סו, א."],["583","69","<b>איילתא דאזלת לטורי חשוכא</b>: זח\"ג רמט, ב. וראה ביאוה\"ז שם."],["584","70","<b>ותנח התיבה בחודש הז'</b>: בראשית ח, ד."],["585","71","<b>שמעו הרים</b>: מיכה ו, ב."],["586","72","<b>לא כאברהם שקראו הר</b>: ראה פסחים פח, א."]]],[2101000108,"אך אח\"כ יוצאין לידי גילוי בחו\"ב ונק' טורי חשוכא להיותם בבחי' העלם הכתר כו' ובחי' המדות שבכתר הן למעלה מעולם האצי' שהרי או\"א דאצי' מלבישים לזרועות דא\"א שנק' יד הגדולה ויד החזקה שהן מבחי' חיצוני' המדות שבכתר בלבד אבל בחי' עצמות המדות שבכתר הן למעלה מבחי' התלבשות אור בכלי עדיין אך הן באין בבחי' התלבשות בבחי' חיצוני' שבהן והוא מה שאו\"א מלבישים לזרועות דא\"א כו', וזהו מדלג על ההרים דקאי בין על טורי נהורא בין על בחי' טורי חשוכא הנ\"ל דהיינו שמדלג בבחי' נה\"י דא\"ק על בחי' המדות שבכתר כדי שלא יבא מהם<sup data-n=\"587\">73</sup> האור דרך השתלשלות אלא בבחי' דליגה והוא בחי' אהבה רבה שבכתר ובחי' יראה עילאה שבכתר שנמשך למטה במל' דרך דילוג.\n<b>והנה</b> בחי' אה\"ר שנמשכה מבחי' כתר (שבה מלובש מבחי' חסד העצמי של עצמו' המאציל כי חפץ חסד הוא וע\"כ בסיבת זה החסד עלה ברצונו הפשוט להאציל כו' וד\"ל) נק' דילוג ברגל אחת והוא רגל הימין להיות שרשו בבחי' החסד שהוא בחי' ימין (והיינו בחי' דילוג הבא בכח יותר מכפי המדה מחמת האהבה הגדולה ולמעלה היינו בחי' דילוג אור עליון שלמעלה מבחי' קו המדה שהוא קו\"ח שנמשך אחר הצמצום והיינו ע\"י כי חפץ חסד הוא כו') אבל בחי' קפיצה בשתי רגליו כא' הנה הוא בא ע\"י כח רב יותר בתגבורת מכח הדילוג ברגל א' והיינו ע\"י בחי' רשפי אש התשוקה שבאהבה שהיא גורמת כח גדול הרבה יותר מכפי כחו המצומצם בבחי' א\"פ ודוגמא לדבר בר\"ל<sup data-n=\"588\">74</sup> דקפץ ירדנא בכח יתירה מחמת חמימות התאוה כו' וא\"ל ר\"י חילך לאוריי' כי עוצם תשוקה כזו ממשכת כח גדול מבחי' או\"מ כו' וכן בע\"ת<sup data-n=\"589\">75</sup> גדולים מצד\"ג משום דמשכי' לי' בחילא יתיר יותר מכפי הכח העצמי כו' וכיוצא בזה הנה כ\"ז הוא מצד בחי' הגבורות דוקא שהן למעלה מבחי' החסדי' כי גבורה הוא ענין תגבורת גדולה כפשוטו דהיינו כח חזק במאד הרבה יותר מכח של חסדי' הגם שיורד החסד מגובה לנמוך מאד כידוע בענין ימינך פשוטה לקבל שבים וכשי\"ת בסמוך אבל בחי' כח הגבורות גדול הרבה יותר מכחן של חסדים והוא גורם בחי' הקפיצה בשתי רגלים כא' וע\"כ אמר מקפץ בגבעות דוקא להיות שרש הגבעות בבחי' הגבורות דשם ב\"ן כמשי\"ת בסמוך וד\"ל<sup data-n=\"590\">76</sup> ולמעלה היינו בחי' גבורה שבחסד שבעצמות המאציל והיא אהבה רבה שברשפי אש כו' ולמטה בבחי' שרש האצי' הוא בחי' גבורה דע\"י כו' וד\"ל) ובחי' יראה עילאה שבכתר נק' קפיצה בב' רגלים, והענין הוא דכתיב שמאלו<sup data-n=\"591\">77</sup> תחת לראשי וימינו תחבקני פי' ימינו הוא בחי' אה\"ר הנ\"ל הנה טבע האהבה לקבל בימין לכל גם למי שאינו ראוי כראוי והיינו לפי שבחי' אה\"ר זו מתפשטת למטה מטה מאד וע\"ד שאמר וימינך<sup data-n=\"592\">78</sup> פשוטה לקבל שבים דגם הרשעי' שעשו כל הרע שבעולם גם להם יקבל בתשובה כמו מנשה<sup data-n=\"593\">79</sup> דחתר כו'",[["587","73","<b>מהם</b>: בכת\"י ב וכת\"י ג: להם."],["588","74","<b>בר\"ל דקפץ ירדנא</b>: ב\"מ פד, א."],["589","75","<b>בע\"ת גדולים מצד\"ג משום דמשכי' לי' בחילא יתיר</b>: ברכות לד, ב. זח\"א קכט, ב."],["590","76","<b>וד\"ל)</b>: בהכת\"י חסר התחלת המוסגר."],["591","77","<b>שמאלו תחת לראשי וימינו תחבקני</b>: שה\"ש ב, ו."],["592","78","<b>וימינך פשוטה לקבל שבים</b>: תפילת נעילה."],["593","79","<b>מנשה דחתר כו' וקבלוהו</b>: סנהדרין קג, א."]]],[2101000109,"וקיבלוהו כי ימין העליון מתפשטת לקרב גם את היותר תחתון וז\"ש וימינו תחבקני כמו אדם שחובק לחבירו שמחבקו גם מאחוריו דהיינו גם לאחר שנסוג אחור ממנו כו' מחבקהו בימינו ומחזירהו אליו ולהיות כי האה\"ר הנ\"ל הוא בחי' חסד עליון ביותר ע\"כ מתפשט הוא למטה ביותר כידוע, אך הנה זהו דוקא באה\"ר הנ\"ל שנמשך כמים מגובה לנמוך כו' והוא בבחי' הקרירות אבל בבחי' הגבורות דיראה עילאה שבכתר (שנק' גבורה דע\"י או בחי' גבורה שבעצמות המאציל כנ\"ל) הנה הוא בא בבחי' תגבורת גדולה ביותר מפני בחי' רשפי אש וחמימות התשוקה כידוע (ונק' ג\"כ אהבה בתענוגים דהיינו כמו כשמשתעשע ברשפי אש באיזה דבר הנאהב והנחמד לו ביותר כו') וא\"כ הרי הוא כח של חסד גדול הרבה מבחי' כח החסד שיורד בקרירות כטבע המים הנ\"ל בבחי' ימין העליון, אך זהו הטעם עצמו להיות הגבורות היפך החסדי' ג\"כ בבחי' ההתפשטות למטה כקטן כגדול שמפני שהגבורות באין בבחי' רשפי אש הרי נמשך משם בחי' הדין והצמצום שלא להשפיע רק למי שראוי לו ולא למי שאינו ראוי דוגמא לזה כמו התורה<sup data-n=\"594\">80</sup> שנק' סם חיים לעוסקים בה לשמה ולמשמאילים בה נעשה סמא דמותא ועד\"מ הסם רפואה שהוא דבר חריף מאד ויכול לפעול חיות גדול בכחו הרב ולמי שלא יקחנו כראוי ימות בה וכמ\"כ כל דבר שבא מצד בחי' הגבורות הגם שחיותו וכחו רב מאד אבל צריך לבא בדקדוק גדול (וכמו הדם הוא הנפש הוא ג\"כ מבחי' גבורות ויזיק אם יבא בדמים איזה קלקול דהיינו כמו מאכילה גסה וכיוצא) וכך יובן למעלה בבחי' קו שמאל בגבורות העליונות שכחם ואורם רב יותר מאור החסד שבקו הימין אך אינן מתפשטי' למטה למי שאינו כראוי כמו התפשטות החסדי' אלא אדרבא למי שאינו ראוי נעשה שמאל דוחה בבחי' דין ועונש להאבידו וכמ\"ש בפרוח<sup data-n=\"595\">81</sup> רשעים כו' להשמדם כו' וכן משלם<sup data-n=\"596\">82</sup> לשונאיו אל פניו להאבידו דהגם שהחיצוני' מקבלי' מפסולת הנשפע מבחי' קו שמאל כידוע אבל נעשה להם לדין ועונש להאבידם בשפע זו שמקבלי' כו' וד\"ל. ואמנם הנה כ\"ז כאשר עדיין לא נבררו כל הבירורי' דרפ\"ח כו' שנפלו בשבירה בע' שרים ולא אתהפכ' חשוכא לנהורא כו' וע\"כ לא יוכל לירד אור שפע הגבורות העליונות שבכתר למטה אבל לע\"ל דכתיב ואת<sup data-n=\"597\">83</sup> רוח הטומאה אעביר כו' בלע<sup data-n=\"598\">84</sup> המות לנצח כו' לפי שיבורר<sup data-n=\"599\">85</sup> הכל ע\"י שם ב\"ן כידוע אז נאמר שמאלו תחת לראשי שבחי' קו השמאל העליון יתפשט גם הוא עד למטה מטה תחת לראשי דהיינו ע\"ד המאמר דרישא<sup data-n=\"600\">85</sup> שכיבת לעפרא והוא בחי' מל' דאצי' שעומדת עכשיו בבחי' אבא ובחי' חב\"ד שבה שנק' רישא שכיבת לעפרא בעפר דבריאה כמ\"ש מקימי<sup data-n=\"601\">87</sup> מעפר דל כו' וד\"ל, וזהו ענין הקפיצה בב' רגליו שהוא בחי' המשכת יראה עילאה דכתר שבקו השמאל שיתגלה למטה כמו בחי' התפשטו' החסד דקו הימין אך להיותו בבחי' רשפי אש",[["594","80","<b>התורה שנק' סם חיים לעוסקים בה לשמה</b>: יומא עב, ב. ובכ\"מ."],["595","81","<b>בפרוח רשעים</b>: תהלים צב, ח."],["596","82","<b>משלם לשונאיו אל פניו</b>: דברים ז, י."],["597","83","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["598","84","<b>בלע המות לנצח</b>: ישעי' כה, ח."],["599","85","<b>שיבורר הכל ע\"י שם ב\"ן כידוע</b>: ראה תו\"א ויחי מח, א. לקו\"ת עקב יד, ג. לעיל ע' ג. ובכ\"מ."],["600","85","<b>דרישא שכיבת לעפרא</b>: זח\"ג קיט, ב. וראה ע\"ח שמ\"ח פ\"ג. סה\"מ אתהלך לאזניא ע' קמו. ביאוה\"ז קמג, א ואילך. אוה\"ת נ\"ך ע' שפז. ובכ\"מ."],["601","87","<b>מקימי מעפר דל</b>: תהלים קיג, ז."]]],[2101000110,"וגדול כחו הרבה יותר מבחי' החסד שבימין כנ\"ל ע\"כ נאמר בו קפיצה בב' רגלים (שהוא בא מבחי' הגבורו' בתגבורת כח גדול יותר מדאי כנ\"ל וד\"ל).\nד) <b>וזהו</b> קול דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות דהנה בחי' אה\"ר ויראה עילאה הנ\"ל שנמשך מבחי' כתר למטה היינו ע\"י עסק התורה והמצות שנק' הרים וגבעות כמ\"ש ישאו<sup data-n=\"602\">88</sup> הרים שלום ואין<sup data-n=\"603\">89</sup> שלום אלא תורה כו' וגבעות בצדקה שהן המצות כנ\"ל, אך להבין הטעם למה נק' התורה והמצות בשם הרים וגבעות הנה תחלה יש להקדים שרש ענין הרים וגבעות באבות והאמהות שהאבות נק' הרים כמארז\"ל לא<sup data-n=\"604\">90</sup> כאברהם שקראו הר וכמ\"ש שמעו<sup data-n=\"605\">91</sup> הרים את ריב ה' והאמהות נק' גבעות וכמ\"ש<sup data-n=\"606\">92</sup> בזהר ע\"פ כי מראש צורים אראנו ומגבעות אשורנו כו' (וכמ\"ש<sup data-n=\"607\">93</sup> בזוהר<sup data-n=\"608\">94</sup> דהיינו בחי' בינה ומל' גבעה דלעילא וגבעה דלתתא כו') ושרש הדברים היינו כמ\"ש בע\"ח שאברהם ושרה הוא בחי' מ\"ה וב\"ן כי אברהם אבר מ\"ה כו' וכן יצחק ורבקה יעקב ורחל כו' הכל הוא בחי' מ\"ה וב\"ן שבג' פרצופים כו' ודרך כלל האבות הן המרכבה לבחי' חג\"ת דז\"א ולפעמים לבחי' חג\"ת דא\"א ובכאו\"א הנה בחי' מ\"ה מברר לב\"ן שבאותו הפרצוף והיינו הטעם שהאבות נק' הרים שהוא בחי' שם מ\"ה המברר והאמהות נק' גבעות בחי' שם ב\"ן המתברר כו' וכידוע דכל המתבררי' הוא ע\"י שם מ\"ה כי בחכ'<sup data-n=\"609\">95</sup> אתברירו שהוא בחי' מ\"ה דחכ' כו'. אך הנה לפ\"ז לכאורה יש להקשות קושי' גדולה וחזקה מאד דלפי הנ\"ל הרי האבות למעלה מן האמהות מאחר שהאבות נק' מבררים לבחי' ב\"ן שהן האמהות וא\"כ איך אמר ה' לאברהם כל<sup data-n=\"610\">96</sup> אשר תאמר אליך שרה שמע בקולה ואיך יקבל אברהם שהוא בחי' מ\"ה משרה שהוא בחי' ב\"ן לשמוע בכל אשר תאמר אליו הלא אברהם הוא בחי' משפיע ושרה הוא בחי' מקבל ואיך יקבל המשפיע מן המקבל עולם<sup data-n=\"611\">97</sup> הפוך הוא עליונים למטה כו', וכמ\"כ יפלא במה שמצינו ברבקה דכתיב בה ותרד<sup data-n=\"612\">98</sup> העינה ותמלא כדה ותעל וידוע<sup data-n=\"613\">99</sup> דכ\"ד זה היינו כ\"ד ספרי' דאוריי' ששאבה רבקה ממעיין חכמה עילאה שנק' עינה וז\"ש ותרד העינה לח\"ע בכדי למלאות משם כ\"ד ספרי' דאוריי' כי אוריי'<sup data-n=\"614\">100</sup> מח\"ע נפקת כידוע וגם זה לא יתכן לפי הנ\"ל דח\"ע הוא בחי'",[["602","88","<b>ישאו הרים שלום</b>: תהלים עב, יג."],["603","89","<b>ואין שלום אלא תורה</b>: פס\"ז ר\"פ קדושים. וראה גיטין נט, ב. במדב\"ר פי\"א, ז."],["604","90","<b>לא כאברהם שקראו הר</b>: ראה פסחים פח, א."],["605","91","<b>שמעו הרים את ריב ה'</b>: מיכה ו, ב."],["606","92","<b>וכמ\"ש בזהר ע\"פ כי מראש צורים אראנו</b>: זח\"ג רג, ב."],["607","93","<b>וכמ\"ש. . דהיינו בחי' בינה ומל'</b>: ראה ביאוה\"ז שם (קד, ג ואילך)."],["608","94","<b>וכמ\"ש בזוהר</b>: בכת\"י ב וכת\"י ג: וכמ\"ש במ\"א."],["609","95","<b>בחכ' אתברירו</b>: ראה זח\"ב רנד, ב. ע\"ח שי\"ח פ\"ה ועוד. מבו\"ש ש\"ה ח\"א פ\"ב. אגה\"ק סכ\"ח. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 206."],["610","96","<b>כל אשר תאמר אליך שרה שמע בקולה</b>: בראשית כא, יב."],["611","97","<b>עולם הפוך הוא עליונים למטה</b>: ע\"פ הגמרא פסחים נ, א. ובכ\"מ."],["612","98","<b>ותרד העינה ותמלא כדה</b>: בראשית כד, טז."],["613","99","<b>וידוע דכ\"ד זה היינו כ\"ד ספרי' דאורייתא</b>: ראה ת\"ז תכ\"א (מו, ב). וראה לעיל בריש ד\"ה מים רבים."],["614","100","<b>אוריי' מח\"ע נפקת</b>: זח\"ב קכא, א."]]],[2101000111,"שם מ\"ה המברר לבחי' ב\"ן כו' ובחי' רבקה הרי הוא רק מבחי' ב\"ן כנ\"ל ואיך אמר לשון ירידה ותרד העינה שירדה רבקה אל העין דחכ' דמשמע שבחי' ירידה נחשב לגבי מדריגת רבקה למלאות כ\"ד ספרים משם הרי בחי' ח\"ע גבוה ממדריגת רבקה וגם אמר ותמלא כדה שהיא הממלא לכ\"ד ספרים דאוריי' ממי המעיין דח\"ע ולא כן הוא אלא אדרבא נהפוך הוא שמי המעיין דח\"ע למעלה מבחי' ב\"ן דרבקה והיא מקבלת משם בבחי' מקבל בלבד, וכמ\"כ יפלא מה שאמרה רבקה אל העבד שתה וגם לגמליך אשקה הרי ידוע דגמלי אדוניו של עבד זה הן בחי' כלים דע\"ס דמ\"ה דאברהם שהוא בחי' משפיע ואיך אמרה רבקה שהיא בחי' מקבל וגם לגמליך אשקה היתכן שנעשה המקבל משפיע כו'. אך הנה כ\"ז יתורץ עפ\"י המבואר למעלה בשלשה<sup data-n=\"615\">101</sup> שהטעימן הקב\"ה מעין עוה\"ב והמה אברהם יצחק ויעקב שנאמר בהן בכל מכל כל כו' והענין הוא כי בחי' האמהות בשרשן יהי' לעתיד גבוה מבחי' האבות וכמ\"ש הנני<sup data-n=\"616\">102</sup> בורא חדשה בארץ נקבה תסובב גבר דהיינו בחי' שם ב\"ן שיהי' גבוה מבחי' מ\"ה והיינו פי' נקבה תסובב גבר וכמ\"ש א\"ח<sup data-n=\"617\">103</sup> עט\"ב כו' וד\"ל.\n<b>ויובן</b> זה עפ\"י הידוע בע\"ח במ\"ש ואלה<sup data-n=\"618\">104</sup> המלכים אשר מלכו בארץ אדום לפני מלוך מלך לבנ\"י כו' שהן בחי' האורות דתוהו וכולם המה בבחי' ב\"ן שהרי נאמר בהן לשון מלוכה וימלוך בלע כו' וכל מלוכה הוא בבחי' ב\"ן כידוע וכל הז' מלכים דתוהו נפלו בעולם הבריאה והוא בבחי' שם ב\"ן דבריאה כמ\"ש בע\"ח והנה בחי' התיקון והבירור דב\"ן דתוהו שנפל למטה בבריאה הוא ע\"י בחי' שם מ\"ה דתיקון שבאצי' שנק' מלך לבנ\"י שלאחר הבירור כו' (והיינו ע\"י הארת שם מ\"ה החדש דא\"ק כו' שנק' מלך השמיני הדר כו' וכמ\"ש בע\"ח וכמ\"ש במ\"א), אך הנה אעפ\"י שבחי' שם מ\"ה הוא המברר לבחי' ב\"ן שנפל מבחי' התוהו כנ\"ל הנה מ\"מ שרש בחי' ב\"ן זה לאחר שמתברר משם מ\"ה דתיקון גבוה הוא מצד שרשו הקדום בתוהו שקדם לתיקון וכמ\"ש ואלה המלכים אשר מלכו לפני מלוך מלך כו' שהז' מלכים דתוהו קדמו לפני בחי' התיקון כו' וכמ\"ש בע\"ח בענין ד' שמות ע\"ב ס\"ג מ\"ה ב\"ן דעיקר השבירה הי' בבחי' שם ס\"ג דבינה והוא בבחי' הנקודים כו' והתיקון הוא בשם מ\"ה שלמטה משם ס\"ג והוא בחי' ברודי' אך כשנפלו רפ\"ח ניצוצין דתוהו נפלו בבחי' ב\"ן כנ\"ל אך לאחר שיוברר שם ב\"ן ע\"י שם מ\"ה דתיקון הרי עולה בחי' ב\"ן זה לבחי' ב\"ן דתוהו דהיינו בבחי' ב\"ן דס\"ג דבינה שלמעלה מבחי' מ\"ה דז\"א כידוע ואעפ\"י שעכשיו בחי' מ\"ה מברר לב\"ן דנוק' אבל לאחר הבירור יעלה לשרשו בחי' ס\"ג שלמעלה משם מ\"ה המברר וז\"ש א\"ח שהוא שם ב\"ן לאחר הבירור שנק' אשת חיל ע\"ש ריבוי חיל הבירורים שעולין עמה כמ\"ש חיל<sup data-n=\"619\">105</sup> בלע ויקיאנו וכן חיל לשון כח כמו רבות<sup data-n=\"620\">106</sup> בנות עשו חיל ואת עלית כו' וכמ\"ש תנו<sup data-n=\"621\">107</sup> עוז לאלקים שהוא שם",[["615","101","<b>בשלשה שהטעימן הקב\"ה מעין עוה\"ב</b>: ב\"ב טז, ב."],["616","102","<b>הנני בורא חדשה בארץ</b>: ראה ירמי' לא, כא. וראה אוה\"ת בראשית מ, ב ואילך."],["617","103","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["618","104","<b>ואלה המלכים אשר מלכו בארץ אדום</b>: בראשית לו, לא."],["619","105","<b>חיל בלע ויקיאנו</b>: איוב כ, טו."],["620","106","<b>רבות בנות עשו חיל</b>: משלי לא, כט."],["621","107","<b>תנו עוז לאלקים</b>: תהלים סח, לה."]]],[2101000112,"ב\"ן כו' ובחי' אשת חיל זאת נעשית עטרת לבעלה שהוא שם מ\"ה וז\"ש נקבה תסובב גבר כו' וד\"ל.\n<b>וביאור</b> זה יובן ג\"כ ממה שמצינו בדרז\"ל דבע\"ת<sup data-n=\"622\">108</sup> גדולים מצד\"ג ובזהר אמרו הטעם משום דמשכי'<sup data-n=\"623\">109</sup> לי' בחילא יתיר פי' חילא יתיר כח גדול וחזק הרבה יותר מכחן של צד\"ג בעבודתם באוי\"ר כו' ולכאורה דבר זה כפלא יחשב איך כח אהוי\"ר של בע\"ת תגדל מכח אוי\"ר של צד\"ג, אך הענין הוא משום דאוי\"ר של צד\"ג הוא מבחי' המדות שבנפשם האלקי' ששרשה מבחי' מ\"ה דתיקון כמ\"ש<sup data-n=\"624\">110</sup> בע\"ח דהנשמה עצמה א\"צ תיקון כי כבר ניתקנה במ\"ה דזו\"נ דאצי' כידוע דשרש הנשמות נולדו מיחוד זו\"נ שהן לאחר התיקון אבל אוי\"ר של בע\"ת הוא מבחי' המדות הרעות דנוגה שהוא שרש נה\"ב שנהפך מרע לטוב ע\"י התשובה ושרש נה\"ב דנוגה בבחי' התוהו שלפני התיקון אלא שנפל בשבירה בב\"ן דבריאה כנ\"ל ונתגשמו עוד בירידתן למטה מטה בנוגה דבי\"ע עד שנעשה למטה בחי' מדות רעות כמו טבע המזיקין כעופות וחיות הדורסין וכמ\"כ בנ\"א רעים ואכזרים בטבעם למהר לשפוך דם נקי ולא יחמלו כו', אך אנו רואים שיש תוקף וחוזק בתגבורת עצומה במדות נפש הטבעיית החיונית יותר הרבה מטבע המדות דנפש האלקי' (וכמ\"ש במ\"א בביאור ענין לעולם<sup data-n=\"625\">111</sup> יהא אדם רך כקנה ואל יהא קשה כארז שהמדות הטבעיי' קשים כארז בלי יחלשו כחם מכל מנגד ואין לשכל שליטה עליהם להפכם כו'<sup data-n=\"626\">112</sup>) מפני ששרשם מבחי' התוהו שהיו בחי' אורות תקיפין וחזקים ביותר וע\"כ גם בנפילתם למטה בהגשמה דנוגה ג\"כ המה תקיפים וחזקים כמו תקיפי<sup data-n=\"627\">113</sup> דרא שנק' עזי פנים כו') והמופת לזה במה שאנו רואים שכח הבהמה חזקה מכח האדם להיות שרש הבהמה מבחי' התוהו (וכמ\"ש<sup data-n=\"628\">114</sup> באד\"ר באני עלמין כו' ולא אתקיימו עד דאתברי בפרצופא דאדם שהוא בחי' התיקון והן הנה המאמרות דתוצא ארץ נפש חי' ועוף יעופף כו' שקדמו כולן למאמר נעשה אדם וכמ\"ש אחור וקדם צרתני אחור<sup data-n=\"629\">115</sup> למע\"ב כו' וכמ\"ש במ\"א) ומטעם זה יובן ג\"כ מה שבע\"ת משכין לי' לקוב\"ה בחילא יתיר מצד\"ג כי אחר בירור הרע שבהם עולין לשרשם בבחי' ב\"ן דתוהו שקדם לבחי' מ\"ה דתיקון וע\"כ גם למטה בהתהפך הרע שלהם לטוב הן בתוקף ותגבורת גדולה בחילא יתיר יותר גם מאוי\"ר של צדיקים גמורים כו' וכ\"ז מופת לענין הנ\"ל דבחי' ב\"ן לאחר הבירור גבוה מבחי' מ\"ה להיותו עולה לשרשו בבחי' שם ס\"ג שלמעלה משם מ\"ה כנ\"ל וד\"ל.",[["622","108","<b>דבע\"ת גדולים מצד\"ג</b>: ברכות לד, ב."],["623","109","<b>ובזוהר. . משום דמשכין לי' בחילא יתיר</b>: זח\"א קכט, ב."],["624","110","<b>כמ\"ש בע\"ח דהנשמה עצמה א\"צ תיקון</b>: ע\"ח שער כ\"ו פ\"א. וראה תניא פל\"ז."],["625","111","<b>לעולם יהא אדם רך כקנה</b>: תענית כ, ב."],["626","112","<b>כו')</b>: כ\"ה בהכת\"י. וכנראה סיום המוסגר מיותר."],["627","113","<b>תקיפי דרא</b>: ראה חגיגה יד, רע\"א. וראה סה\"מ תקס\"ח ע' רכג. תו\"ח בראשית טז, ב. שם שמות תקמ, ב. ובכ\"מ."],["628","114","<b>וכמ\"ש באד\"ר באני עלמין</b>: ראה זח\"ג קמב, א."],["629","115","<b>אחור וקדם צרתני אחור למע\"ב</b>: תהלים קלט, ה. ויק\"ר יד, א. ובכ\"מ."]]],[2101000113,"<b>ועכ\"ז</b> יובן ג\"כ שרש האבות והאמהות ששרש האמהות למעלה יהי' לעתיד גבוה מן האבות וכמ\"ש נקבה תסובב גבר וכנ\"ל וגם עכשיו הטעימן הקב\"ה מעין העוה\"ב דלעתיד וע\"כ נאמר לאברהם כל אשר תאמר אליך שרה שמע בקולה כו' כי הנה העוה\"ב הוא לאחר הבירור דשיתא<sup data-n=\"630\">116</sup> אלפי שני כו' ואז יעלה בחי' ב\"ן לשרשו בס\"ג שלמעלה שמשם מ\"ה ותהי' א\"ח עט\"ב ונקבה תסובב גבר אלא רק עכשיו דוקא בחי' מ\"ה מברר לבחי' ב\"ן אבל האבות הטעימן גם עכשיו מעין העוה\"ב שנאמר בכל מכל כל שהן נש\"ב שבבחי' בינה שנשלמים אחר הבירור וע\"כ היו האמהות עקרות כי היו בבחי' דכורא כו'. ובכ\"ז יתורצו כל הקושיו' הנ\"ל איך אמר שאברהם יהי' בחי' מקבל לשמוע בקול שרה, כי שרה שרשה למעלה מבחי' אברהם מטעם הנ\"ל דבחי' מ\"ה יהי' למטה מבחי' ב\"ן לאחר הבירור והאמהות הן בבחי' ב\"ן והאבות בבחי' מ\"ה כנ\"ל, ומזה הטעם ג\"כ כתיב ברבקה שהיא ב\"ן ותרד העינה לבחי' מ\"ה דחכ' וכן לגמליך אשקה כנ\"ל לפי שהמקבל נעשה בחי' משפיע כמ\"ש נקבה תסובב גבר א\"ח ע\"ב כנ\"ל וד\"ל.\nה) <b>ומעתה</b> יובן ג\"כ דוגמת כל הנ\"ל באבות ואמהות שנק' הרים וגבעות בחי' מ\"ה וב\"ן גם בשרש ענין התורה והמצות שנק' הרים וגבעות כנ\"ל שהן ג\"כ בחי' מ\"ה וב\"ן כנ\"ל באבות ואמהות. דהנה ידוע דאוריי' מח\"ע נפקת והוא בחי' שם מ\"ה דחכ' שמברר למעשה המצות כי עפ\"י החכ' שבתורה דוקא נעשה כל מצוה כך וכך יוכשר למצוה וא\"ל אינה מצוה כלל וה\"ז כמו בחי' מ\"ה שמברר לב\"ן כך הרי המצות נתלבשו בענינים גשמיי' דנוגה באתרוג וציצית ומכ\"ש מצות ל\"ת בסור מרע והכל מתברר ע\"י החכ' שנגזרה זה יעלה למעלה כו' וזה יפסול כו' ונמצא בחי' ב\"ן דנוגה שנפל בשבירה מתברר ע\"י מ\"ה דחכ' ולכך תלמוד<sup data-n=\"631\">117</sup> גדול כו' וכמ\"ש<sup data-n=\"632\">118</sup> בע\"ח דתלמוד בבריאה כו' וכידוע שהתורה הוא בחי' ז\"א שהן המדות שבחכ' להבדיל בין טמא כו' והמצות הן בבחי' המל' הנק' מצות המלך שמקבלת מהתורה כנ\"ל. והנה כמו שמבואר למעלה דלעתיד יתעלה שם ב\"ן למעלה משם מ\"ה כך המצות שהן בבחי' ב\"ן כנ\"ל הגם שעכשיו למטה מבחי' מ\"ה דחכ' שבתורה לעתיד יתעלו למעלה מבחי' מ\"ה דחכ' והיינו מפני ששרש המצות כמו שהן למעלה הרי<sup data-n=\"633\">119</sup> נק' תר\"ך עמודי אור והן<sup data-n=\"634\">120</sup> בחי' תרי\"ג ארחין דגלגלתא דא\"א שנק' כתר שבכתר כידוע רק שירדו למטה דרך בחי' החכ' שבתורה כו' ונתלבשו למטה להתברר ע\"י החכ' אבל לאחר תשלום בירורן יעלו בשרשן הראשון בגלגלתא דא\"א שהוא בחי' פנימי' רצה\"ע שלמעלה מן החכ' כמ\"ש והחכ'<sup data-n=\"635\">121</sup> מאין כו' וכידוע וז\"ש",[["630","116","<b>דשיתא אלפי שני</b>: ר\"ה לא, א. ובכ\"מ. וראה לקו\"ש חכ\"א ע' 453."],["631","117","<b>תלמוד גדול</b>: קדושין מ, ב. ובכ\"מ."],["632","118","<b>וכמ\"ש בע\"ח דתלמוד בבריאה</b>: ראה שער המצות וטעהמ\"צ פ' ואתחנן. פע\"ח שער הנהגת הלימוד. וראה ת\"ז בהקדמה (יד, א). תניא פ\"מ בהגה\"ה אחרונה. אגה\"ק סכ\"ו. תו\"א ר\"פ שמות. ובכ\"מ."],["633","119","<b>הרי נק' תר\"ך עמודי אור</b>: ראה אגה\"ק סכ\"ט. פרדס ש\"ח פ\"ג."],["634","120","<b>והן בחי' תרי\"ג ארחין דגלגלתא</b>: ראה זח\"ג קכט, א. ובביאור האריז\"ל שם. מ\"ח מס' א\"א ספ\"ד."],["635","121","<b>והחכ' מאין</b>: איוב כח, יב."]]],[2101000114,"גם על המצות שהן בבחי' ב\"ן א\"ח ע\"ב ונקבה תסובב גבר כנ\"ל בבחי' האמהות וזהו שנק' התורה והמצות בשם הרים וגבעות כמ\"ש ישאו הרים שלום ואין שלום אלא תורה וגבעות בצדקה שהן המצות שנק' צדקה כו' דהיינו בחי' מ\"ה וב\"ן שנק' הרים וגבעות כנ\"ל באבות ואמהות וד\"ל.\n<b>ומ\"ש</b> ישאו הרים שלום דמשמע שהתורה לא נק' הרים אלא שלום, הענין הוא כמארז\"ל כל<sup data-n=\"636\">122</sup> העוסק בתורה לשמה עושה שלום בפשמ\"ע ובפשמ\"ט שנאמר או יחזיק במעוזי יעשה שלום לי שלום יעשה לי כי הנה שרש בחי' התורה הוא בחי' קו האמצעי דת\"י כו' שנק' בריח התיכון כו' ועולה עד קצה העליון דכתר לחבר ולייחד פשמ\"ע שהוא יחוד מ\"ה וב\"ן דחו\"ב ומ\"ה וב\"ן דזו\"נ שנק' פשמ\"ט כידוע וזהו ב' שלומות יעשה שלום לי לחו\"ב שלום יעשה לי לזו\"נ כו' וד\"ל, ודרך כללות הנה בחי' השלום הוא בחי' התחברות המשפיע במקבל וכמ\"ש וידעת<sup data-n=\"637\">123</sup> כי שלום אהלך כו' וז\"ש והי'<sup data-n=\"638\">124</sup> מעשה הצדקה שלום פי' השפעת המשפיע במקבל נק' מעשה של צדקה ונק' שלום לפי שעי\"ז מתחבר המשפיע במקבל והוא הנק' חיבור אורות בכלים באצי' הנק' פשמ\"ע והתלבשות האצי' בבריאה שנק' פשמ\"ט כו' וז\"ש ישאו הרים שלום לחברם במקבלים כו' והוא ע\"י התורה שהיא בחי' קו האמצעי כנ\"ל וד\"ל.\n<b>וגבעות</b> בצדקה, פי' כל המצות נק' צדקה כמ\"ש וצדקה<sup data-n=\"639\">125</sup> תהי' לנו כי נשמור כו' וכן ושמרו<sup data-n=\"640\">126</sup> דרך ה' לעשות צדקה כו' והטעם ידוע כמו הצדקה גשמי' שהיא להחיות רוח שפלים למאן דלית לי' מגרמי' כלום כך ע\"י מעשה המצות הנה נמשך בחי' גילוי אלקות למטה בכלים מכלים שונים כאתרוג ולולב וכיוצא להאיר ולהחיות רוח שפלים בע\"ג כו' ולכך המקיים את המצות מפני שהוא הממשיך לבחי' גילוי אור עליון בכלים שונים נק' צדיק כמו העושה והמשפיע את הצדקה נק' צדיק ע\"ד מ\"ש כי<sup data-n=\"641\">127</sup> צדיק ה' צדקות אהב כו' וכמ\"ש במ\"א ולמעלה יובן מזה ג\"כ דבחי' המעשה של המצוה נק' צדקה בה\"א בחי' מקבל וההמשכה שנמשכה במעשה זאת נק' צדיק בחי' יסוד ז\"א כמ\"ש צדיק ה' צדקות אהב כו' וד\"ל. וזהו וגבעות בצדקה פי' גבעות וצדקה הוא בחי' שם ב\"ן שרש המצות שהוא בחי' מקבל מהרים שהוא בחי' המשכת אור א\"ס בחכ' שבתורה שנק' הרים ונק' שלום כנ\"ל וכנ\"ל דהמצות מקבלין מן התורה עכשיו כי בחי' מ\"ה מברר לב\"ן אך לעתיד הרי יתעלה בחי' ב\"ן למעלה משם מ\"ה כנ\"ל ויהי' שרש המצות למעלה מבחי' התורה כמ\"ש א\"ח ע\"ב ונקבה תסובב גבר כנ\"ל. וז\"ש קול דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות דבהרים לא אמר רק דילוג ברגל א' הימנית ובגבעות א' קפיצה בשתי רגליו",[["636","122","<b>כל העוסק בתורה לשמה עושה שלום בפשמ\"ע</b>: סנהדרין צט, ב."],["637","123","<b>וידעת כי שלום אהלך</b>: איוב ה, כד. וראה יבמות סב, ב. ובכ\"מ."],["638","124","<b>והי' מעשה הצדקה שלום</b>: ישעי' לב, יז."],["639","125","<b>וצדקה תהי' לנו כי נשמור</b>: דברים ו, כה."],["640","126","<b>ושמרו דרך ה' לעשות צדקה</b>: בראשית יח, יט."],["641","127","<b>כי צדיק ה' צדקות אהב</b>: תהלים יא, ז."]]],[2101000115,"כא' כנ\"ל דהנה בחי' דילוג וקפיצה זאת היינו גם על הארת בחי' אה\"ר ויראה עילאה שבכתר והיינו שמדלג על ההרים כנ\"ל ובחי' דילוג בא ע\"י עסק התו\"מ כי האהוי\"ר שבכתר נק' טורי חשוכא כנ\"ל ושרש התומ\"צ הוא בבחי' מ\"ה וב\"ן שהוא בחי' חו\"ג שבעצמות המאציל שלמעלה מחו\"ג שבכתר ולכך נק' קול דודי כמו קול גדול כו' ולהיות כי בחי' ב\"ן שהוא שרש האמהות שנק' גבעות והוא שרש המצות כנ\"ל גבוה לעתיד מבחי' מ\"ה דאבות שהוא שרש התורה כנ\"ל ע\"כ אמר קפיצה בב' רגליו בגבעות להיותם למעלה במדריגה מן ההרים מטעם הנ\"ל ודליגה ברגל א' אמר בהרים וכנ\"ל בפי' שמאלו תחת לראשי שהוא בחי' קו השמאל דגבורות והיינו ג\"כ בחי' שם ב\"ן שיהי' גבוה לעתיד מבחי' קו הימין דחכ' כו' וע\"כ א' מקפץ על הגבעות כו' וד\"ל."],[2101000116,"<h3>ולהבין בתוספת הביאור</h3>\n<b></b><b>ולהבין בתוספת הביאור </b>\nא) <b>ולהבין</b><sup data-n=\"642\">1</sup> בתוס' ביאור מ\"ש מקפץ על הגבעות דבגבעות שהוא בחי' צדקה מקפץ בקפיצה שהיא בשתי רגליו כו' הנה יש להקדים מ\"ש וצדקה<sup data-n=\"643\">2</sup> כנחל איתן למה נמשלה הצדקה לנחל איתן דוקא, להיות ידוע דרשת רז\"ל בעגלה ערופה דכתיב והורידו<sup data-n=\"644\">3</sup> זקני העיר כו' אל נחל איתן אשר לא יעבד כו' אמר<sup data-n=\"645\">4</sup> הקב\"ה יבא מי שלא עשה פירות ויכפר על מי שלא הניחו לעשות פירות והקשה א\"כ זקן וסריס כו' אלא מאי פירות מצות שלא הניחו לעשות מצות שנק' פירות. וי\"ל הטעם למה נק' המצות בשם פירות דוקא ועוד י\"ל דהלא הפירות הן בחי' מזון וחיות פנימי הנק' או\"פ כידוע ובכמה דוכתי בזהר וע\"ח מבואר דשרש המצות הוא בבחי' לבושים שהן בחי' א\"מ כידוע. אך הנה כ\"ז יובן בהקדים מ\"ש אור<sup data-n=\"646\">5</sup> זרוע לצדיק פי' צד\"ע הוא העושה את הצדקה שהן המצות שנק' צדקות והנה מ\"ש זורע<sup data-n=\"647\">6</sup> צדקות וכן אור זרוע לצדיק שנמשל לזריעה לכאורה אין לזה הבנה למה נמשל לזריעה דוקא. אך הענין הוא עד\"מ הזורע דבר מה כמו הזורע גרעין של חטה כדי להצמיח מן הארץ חיטים הרבה וכן הנוטע אילן שיעשה מיני פירות הרבה חמוצים או מתוקים חלוקים במיניהם כידוע הנה צריך שיזריע בארץ גרעין שיהי' מאותו המין ויורקב בארץ ואח\"כ יוליד ויצמיח בארץ ובלעדי זה לא יצמח מאומה, ודבר זה כפלא יחשב לכאורה שהרי עיקר הצמיחה אינו אלא מכח הצומח שיש בארץ שבו שורה כח האלקי ממאמר תדשא הארץ כו' כידוע והכח הצומח ודאי יש ביכולת להצמיח כל מיני תבואה ופירות ולמה צריכים לזריעת הגרעין לגמרי. אך הטעם הוא לפי שבחי' כח הצומח שבארץ הוא בחי' כח רוחני והיולי וא\"א שיצמח ממנו הגשמת דבר מה",[["642","1","<b>ולהבין בתוס' ביאור</b>: נדפס בשינויים (ותוס' הגהות) בלקו\"ת שה\"ש טו, ד."],["643","2","<b>וצדקה כנחל איתן</b>: עמוס ה, כד."],["644","3","<b>והורידו זקני העיר כו'</b>: דברים כא, ד."],["645","4","<b>אמר הקב\"ה יבא מי שלא עשה פירות</b>: סוטה מו, א."],["646","5","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["647","6","<b>זורע צדקות</b>: נוסח ברכת יוצר."]]],[2101000117,"כמו הגשמת טעם חמיצות או מתיקות של פירות גשמיי' כי לא יתכן שיהי' הגשמה כזאת כמו טעם חמיצות גשמיי' ברוחניות כח המצמיח, והגם שידוע שכל מציאות כחות הרוחניי' יש בהם התחלקות מדריגות דע\"ס כמו בחי' חו\"ג וגם במלאכים יש שר של אש ושר של מים שהן בחי' חו\"ג שבכלים החיצוני' דמל' דעשי' כו' אך אעפ\"י שיש בחי' חו\"ג וכיוצא בכח המצמיח אבל המה רוחניי' ואינם בערך הגשמה להיות נצמח טעם חמוץ או מתוק כלל רק ע\"י סיבת הזריעה של הגרעין בארץ גורם שיתלבש כח המצמיח בחומר הגרעין הנזרע ויצמיח בדומה לגרעין בהגשמת דבר כמו מיני פירות חלוקים בטעמי' גשמיי' כי זהו דרכו וטבעו של כח ההיולי הרוחני להתלבש בחומר המוכן ואז נעשה צורה לחומר ההוא כפי הכנת אותו החומר אבל אין זה עצם מהותו כלל רק שמתלבש בלבד להיות צורה לחומר מצד הכנת כלי החומר שממשיכו ומורידו אליו להתלבש בו כו'.\n<b>ויובן</b> זה בתוס' ביאור ממה שמצינו דוגמא זאת גם באור וחיות הנפש הרוחניית שגם היא מושללת ודאי מכל תוארי ההגשמה שבפעולת ותמונת<sup data-n=\"648\">7</sup> אברי הגוף הגשמיי' החומריי' כמו החושי' הגשמיי' כריח ושמיעה וראי' וכיוצא ובודאי אין ביכולת כלי חומר העין לראות ולא בחומר האוזן לשמוע רק ע\"י הארת אור וכח הנפש בהם וזה ברור שהנפש עצמה מושללת מכחות גשמיי' כאלה כי לא יתכן לומר שהנפש הרוחניו' תראה ותשמע בראי' גשמיי' ושמיעה גשמי' ממש רק שהנפש היא בחי' כח היולי רוחני מושללת מהגשמת כחות גשמיי' אך בהמצא לה חומר מוכן לקבל צורה תומשך ותתפשט להאיר ולהחיות כמו בכלי חומר העין תתלבש בה צורת חיות כח הראי' ובחומר האוזן לשמוע ובכלי המוח החומרי יתפשט צורת השכל כו' אבל אין כחות הללו עצם הנפש רק שתרד להיות צורה לחומר בלבד כמו התלבשות כח הצומח בגרעין לפי מה שהוא כנ\"ל וד\"ל.\n<b>והמובן</b> מכל משלים האלה מגרעין הנזרע או מחיות הנפש באברי' החומריי' שא\"א שיתהווה מציאת דבר בהגשמה מכח הרוחני בלתי אם לא שיהי' מוכן לו חומר להורידו ולהמשיכו ואז יתלבש בו כו' והוא טעם הזריעה שבלעדה לא יצמח מאומה מן כח הצומח אבל ע\"י הזריעה יתלבש כח הצומח בכמה חילוקי מדריגות גשמיות כמו ריבוי מיני פירות חמוצים ומתוקים חלוקים למיניהם לרוב שמתהווה הכל מכח הצומח כו' והנמשל מכ\"ז יובן ג\"כ למשכיל למעלה בבחי' אור הזרוע לצד\"ע שהוא בחי' המצות<sup data-n=\"649\">8</sup> שנק' רמ\"ח אברי' דמלכא ועד\"מ הנ\"ל באברי' החומריי' שהמה מורידים וממשיכים אליהם מאור וחיות הנפש הרוחניות להיות מתלבש בהם לצורה וחיות כו' ובלעדם לא יתכן לומר שיש התהוות כחות אלה בנפש כו' וכך יובן למעלה דהנה ידוע בע\"ח דעצמות אא\"ס ב\"ה הוא למעלה מכל ההשתלשלות דע\"ס דאבי\"ע וגם העולמות שלפני האצי' בקו וחוט כו' אין להם ערך",[["648","7","<b>שבפעולת ותמונת</b>: בכת\"י ב': שבפעולת תכונות."],["649","8","<b>המצות שנק' רמ\"ח אברי' דמלכא</b>: ראה ת\"ז תי' ל. זח\"ב קיח, א. וראה תניא פ\"ד ובליקוט פירושים ומ\"מ שם."]]],[2101000118,"כלל לגבי העצמות גם לא כערך טפה בים כו' שהרי הוצרך להיות בחי' צמצום הנק' מקו\"פ וחלל ריקן כו' בעצמו' אוא\"ס תחלה כדי שיוכל להאיר בקו\"ח כו' כידוע, והיינו מפני שאין ערוך כלל בין עצמות אור א\"ס לבחי' ההארה בעלמא הנבדל מעצם אורו להיות מקור להשתלשלו' הנק' קו\"ח כו' וע\"כ ידוע שכל חילוקי המדריגות דאבי\"ע ע\"י בחי' הקו\"ח שיש בו בחי' מעלה ומטה שוין ממש קמי' העצמות כמ\"ש קטן<sup data-n=\"650\">9</sup> וגדול שם הוא כו' משום דקמי' כחשיכה כאורה רוחניות וגשמיו' אצי' ועשי' שוין מטעם שהוא מושלל בערך לגמרי מכל עיקר ההשתלשלות דקו הנ\"ל ועד\"מ עצם הנפש שהיא מושללת מבחי' הגשמת מציאת כח הראי' ושמיעה וכה\"ג כנ\"ל, אך הנה בתחלת ההשתלשלו' עלה ברצונו הפשוט להאציל ולברוא כו' והוא הנק' חפץ חסד שמצד טבע הטוב להטיב כמ\"ש<sup data-n=\"651\">10</sup> בע\"ח והוא בחי' המחה\"ק שנק' רצון קדום שעלה בעצמותו שהוא למעלה עדיין מכל ההשתלשלות שנמשך ע\"י הקו הנ\"ל כי בחי' המחה\"ק הזאת היא בחי' מקיף וסובב לכל ציור הד' עולמות שבקו הכל בהשוואה א' וכידוע שזהו פי' המאמר בריש<sup data-n=\"652\">11</sup> הורמנת' דמלכא כו' שהוא בחי' רצון הפשוט ונזכר<sup data-n=\"653\">12</sup> בזוהר בכמה דוכתי בלשון כד סליק ברעות' כו' אך אח\"כ תלוי במעשה התחתונים וכמ\"ש בע\"ח דהיינו ע\"י המצות וכיוצא מעוררי' לבחי' התגלות רצה\"פ הנ\"ל שיבא מן ההעלם לגילוי אור בקיום תמידי והוא בחי' המשכת הקו הנ\"ל להאציל ע\"ס כו' כמו להיות נק' חכים בחכ' דאצי' ומבין בבינה דאצי' כו' אבל מצד עצמו לאו<sup data-n=\"654\">13</sup> דאית לי' מכל אינון מדות כלל כי אוא\"ס פשוט הוא בתכלית למעלה גם מהיות מקור לאצי' כנ\"ל וה\"ז ממש כמו דמיון הארת הנפש באברי הגוף שבלעדי העלאת כלי החומר לא יומשך הצורה וז\"ש אי אנת תסתלק מנייהו אשתארו כגופא בלא נשמתא כו' והכנת הכלים הן הנה רמ\"ח פיקודי' שנקראי' רמ\"ח אברי' דמלכא שעל ידן יומשך אור א\"ס הפשוט ההיולי שבמחה\"ק להיות מתלבש ובא בכלים מכלים שונים כו', וז\"ש אשר<sup data-n=\"655\">14</sup> יעשה אותם האדם וחי בהם פי' האדם האדם דלעילא שהוא בחי' ז\"א שע\"י המצות שנק' רמ\"ח אברים יומשך בו תוס' גילוי אא\"ס וחי בהם ממש כי לפעמים ג\"כ יבא בחי' תוס' גילוי אא\"ס באצי' בתוס' מרובה על העיקר ובפרט כשצריך להיות שינויים כמו מהתהפכות מדה\"ד למדה\"ר כמ\"ש יהי רצון מלפניך שיכבשו רחמיך את כעסך כו' או בהיפוך האור בכלי היפכו כמו אור<sup data-n=\"656\">15</sup> החסד בכלי הגבורה כו' שהוא לאכללא<sup data-n=\"657\">16</sup> שמאלא בימינא כו' ובפרט לצורך תולדות אורות חדשים לגמרי כמו להוליד נשמות חדשות שצ\"ל יחוד או\"א וזו\"נ בבחי' מוחין חדשים ששרשם מאור א\"ס שלפני הצמצום כו' והיינו כמו עד\"מ הנ\"ל בזריעת הגרעין שיצמח עי\"ז מכח הצומח פירות חלוקים",[["650","9","<b>קטן וגדול שם הוא</b>: איוב ג, יט."],["651","10","<b>כמ\"ש בע\"ח</b>: שער א ענף ב. ובכ\"מ."],["652","11","<b>בריש הורמנתא דמלכא</b>: זח\"א טו, א. ת\"ז תי' ה."],["653","12","<b>ונזכר בזוהר. . כד סליק ברעות'</b>: זח\"א פו, ב."],["654","13","<b>לאו דאית לי' מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה ד\"ה פתח אליהו."],["655","14","<b>אשר יעשה אותם האדם וחי בהם</b>: ויקרא יח, ה."],["656","15","<b>אור החסד בכלי הגבורה</b>: זח\"א פז, א. ובמק\"מ שם."],["657","16","<b>לאכללא שמאלא בימינא</b>: ראה זח\"ג קעו, א. ובכ\"מ."]]],[2101000119,"בטעמי' גשמיי' חמוצים או מתוקים לפי שמתלבש כח זה בגרעין להיות כמו צורה לחומר כו' אבל אין זה עצם מהותו כי הכח הזה הוא רוחני והיולי כו' כך עצמו' אור א\"ס הוא מושלל מכל בחי' אור הנאצל בבחי' מציאת דבר מה כמו חו\"ג וכמ\"ש לך<sup data-n=\"658\">17</sup> ה' הגדולה והגבורה כו' רק שמעוררי' אורו לירד ולהתלבש להצמיח אור במציאות להיות לו כמו צורה כו' אבל אין זה מעצמות מהותו כלל אלא כמו כח הצומח שמתלבש להצמיח טעם חמיצות כו' רק שע\"י הזריעה של הגרעין ירד ונתלבש בו כו' וכך ע\"י זריעת אור לצד\"ע במעשה המצות גורם שיומשך אור א\"ס באצי' ולכך נמשלו המצות לבחי' זריעה דוקא וד\"ל. והמופת לזה הוא מה שנאמר בכל פ' ופ' של כל מצוה וידבר ה' אל משה ויאמר ה' אל משה דבר אל בנ\"י לאמור, פי' ויאמר ה' שנמשך אוא\"ס בשם הוי' דחכ' שהוא בחי' משה כידוע ואח\"כ נמשך לבנ\"י שהן בחי' נו\"ה דז\"א לאמור לבחי' מל' שהוא שרש בנ\"י כידוע וזהו כללות עולם האצי' כידוע דשם הוי' כולל כל האצי' יו\"ד בחכ' כו' וד\"ל.\n<b>ובכ\"ז</b> יובן הטעם למה נק' המצות בשם פירות דוקא כמארז\"ל בענין עגלה ערופה שלא הניחו לעשות פירות כו' שהן המצות כי המצות הן בבחי' זריעה כמו הזריעה של הגרעין שיולידו ויצמיחו מיני פירות הרבה כך מעשה המצות יולידו ויצמיחו למעלה כמה מיני המשכות אורות עליונים מעצמות אא\"ס שלפני הצמצום שמתלבש למטה באצי' כנ\"ל וד\"ל. וזהו פי' וצדקה כנחל איתן דגם בנחל איתן שלא יזרע הנה הצדקה תצמיח גם שם פירות הרבה דהיינו גם בהעדר מעשה התחתונים מן המצות מ\"מ ע\"י הצדקה<sup data-n=\"659\">18</sup> ששקולה כנגד כל המצות יהי' אור זרוע לצד\"ע גם בנחל איתן כו' וכמ\"ש כי<sup data-n=\"660\">19</sup> כארץ תוציא צמחה כו' כן יצמיח ה' צדקה כו' (ולזה הטעם הורידו זקני העיר אל נחל איתן דוקא כמ\"ש יבא מי כו' וד\"ל).\nב) <b>ולהבין</b> בתוס' ביאור בענין המצות איך שהן כדמיון הזריעה כנ\"ל הנה אנו רואים במצות הקרבת העומר שציוה להקריב מנחת העומר שני עשרונים וכבש בן שנתו ויין רביעית ההין והי' הכהן מקריב את הכבש ע\"ג המזבח והניף את העומר וכו' וע\"י זה הקרבן ואחריו ימי הספירה של העומר יוכל להיות אח\"כ בחג השבועות בחי' גילוי אור עליון מבחי' הכתר כמ\"ש בפע\"ח ובלעדי זה הקרבן של העומר עם כל פרטי אופניו הנ\"ל ועם ימי הספירה וכמ\"ש וספרתם<sup data-n=\"661\">20</sup> לכם ממחרת השבת כו' לא יוכל להיות בחי' המשכת גילוי אור הכתר בשבועות, ולכאורה אין להשגת שכל אנושי כח להשיג דבר זה איך ע\"י הקרבת כבש גשמי ויין ומנחה גשמיי' יהי' סיבה להתעוררו' גילוי אור עליון כזה. אך הענין הוא דהנה כללות ענין הספירה ידוע שהוא בחי' העלאות מז' מדות דנוגה שהוא בחי' עומר שעורי' כמשי\"ת כי הנה מבואר למעלה דביום א' דפסח הי' בחי' הדילוג כמ\"ש ופסח ה' על הפתח והיינו שהי' המשכת אוא\"ס שלא בדרך השתלשלות בלא אתדל\"ת כלל אך ביום ב'",[["658","17","<b>לך ה' הגדולה והגבורה</b>: דה\"א כט, יא."],["659","18","<b>הצדקה ששקולה כנגד כל המצות</b>: ירושלמי פאה פ\"א ה\"א."],["660","19","<b>כי כארץ תוציא צמחה</b>: ישעי' סא, יא."],["661","20","<b>וספרתם לכם ממחרת השבת</b>: ויקרא כג, טו."]]],[2101000120,"דפסח ציוה לספור ז' שבועות כמ\"ש ממחרת השבת תספרו כו' דהיינו שיהי' בחי' העלאו' באתדל\"ת דוקא ועי\"ז יהי' בחי' המשכות מז' מדות דאימא שנק' נשע\"ב שהוא לנגד מ\"ט פעמים מצרים שנז' בתורה וחג השבועות הוא שער הנו\"ן שממילא מתגלה כמ\"ש במ\"א באריכות. וזהו פי' היום יום כו' פי' בכל יום ממשיכים מז' מדות דבינה באמרו היום יום כידוע<sup data-n=\"662\">21</sup> דגי' דיום הוא נ\"ז ע\"ה שהוא גי' דאל הוי' והוא בחי' פנימי' המשכה לעומר שהוא שם ב\"ן שמוסתר בעולמות וזהו היום יום א' או ב' לעומר כו'.\n<b>והנה</b> הטעם שהיתה המנחה משעורים דוקא ולא מחיטים יש להקדים תחלה מ\"ש אדם<sup data-n=\"663\">22</sup> ובהמה תושיע ה' שהוא בחי' מ\"ה וב\"ן כי מ\"ה בגי' אדם ובהמה בגי' ב\"ן והיינו כמ\"ש כי<sup data-n=\"664\">23</sup> רוח האדם כו' ורוח הבהמה יורדת למטה כו', דהנה בחי' מל' דאצי' בהיותה בבחי' האצי' קודם ירידתה לבריאה נק' אדם וכמ\"ש ועל<sup data-n=\"665\">24</sup> הכסא דמות כמראה אדם כו' וכן ופני<sup data-n=\"666\">25</sup> אדם לארבעתן כו' לפי שבחי' אדם הוא בחי' מדבר שנק' נפש המדברת וכך למעלה כתיב ויהי<sup data-n=\"667\">26</sup> האדם לנפש חי' ותרגומו לרוח ממללא שהוא בחי' דיבור העליון שבי' מאמרות כמ\"ש ויאמר אלקים וכמ\"כ בדבר<sup data-n=\"668\">27</sup> ה' כו' אבל כאשר בחי' המל' יורדת להשפיע למטה ומתלבשת בבריאה ששם פעולת ההמשכה אינו אלא להוות המלאכים וחיות כו' נמשלה לבחי' בהמה כמ\"ש ורוח הבהמה יורדת למטה והוא הנק' בחי' ב\"ן וכמ\"ש דוד שהוא בחי' מל' דבריאה ואני<sup data-n=\"669\">28</sup> בהמות הייתי עמך כו' ושם נאמר בהמות<sup data-n=\"670\">29</sup> בהררי אלף כו' ובחי' המל' נק' שם בחי' בהמה<sup data-n=\"671\">30</sup> רבה דרביע' על אלף טורין ושתת לון בגמיע' חדא וז\"ש מצמיח<sup data-n=\"672\">31</sup> חציר לבהמה כמ\"ש בזוהר ולפי המשל הזה שנק' המל' שבבריאה בשם בהמה נק' גם בחי' המאכל שלה מאכל בהמה (וע\"ז רמזו רז\"ל דאסור<sup data-n=\"673\">32</sup> לאדם לאכול שהוא בחי' מאכל אדם בחי' מ\"ה עד שיתן מאכל לבהמתו שהוא שם ב\"ן כמ\"ש במ\"א) והיינו בחי' השעורים שנק' מאכל בהמה ועד\"מ המאכל הגשמי שהוא מזון לחיות הנפש הרוחניות של הבהמה כך בחי' המאכל העליון של בחי' שעורים הוא בחי' מזון וחיות פנימי' לבחי' בהמה העליונה שהוא בחי' שם ב\"ן בגי' בהמה כנ\"ל. וזהו מ\"ש<sup data-n=\"674\">33</sup> בזוהר בפי' שעורה שיעור ה\"א פי' ה\"א הוא בחי' מל' ה\"א אחרונה דשם הוי' כמ\"ש",[["662","21","<b>כידוע דגי' דיום. . דאל הוי'</b>: ראה מאו\"א אות יום ס\"ח."],["663","22","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז."],["664","23","<b>כי רוח האדם</b>: ראה קהלת ג, כא."],["665","24","<b>ועל הכסא דמות כמראה אדם</b>: יחזקאל א, כו."],["666","25","<b>ופני אדם לארבעתן</b>: ראה יחזקאל א, י. והערת כ\"ק אדמו\"ר זי\"ע בהמשך מים רבים תרל\"ו ע' נא."],["667","26","<b>ויהי האדם לנפש חי'</b>: בראשית ב, ז."],["668","27","<b>בדבר ה'</b>: תהלים לג, ו."],["669","28","<b>ואני בהמות הייתי עמך</b>: תהלים עג, כב."],["670","29","<b>בהמות בהררי אלף</b>: תהלים נ, י."],["671","30","<b>בהמה רבה דרביע' על אלף טורין</b>: זח\"א יח, ב."],["672","31","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד."],["673","32","<b>דאסור לאדם לאכול. . עד שיתן מאכל לבהמתו</b>: ברכות מ, א. ובכ\"מ. וראה לקו\"ת בחוקותי לט, ב."],["674","33","<b>מ\"ש בזוהר בפי' שעורה שיעור ה\"א</b>: זח\"ג קפח, ב."]]],[2101000121,"בהבראם<sup data-n=\"675\">34</sup> בה' בראם ובחי' השיעור של הה\"א היינו בחי' הפנימי' של בחי' הה\"א והוא בחי' המשכת האור מלמעלה שיהי' חפץ המאציל במדה זו להיות מלך על עם כענין הידוע בפי' אמרו<sup data-n=\"676\">35</sup> לפניו מלכיות כו' דהיינו שמעוררי' מלמטה שיהי' רצון המאציל במדת המלוכה דבאמת הלא ממך<sup data-n=\"677\">36</sup> הכל כתיב ואין לך דבר חוץ ממנו ואיך שייך בחי' מלוכה כו' רק שנמשך רצון לזה באתדל\"ת כמו ע\"י המלאכים שעושין הכתר כמו כתר יתנו לך וכמו מט\"ט<sup data-n=\"678\">37</sup> שיושב וקושר כתרים וז\"ש גיבורי כח עושי דברו<sup data-n=\"679\">38</sup> כו' כמ\"ש<sup data-n=\"680\">39</sup> בזהר<sup data-n=\"681\">40</sup> ע\"פ שחורה אני כו' ומטעם זה נק' שעורה שיעור ה\"א.\n<b>אך</b> לכאורה איך יתכן שהנבראים בע\"ג יעוררו רצון אור עליון שיומשך במדת המל' ונק' מזון וחיות אור פנימי הנ\"ל, הענין הוא לפי שבחי' העלאות מ\"נ דמלאכי' ונשמות מלמטה הכל בא מבחי' בירורי' דנוגה מהתהפכות חשוכא לנהורא בבחי'<sup data-n=\"682\">41</sup> ביטול היש כידוע וזה ידוע דשרש הדברים הגשמיי' דנוגה ששרשם מפני שור פני ארי' כו' נמשכו מבחי' ז' מלכים דתוהו שהוא בחי' ב\"ן דתוהו שנק' בשם בהמות וחיות ג\"כ (וכמו בחי' בהמה רבה שלפני האצי' כו') ובז' המלכים נאמר לפני מלוך מלך לבנ\"י שהן למעלה מבחי' התיקון דאדם בגי' מ\"ה ע\"כ בהעלאת מ\"נ דבירורי נוגה דוקא יומשך עי\"ז בחי' רצון ואור עליון לבחי' המל' ונק' שעורה שיעור ה\"א שהוא בחי' פנימי' המל' ולמטה נק' שעורים מאכל בהמה דנוגה וזהו כללות ענין עומר שעורים שנעשה בחי' מאכל לבהמה בגי' ב\"ן כו', אבל בחי' מאכל אדם בגי' מ\"ה הוא הנק' חטה כמ\"ש בזוהר שהיא כ\"ב אתוון דאוריי' כי בחי' אדם הוא בחי' מדבר שהוא בא מבחי' החכ' הנק' נפש השכליות ואין בחי' הדיבור בא רק ע\"י בחי' מזון וחיות פנימי לאדם העליון והיינו כ\"ב אתוון דאוריי' ששרשם בבחי' פנימי' החכ' עד\"מ התינוק שאינו יודע לדבר ולקרות אבא כנ\"ל וכיוצא עד שיטעום טעם דגן דוקא לפי שהלחם שרשו בבחי' פנימי' חכ' וע\"כ נק' חטה בחי' מזון לאדם העליון בבחי' הפנימי' ונק' מאכל אדם כמו ששעורה הוא בחי' פנימי' לבחי' בהמה העליונה בחי' ב\"ן כנ\"ל (וע\"כ אמרו דאסור לאדם לאכול עד שיתן מאכל שעורי' לבהמתו בחי' ב\"ן וכמ\"ש אדם ובהמה תושיע כו' וד\"ל). ומעתה יובן למה הי' העומר קרב משעורים דוקא ולא מחיטים כי הנה החטים הוא בחי' מאכל אדם כנ\"ל אבל ביום ב' דפסח ציוה ה' שיהי' בחי' אתדל\"ת דוקא ע\"י הקרבן והספירה כנ\"ל שהוא בחי' ההעלאות מנוגה בהיפוך חשוכא לנהורא כו' כל ימי הספירה כנ\"ל וע\"כ הקריבו מן השעורים דוקא שהוא מאכל בהמה דהיינו מבחי' העלאת מ\"נ שבא מבירורי' דנוגה כמו בהמה דרביע' כו' ושתת לון כו' וזהו והניף<sup data-n=\"683\">42</sup> את העומר כו' שנתעלה",[["675","34","<b>בהבראם בה' בראם</b>: מנחות כט, ב."],["676","35","<b>אמרו לפני מלכיות</b>: ר\"ה טז, א."],["677","36","<b>ממך הכל</b>: דה\"א כט, יד."],["678","37","<b>מט\"ט שיושב וקושר כתרים</b>: זח\"א לז, ב. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 202."],["679","38","<b>גבורי כח עושי דברו</b>: תהלים קג, כ."],["680","39","<b>כמ\"ש בזוהר ע\"פ שחורה אני</b>: זח\"ג קצא, א. וראה ביאוה\"ז שם."],["681","40","<b>כמ\"ש בזוהר שהוא כ\"ב אתוון דאורייתא</b>: ראה זח\"ג קפח, ב."],["682","41","<b>בבחי'</b>: בכת\"י ב: והיינו בבחי'."],["683","42","<b>והניף את העומר</b>: ויקרא כג, יא."]]],[2101000122,"להיות בחי' מאכל לבהמה בחי' ב\"ן ועי\"ז יהי' בחי' המשכות בכל ימי הספירה באמרו היום יום כו' מנש\"ב כנ\"ל ואז יוכל להיות גילוי שער החמישים שהוא הארת הכתר דז\"א כו' בחג השבועות ובלעדי זה לא יוכל להיות גילוי זה כו', והטעם הוא כי שרש השעורים מאכל בהמה שלמטה וכן הכבש והיין כו' שרשם מבחי' ב\"ן דתוהו שלפני התיקון כנ\"ל וכאשר עולה למעלה לריח ניחוח באש שלמעלה שיורד ואוכל כידוע אזי עולה לשרשם שבבחי' התוהו ועי\"ז נמשך אור עליון חדש מלפני האצי' בשבועות, והגם שהכבש והשעורי' הן גשמיי' היינו מפני שבה\"כ דתוהו שנשברו וירדו ונתגשמו למטה אבל כשעולין לשרשם בבחי' התוהו הרי נאמר א\"ח ע\"ב נקבה תסובב גבר כנ\"ל לפי שבחי' ב\"ן דס\"ג גבוה משם מ\"ה דתיקון כמ\"ש לפני מלוך מלך לבנ\"י כו' כנ\"ל וד\"ל.\n<b>ועם</b> כל הנ\"ל יובן בתוס' ביאור לדוגמא מזה לכל המצות שהן נמשלים לבחי' זריעה דוקא שהרי כמו הגרעין שהוא גשמי ואין בו חיות כלל כשזורעין אותו מתלבש בו כח הצומח ומצמיח הרבה כמוהו לפי שהגרעין הזה הי' בפרי תחלה והפרי יצא מכח הצומח מן הרוחניות אל הגשם ע\"כ ברקבון הגרעין בארץ ונכלל בכח הצומח חוזר וניעור כח הרוחני שבכח הצומח שהוליד והצמיח פירות כבר שיחזור ויתלבש בגרעין זה להוליד מחדש אמנם כשיזרעו דבר אחר לא יצמיח גרעיני חטה או פירות מטעם שצ\"ל בחי' העלאה והתכללות של דבר הנזרע מעין אותו הכח המצמיח הרוחני דוקא וככה יובן בנמשל בבחי' העלאה ובירורי' דרפ\"ח ניצוצות דתוהו שנפלו בשבירה עד בחי' נוגה דבי\"ע דמשום שקודם השבירה היו הניצוצים הללו בבחי' ב\"ן דתוהו ע\"כ גם בירידתן למטה כאשר יקריבו אותן ע\"ג המזבח כמו השעורים והכבש ששרשם מבחי' התוהו ויוכלל באש שלמעלה בשרשם הראשון ה\"ז כמו התכללות הגרעין בכח הצומח וחוזר וניעור עי\"ז כח אורות דתוהו להאיר אור עליון מחדש בשם מ\"ה דתיקון וז\"ש ריח ניחוח להוי' דתיקון וכמ\"ש במ\"א, וזהו הטעם לכל פרטי אופני הקרבת העומר שעורים וכבש כדי שיהי' באופן שיומשך עי\"ז אח\"כ מלמעלה למטה כאופן ההעלאה עד\"מ כמו בזריעה שיצמיח כאופן דבר הנזרע ובתנאי שדבר הנזרע כבר הי' בהתכללות בכח הצומח כך מפני ששרש הכבש הי' תחלה בבחי' התוהו שנק' בהמות וחיות ע\"כ יש בכחו לאחר שיוכלל למעלה לעורר המשכת אור מבחי' התוהו בתיקון כו' וד\"ל. ומכל הנ\"ל בענין המצוה דקרבן עומר י\"ל בדרך פרט בכל מצוה ומצוה בטעם אופני פרטי מעשיה שהכל הוא בבחי' זריעה אלא שיש כמה חילוקי מדריגות כו' ובכלל נק' כל המצות תר\"ך עמודי אור פי' עמודים כמו עמוד המחבר קרקע לגג והוא בחי' ממוצע ביניהם כך בחי' הכתר ממוצע בין עצמות אא\"ס לנאצלים לחבר עצמות אא\"ס בנאצלים והמחברים נק' עמודי אור והן המצות שנמשלים לזריעה שעי\"ז מתחבר כח המשפיע להוליד ולהמשיך מן ההעלם לגילוי כנ\"ל וד\"ל.\nג) <b>ומעתה</b> י\"ל בתוס' ביאור מ\"ש מקפץ על הגבעות וכמ\"ש וגבעות בצדקה כנ\"ל דהנה המצות נק' בשם צדקה כי כמו שצדקה היא להחיות רוח שפלים למאן דלית לי' מגרמי' כלום כך המצות הן בחי' המשכות אורות עליונים בכלים"],[2101000123,"מכלים שונים כידוע שנק' רמ\"ח אברי' דמלכא. אך הנה מ\"ש מקפץ על הגבעות שהן האמהות ששרשם מבחי' ב\"ן דתוהו כנ\"ל בקפיצה בב' רגלים ובהרים אמר ברגל א' כו' הנה יש להקדים תחלה לתרץ הקושי' הנ\"ל דלפעמים משמע שהמצות נק' בשם לבושים בבחי' א\"מ ולפעמים משמע שהן בבחי' א\"פ כמו כאשר נק' בשם פירות כנ\"ל, אך הענין הוא דשרש המצות הוא בחי' ה\"ח כלליי' ונחלקים לרמ\"ח לפי שה\"ח מגדילים האברים להיות כל ספי' כלולה מט' וג\"פ ט' פעמים ט' עולה רמ\"ג<sup data-n=\"684\">43</sup> וע\"ה דה\"ח עולה רמ\"ח כמ\"ש בע\"ח<sup data-n=\"685\">44</sup>, והנה בחי' ה\"ח הללו נחלקים לב' מדריגות הא' בא בבחי' השפעות או\"פ והב' בא בבחי' השפעת או\"מ שנק' בחי' לבושים וההפרש שיש ביניהם ידוע בזה האור והשפע שבא בבחי' או\"פ נעשה בחי' חיות פנימי' ממש אבל האור הבא בבחי' מקיף הגם שהוא חסד גמור אבל אינו נכנס להיות בבחי' פנימי' החיות ממש אלא הוא רק כמו בחי' מלבוש מבחוץ בבחי' חיצוניות והוא בחי' הלבושים שנעשין לנשמה בג\"ע ע\"י המצות כמ\"ש בע\"ח שתוכל ליהנות מזיו השכינה בבחי' מזון פנימי כי בלתי לבוש לא תוכל לקבל מזיו זה וכענין ויבא משה בתוך הענן כמ\"ש במ\"א וכמ\"ש<sup data-n=\"686\">45</sup> בזוהר ע\"פ ואברהם ושרה זקנים באים בימים באינון לבושין כו' אבל מאחר שנעשה בחי' לבוש להלביש בחיצוניות בהכרח ששרש זה הלבוש בא ממדריגה יותר עליונה מבחי' זיו זה שמקבלת בבחי' א\"פ והיינו מבחי' או\"מ שנעשה בחי' לבושי' כידוע והיינו מ\"ש וימינו תחבקני בחי' חסד העליון שהוא בבחי' מקיף נק' ימינו שהוא יורד מגבוה לנמוך לחבק את הנשמה בבחי' חיצוניו' וכמ\"ש ה'<sup data-n=\"687\">46</sup> צילך על יד ימינך כו', אמנם זוהי מעלה יתירה שבמקיף יותר מבפנימי שיוכל לירד למטה מטה מאד עד שמחבק גם בבחי' חיצוניו' ביותר (וכמו וימינך פשוטה לקבל שבים) וכמו אברהם איש החסד שאמר לו ישמעאל חסד דקליפה יחי' גם הוא כו' משא\"כ בחי' או\"פ שלא ירד רק לפי הראוי במדה קצובה כו', והיא הנותנת דמשום שבחי' מקיף הוא רק הלבשה חיצוניות כמו הלבוש גשמי שנפרד מהאדם שהרי אם ילבש אדם כמה לבושים לא יתוסף בו שום חיות כלל ע\"כ ירד גם למטה להגין על הכל כו' אבל בחי' א\"פ שהוא בא בבחי' פנימי' החיות ע\"כ לא יבא רק כפי הכלי הראוי' לכך כו' וד\"ל.\n<b>והנה</b> הגם שיש מעלה במקיף משא\"כ בפנימי שיורד למטה מטה מאד אבל לנגד זה יש מעלה גדולה בפנימי משא\"כ במקיף והוא במה שבחי' או\"פ נעשה בבחי' פנימי' החיות כנ\"ל היינו מפני שפנימי' שפע זו באה מכח שהוא נמשך בתגבורת גדולה והוא הנק' בחי' גבורות עליונות כו' כי הנה כתיב לך<sup data-n=\"688\">47</sup> ה' הגדולה והגבורה כו' וידוע שהגדולה הוא בחי' מדת החסד ובהכרח לפ\"ז שהגבורה הוא",[["684","43","<b>רמ\"ג</b>: בכת\"י ב וכת\"י ג: רמ\"ב. והוא טעות דמוכח."],["685","44","<b>הלבושים שנעשי' לנשמה. . כמ\"ש בע\"ח</b>: ראה ע\"ח שער מ\"ד פ\"ג ועוד. זח\"ב רכט, ב. רי, א. תניא פ\"ה. אגה\"ק סכ\"ט. ובכ\"מ. וראה בהנסמן להלן."],["686","45","<b>וכמ\"ש בזוהר ע\"פ ואברהם ושרה זקנים</b>: ראה זח\"א רכד, א. ובכ\"מ. וראה בהנסמן בד\"ה ואברהם זקן תשל\"ח ס\"א (נדפס בסה\"מ מלוקט ח\"א ע' רפט)."],["687","46","<b>ה' צילך על יד ימינך</b>: תהלים קכא, ה."],["688","47","<b>לך ה' הגדולה והגבורה</b>: דה\"א כט, יא."]]],[2101000124,"מדה\"ד והעונש אבל באמת אין פי' האמיתי כן דהא פי' הפשוט דגבורה היינו בחי' התגברות כח כמו הגיבור שנק' גיבור מפני כחו הגדול ואין זה שייך לענין מדה של דין ועונש אך מסתעף ממנה מדה\"ד, והענין הוא כי פי' גבורה הוא בחי' תגבורת הכח והעוז ואדרבא מכח זה שנק' גבורה נשפע ונמשך פנימי' שפע וחיות לכל דבר הצריך חיות וכח ממש להיות כי שרש החיות הפנימי' נמשך ממדה זו הנק' כח וגבורה להיותו בבחי' תגבורת גדולה הוא מקור כל חיות ושפע פנימי' ולעולם לא ימצא כל שפע פנימי' החיות רק ממדת הגבורה דוקא כמו המזונות שחיי אדם תלויי' בהן נמשכי' מבחי' גבורות דוקא כידוע<sup data-n=\"689\">48</sup> בזוהר שולחן בצפון כו' וכן על שולחן המלך כו' וכן ארז\"ל דבני<sup data-n=\"690\">49</sup> חיי ומזונא במזלא תלי' שהוא בחי' הגבורו' ולא בזכותא שהוא היכל החסד כו', ודוגמא לדבר זה למעלה הנה אנו רואים למטה בדם שהוא הנפש להחיות כל הגוף והדם הוא חם ויבש בטבעו וכל שחמימות שלו בתגבורת יותר יתפשט להחיות בכח רב וחזק יותר והזקן שנתמעט החום שבדמו נתמעט חיותו וכחו כידוע, וכך יובן למעלה שכל בחי' השפעות הבאים בבחי' אור חיות רב הכל בא מבחי' גבורות עליונות דוקא כמ\"ש אתה<sup data-n=\"691\">50</sup> גיבור כו' ובברכה זו נזכר גבורות גשמים ותחה\"מ כו' וכמ\"ש להודיע<sup data-n=\"692\">51</sup> לבנ\"א גבורותיו ואז כבוד הדר מלכותו מתפשטת כו' וכמ\"ש במ\"א באריכו' וז\"ש לך ה' הגדולה שהוא בחי' חסד הבא בקרירות כמים שיורדי' מגבוה לנמוך כנ\"ל בפי' וימינו תחבקני כו' והגבורה הוא בחי' תגבורת החסד שבאה להיות בחי' פנימי' אור וחיות רב כנ\"ל, ונמצא שיש מעלה יתירה בגבורות יותר מבחסדים בדבר זה והוא ההפרש שבין בחי' או\"פ לבחי' או\"מ דהנה בחי' הא\"פ נמשך מבחי' הגבורות אחר שנמשך להיות בבחי' פנימי' החיות והאו\"מ נמשך מבחי' החסד עצמו והוא המעלה שיש בא\"פ משא\"כ בא\"מ כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> מתורץ הקושי' הנ\"ל דלפעמים המצוות בבחי' לבושי' דא\"מ והוא מ\"ש וימינו תחבקני כנ\"ל ולפעמים המצות שיורד למטה מאד אבל אינו אלא בחי' הלבשה חיצוני' כנ\"ל ולפעמים המצות הן בחי' א\"פ להיות בבחי' מזון וחיות פנימי' כמו פירות וכה\"ג והוא האור הנמשך מבחי' גבורה שבחסד כו' שבאים בתגבורת גדולה יותר מהחסדי' כנ\"ל וד\"ל. והנה כאשר המצות נק' בבחי' א\"פ כמזון ופירות וכה\"ג ה\"ז כמו משל הזריעה הנ\"ל שהוא ג\"כ בא בבחי' או\"פ כאור זרוע שבא מבחי' הגבורות וכענין גבורות גשמי' שמצמיחים ואין<sup data-n=\"693\">52</sup> לך טפה כו' שאין טיפיים עולין כנגדה בבחי' א\"ח והצמיחה מכח הצומח בא ע\"י בחי' גבורות ג\"כ כמו אור הזרוע כו' וכמ\"כ כאשר המצות נק' רמ\"ח אברים דמלכא כנ\"ל שמקבלי' חיות פנימי כמו הדם הוא הנפש שמחי' לאברים כו' וד\"ל. אך הנה כ\"ז האור הנמשך מבחי' הגבורות",[["689","48","<b>כידוע בזוהר. . על שולחן המלך כו'</b>: שמואל ב ט, יג. וראה זח\"ב קנג, א. קנו, ב. וראה תו\"ח תרומה ד\"ה ועשו לי מקדש. אוה\"ת ויקהל ע' ב'קפח, וע' ב'רי."],["690","49","<b>דבני חיי ומזונא במזלא תלי'</b>: ראה מו\"ק כח, א. ובכ\"מ."],["691","50","<b>אתה גבור</b>: תפילת שמו\"ע."],["692","51","<b>להודיע לבני האדם גבורותיו</b>: תהלים קמה, יב."],["693","52","<b>ואין לך טיפה כו' שאין טיפיים עולים כנגדה</b>: ראה זח\"ג רמז, ב. תענית כה, ב. ב\"ר פי\"ג, יג."]]],[2101000125,"א\"א שיתגלה עתה בזמן הגלות לפי שבזמן הגלות יש תוס' יניקה לחיצונים מקו השמאל ע\"י סיבת שבה\"כ דהיינו מבחי' ב\"ן דתוהו שנפל בנוגה כו' והנה מזה נמשך להיות נק' הגבורה בשם מדה\"ד דהנה הגם שבעצם מהותה נק' תגבורת השפע כנ\"ל אך שהיא הנותנת דמשום שכחה גדול ומרומם מאד היא נעשי' שמאל דוחה לדחות למי שאינו ראוי ולהיות דין קשה למנגד אליה ג\"כ בכח הגבורה הזאת כמו הגיבור שבכחו להפיל לשונאו הנלחם עמו ומנגדו וכמ\"ש ה'<sup data-n=\"694\">53</sup> כגיבור יצא כו' וא\"כ כאשר יש תוס' יניקה לחיצוני' כתיב ה' כגיבור יצא כו' וכתיב מי<sup data-n=\"695\">54</sup> זה בא מאדום כו' משום דכתיב ואת<sup data-n=\"696\">55</sup> עשו שנאתי כו' ולעתיד נאמר ואת<sup data-n=\"697\">56</sup> רוח הטומאה אעביר כו' אך עכשיו כל זמן שלא נתבער הרע דעשו והוא שונא לעשו לא יוכל עדיין לבא לידי גילוי מבחי' הגבורות עליונות אך הנה ע\"י הבירורים דנוגה כמו בתשובה דבע\"ת משכי' לי' בחילא יתיר שהוא ג\"כ מבחי' הגבורות יותר מכפי המדה להיות שרשם מבחי' ב\"ן דתוהו כי נה\"ב שרשה מבחי' התוהו כנ\"ל וע\"כ חזק כחה למסור נפשה בבחי' ובכל מאדך שאז יתהפך חשוכא לנהורא כו' אזי יוכל להיות בחי' גילוי גבורות עליונות דתוהו למטה שגדול כחם הרבה מבחי' החסדים כמעלת הזהב על הכסף כמ\"ש מצפון<sup data-n=\"698\">57</sup> זהב יאתה וכידוע דלעתיד יהיו הכהנים לוים והלוים יהיו כהנים כי בחי' הגבורות שרש הלוים יתעלו למעלה מבחי' החסדי' מטעם הנ\"ל להיותו בחי' תגבורת כח גדול ומשם דוקא מקור כל המשכת פנימי' החיו' כו' וד\"ל. ובכ\"ז מובן מ\"ש מקפץ על הגבעות דוקא דבהרים שהן האבות ששרשם מבחי' החסדי' לבד שמצד זה נק' המצות לבושי' כנ\"ל נאמר דילוג ברגל א' הימנית כמ\"ש וימינו כו' אך על הגבעות שהן האמהות ששרשם מבחי' גבורות דב\"ן כנ\"ל נאמר קפיצה בשתי רגלים מפני שהן המצות שנק' בחי' או\"פ כמו פירות וכה\"ג ששרשם מבחי' הגבורות שבא בתגבורת גדולה וכולל ב' הרגלים כא' כו' וד\"ל (וזהו וגבעות בצדקה שכולל לב' מיני מצות הנ\"ל א\"פ וא\"מ וד\"ל).\n<b>ואחר</b> כל הנ\"ל עדיין י\"ל מ\"ש הנה קול דודי הנה זה בא כו' שהנה זה בא משמע לעתיד דוקא דכתיב כימי<sup data-n=\"699\">58</sup> צאתך כו' כנ\"ל ולעתיד הרי יושלמו כל הבירורי' והעלאות מלמטה למעלה עד רום המעלות (ודוגמא לדבר הוא ענין שתי הלחם שבשבועות דכתיב בהו חמץ<sup data-n=\"700\">59</sup> תאפינה להיות שהן כמו ב' מיני מצות הנ\"ל שהוא ביטול שמלמטה למעלה וביטול שמלמעלה למטה רק שבפסח היו של מצה להיותו קודם הבירור שאז החמץ הוא קליפת הגסות כו' אבל בשבועות לאחר הבירור שע\"י ספה\"ע אין החמץ גסות דקליפה אלא נהפך לקדושה בהתנשאו' אלקי' ולכך מצוה לאפותם חמץ כו' וכעין זה יהי' לעתיד שלא יהי' בחי' הסתר מקליפות כלל כו') וא\"כ למה יצטרך אז לבחי' דילוג מלמעלה מהשתלשלות, אך הענין הוא דגם שיבורר הכל בתכלית מלמטה למעלה עד רום המעלות מ\"מ צריך להיות בחי' דילוג מלמעלה",[["694","53","<b>ה' כגבור יצא</b>: ישעי' מב, יג."],["695","54","<b>מי זה בא מאדום</b>: ישעי' סג, א."],["696","55","<b>ואת עשו שנאתי</b>: מלאכי א, ג."],["697","56","<b>ואת רוח הטומאה אעביר כו'</b>: זכרי' יג, ב."],["698","57","<b>מצפון זהב יאתה</b>: איוב לז, כב."],["699","58","<b>כימי צאתך</b>: מיכה ז, טו."],["700","59","<b>חמץ תאפינה</b>: ויקרא כג, יז."]]],[2101000126,"מעלה מבחי' הבירורי' וההעלאו' של רפ\"ח ניצוצו' דתוהו הנ\"ל שאין העלאו' מ\"נ מגיע לשם כלל וכמ\"ש אם<sup data-n=\"701\">60</sup> צדקת מה תתן כו' כי הרי בחי' התוהו והתיקון הנ\"ל אינו אלא לאחר שבא האור והשפע מעצמו' המאציל בהשתלשלות דקו\"ח כו' אבל בחי' עצמיו' דאוא\"ס כמו שהוא קודם שמאיר בקו\"ח כו' לא שייך לומר שם בחי' חילוק מדריגות בין תוהו לתיקון (וזהו שאמר למשה מי<sup data-n=\"702\">61</sup> שם פה לאדם כו' וכמ\"ש במ\"א) אך מ\"מ כל הבירורים והעלאות המה עכ\"פ בחי' הכנה שיהי' עי\"ז בחי' גילוי עצמיות המאציל למטה כמו למעלה והוא כדי שיוכלו לקבל אותו האור ולא יסתירו בחי' הכלים שלהם אבל בחי' דילוג הנ\"ל הי' נצרך לעתיד ג\"כ וז\"ש קול דודי הנה זה בא לעתיד כמ\"ש כימי צאתך כו' אראנו נפלאות כמו ביצי\"מ ממש וד\"ל (וזהו שאנו או' בהגדה ימי חייך הימים כו' וחכ\"א ימי חייך העוה\"ז כל ימי חייך להביא לימוהמ\"ש דגם בימות המשיח שנגלה כבוד ה' כו' מ\"מ יהי' בחי' דילוג הנ\"ל שהי' ביצ\"מ) ולזה הכוונה באמרינו אפס בלתיך גואלינו לימוהמ\"ש ואין דומה לך לתחה\"מ שהוא בחי' בירורי' דתוהו וד\"ל)<sup data-n=\"703\">62</sup>.",[["701","60","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["702","61","<b>מי שם פה לאדם</b>: שמות ד, יא."],["703","62","<b>דתוהו וד\"ל)</b>: בהכת\"י חסר התחלת המוסגר."]]],[2101000127,"<h3>יונתי בחגוי הסלע</h3>\n<b></b><b>בעזר\"ה<sup data-n=\"704\">1</sup> </b>\n(מינסק)\nיונתי<sup data-n=\"705\">2</sup> בחגוי הסלע<sup data-n=\"706\">3</sup> בסתר המדרגה כו'. הנה<sup data-n=\"707\">4</sup> כנ\"י נמשלה ליונה וכמ\"ש עיניך<sup data-n=\"708\">5</sup> יונים כו' פי' עד\"מ הסתכלות היונים זכר ונקבה שמתענגי' זע\"ז מאד בהסתכלות זאת כידוע כך כנ\"י עם הקדב\"ה כתי' עיניך יונים שמתענגי' על ה' לאסתכלא<sup data-n=\"709\">6</sup> ביקרא דמלכא בהתבוננו' בשמחה ותענוג גדול כמ\"ש ישמח<sup data-n=\"710\">7</sup> ישראל בעושיו כו' שמחו<sup data-n=\"711\">8</sup> צדיקי' בה' וכה\"ג והסתכלות זאת הוא בחי' ראי' שכליי' בהשגה אלקי' (כמאמר<sup data-n=\"712\">9</sup> הלב רואה (וכמ\"ש<sup data-n=\"713\">10</sup> בר\"מ בעין השכל דבלבא אתחזי כולא כו')",[["704","1","<b>בעזר\"ה</b>: מאמר זה וחלק מהביאור הראשון נעתק מבוך גוכי\"ק אדמו\"ר האמצעי."],["705","2","<b>יונתי</b>: נדפס בשינויים בס' מאמרי אדה\"ז הנחות הר\"פ ע' קס. ובתוס' הגהות באוה\"ת שה\"ש ע' שיב. ע' של. ע' שלו. שם כרך ג' ע' תתפו ואילך. אוה\"ת בראשית כרך ז' תתשעז, א ואילך. נדפס ג\"כ בשינויים בס' עבודת הלוי ויקרא כא, א. ורשום שם: כי\"ק שכתב שם בעת ששמע מאדמוה\"ז נ\"ע. וראה ג\"כ פלח הרמון שה\"ש מא, א."],["706","3","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["707","4","<b>הנה כנ\"י נמשלה ליונה</b>: שבת מט, א. ועוד."],["708","5","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["709","6","<b>לאסתכלא ביקרא דמלכא</b>: ראה זח\"ב רמז, ב."],["710","7","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["711","8","<b>שמחו צדיקים בה'</b>: תהלים צז, יב."],["712","9","<b>כמאמר הלב רואה</b>: קה\"ר פ\"א, טז. וראה שערי זהר (מרגלית) שם."],["713","10","<b>וכמ\"ש בר\"מ בעין השכל</b>: זח\"ב קטז, ב."]]],[2101000128,"וכמ\"ש ולבי<sup data-n=\"714\">11</sup> ראה כו' והוא בחי' ראי' דחכמה כמ\"ש במשה ויר\"א ראשי\"ת לו<sup data-n=\"715\">12</sup> כו') ובאתדל\"ת מהסתכלו' כנ\"י ביקרא דמלכא כו' נעשה אתדל\"ע בחי' הסתכלו' הקדב\"ה בכנ\"י וכמ\"ש עיני'<sup data-n=\"716\">13</sup> יונים כו' וכמ\"ש עיני<sup data-n=\"717\">14</sup> ה' אל צדיקים וכו' ועד\"מ שמהסתכלו' יונים זכר ונקבה אין התולדה באה מזה כלל רק אח\"כ כשמזדווגי' יחד כו' כך בבחי' הסתכלו' העליונה דכנ\"י שהוא בחי' העונג בראי' שכליית לא יש מזה תולדה אוי\"ר וכיוצא רק הוא מעביר בעלמא כו' (והוא ענין אורו' מקיפי' שלפני היחוד שלא יש מזה תולדה והן למעלה מגוף היחוד כמו עד\"מ חיבוק ונישוק שהוא זיווג רוחני מבחי' מקיפי' רוחא ברוחא<sup data-n=\"718\">15</sup> שלפני זיווג גופני כו' כמ\"ש במ\"א וד\"ל), וזהו שרש ענין פסוקי<sup data-n=\"719\">16</sup> דזמרה עד ק\"ש שמסדרי' שבחו של מקום לאסתכלא ביקרא דמלכא כו' שהוא הכנה לפני ק\"ש (ובק\"ש הוא יחוד עליון כו').\n<b>והנה</b> תחלה יש להבין ביאור המשך הפ' דק\"ש באמרו שמע ישראל ואח\"כ ואהבת כו' ואח\"כ והיו הדברי' האלה כו'. דהנה פי' שמ\"ע הוא בחי' העמקת הדעת כמו הסכ\"ת<sup data-n=\"720\">17</sup> ושמ\"ע כו' וענין ההעמקה הוא בהשגה דגדולת ה' איך שהוא ממלא כ\"ע וסובב כ\"ע וכל זה אינו רק בחי' זיו והארה מעצמותו ממש הנק' שם כידוע, וידוע שיש עליו' העולמות בפרטות עד נ'<sup data-n=\"721\">18</sup> אלפים יובלות כמ\"ש בס' התמונה והכל הוא רק בבחי' גילוי זיוו והודו ית' בלבד ולא מגיע לבחי' עצמותו ומהותו כלל וכמו שאו' אתה<sup data-n=\"722\">19</sup> קדוש ושמך קדוש שגם שמך הוא קדו\"ש ומובדל בערך גם אחר עליו' נ' אלפי' יובלו\"ת הנ\"ל, וקדושים בכל יום יהללו\"ך סל\"ה פי' קדושי' הן ישראל כמ\"ש לקדוש\"י'<sup data-n=\"723\">20</sup> אשר בארץ כו' להיו' כי שרשם עלה במחשבה שהוא בחי' שמ\"ך הנ\"ל וע\"כ הם דוקא נק' קדושי\"ם כמ\"ש והתקדשתם<sup data-n=\"724\">21</sup> והייתם קדושי' כי קדו\"ש אני כו' והם יהללוך שמ\"ך סל\"ה בלי הפסק בעילוי אחר עילוי עד אין שיעור כי אור א\"ס ב\"ה למעלה עד אין קץ בעילוי אחר עילוי וז\"ש סל\"ה והכל בבחי' שמ\"ך בלבד (שהוא<sup data-n=\"725\">22</sup> נק' בחי' מל' דא\"ס) וזהו שארז\"ל<sup data-n=\"726\">23</sup> כי קדו\"ש אני קדושת\"י למעלה מקדושתכ\"ם כו' וד\"ל.\n<b>ואחר</b> התבוננו' כזאת באמרו שמ\"ע ישרא\"ל כו' נולד ממילא אהבה גדולה ברשפי אש התענוג הנק' אהבה בתענוגי' (שלמעלה מבחי' העונג שבהסתכלו'",[["714","11","<b>ולבי ראה</b>: קהלת א, טז."],["715","12","<b>וירא ראשית לו</b>: דברים לג, כא. וראה ת\"י ריש בראשית."],["716","13","<b>עיני' יונים</b>: ראה שה\"ש ה, יב."],["717","14","<b>עיני ה' אל צריקים</b>: תהלים לד, טז."],["718","15","<b>רוחא ברוחא</b>: ראה זח\"ב קכד, ב."],["719","16","<b>פסוקי דזמרה. . שמסדרים שבחו של מקום</b>: ראה ברכות לב, א. ובכ\"מ."],["720","17","<b>הסכ\"ת ושמ\"ע</b>: דברים כז, ט."],["721","18","<b>נ' אלפים יובלות</b>: ראה ג\"כ סה\"מ תקס\"ב ע' יז. תו\"א תצוה פא, ג. ובכ\"מ."],["722","19","<b>אתה קדוש ושמך קדוש</b>: נוסח תפילת שמו\"ע."],["723","20","<b>לקדוש\"י' אשר בארץ</b>: תהלים טז, ג."],["724","21","<b>והתקדשתם והייתם קדושים</b>: ויקרא יא, מד."],["725","22","<b>שהוא נק' בחי' מל' דא\"ס</b>: ראה לעיל ד\"ה קול דודי."],["726","23","<b>שארז\"ל. . קדושתי למעלה מקדושתכם</b>: ויק\"ר פכ\"ד, ט. וראה אוה\"ת ויקרא ע' קה ואילך."]]],[2101000129,"ביקרא דמלכא אשר בפסד\"ז הנ\"ל שאינו אלא בחי' מקיף) וזהו באמרו ואהב\"ת כו' ואח\"כ והיו הדברי' האלה כו', דהנה אמרו ז\"ל עד<sup data-n=\"727\">24</sup> כאן מצות כונה (עד והיו כו') מכאן ואילך מצות קריאה כו', פי' עד כאן עד בכל מאדך מצות כונה בבחי' רצוא מלמטה למעלה מכאן ואילך מוהיו הדברי' כו' מצות קריאה בבחי' שוב מלמעלה למטה כו'. וביאור הדברים הנה אמר בס\"י<sup data-n=\"728\">25</sup> אם רץ לבך שוב כו' וכמ\"ש והחיות<sup data-n=\"729\">26</sup> רצוא ושוב פי' רץ לבך הוא בחי' התשוקה בלב ברשפי אש לעלות וליכלל בה' אחד במס\"נ בכל לב ונפש ומאד וז\"ש ואהבת בכל לבבך כו' ואחרי בחי' הרצוא צ\"ל בחי' שוב והוא לבא לבחי' ביטול ויראה היפך הרצוא כמו ששב האדם לאחורי\"ו ומזדעזע מאד בעמדו לפני מלך גדול כו' וע\"י בחי' שו\"ב זה הוא ממשיך בחי' גילוי אלקו' מלמעלה למטה ע\"י מצות קריאה והוא באמרו והיו הדברי' האלה אשר אנכ\"י מצוך היום כו' פי' הדברי\"ם האל\"ה אשר אנכ\"י הוא בחי' רצונ\"ו וחכמת\"ו ית' המלובש בתורה<sup data-n=\"730\">27</sup> שנקרא' היכלא עילאה דמלכא כי הנה התפלה נק' סולם כמ\"ש סולם<sup data-n=\"731\">28</sup> מוצב ארצה וראשו מגיע השמיימ' כו' ועד\"מ הסולם שמעמידין אותו אצל היכל עליון מאד שעל ידו יוכלו לעלות וליכנס להיכל העליון כך התורה נק' היכלא עילאה מאד וא\"א לעלות אליו בלתי סולם גדול והוא התפלה שנק' סולם שבו עולי' למעלה מעלה גם להיכלא עילא' דתורה וכמ\"ש וראש\"ו מגיע השמימה וד\"ל, והענין הוא דשרש התפלה הוא בחי' הרצוא לעלות מעלה מעלה במס\"נ ואהבת כו' וכמ\"ש<sup data-n=\"732\">29</sup> באברהם הלו\"ך ונסו\"ע בדביקותו ממדרגה למדרגה יותר גבוה כמו עד\"מ העולה בסולם גשמי עד שיגיע להיכל העליון דתורה והוא כדי להמשיך מהיכלא עילאה בחי' גילוי אור א\"ס שבחכמה שבתורה באמרו והיו הדברי' האלה כו' שהוא מצות קריאה כנ\"ל שנמשך מלמעלה למטה כנ\"ל (וז\"ש ע\"ל לבב\"ך דוקא כי הרצוא הוא בחי' נוק' וכמ\"ש ואל<sup data-n=\"733\">30</sup> אישך תשוקת\"ך כו' שהוא בחי' העלא' מ\"ן והשוב הוא בחי' דכר שהוא בחי' המשכת מ\"ד דתורה וז\"ש והיו הדברי' האל\"ה ע\"ל לבב\"ך הנ\"ל שבבחי' רצוא כי בכל ניצוץ יש בחי' דכר ונוק' רו\"ש וכמ\"ש והחיות<sup data-n=\"734\">31</sup> רו\"ש כו' ובתחלה צ\"ל בחי' נוק' שהוא הרצוא ואח\"כ השוב שהוא בחי' דכר וע\"כ אמרו עד כאן מצות כונה בהעלאת מ\"ן ואח\"כ מצות קריאה בהמשכת מ\"ד כי המ\"ד מברר למ\"ן כידוע וז\"ש והי\"ו כו' ע\"ל לבב\"ך דוקא וד\"ל). וזהו שנא' הלא<sup data-n=\"735\">32</sup> כה דברי כאש נאם ה', פי' עד\"מ האש שאינו נאחז רק בפתילה שהיא כלי שיהי' לו במה להתאחז בו וכך למעלה הנה התורה בשרשה נק' או\"ר כמ\"ש ותורה<sup data-n=\"736\">33</sup> או\"ר וכתי' עוטה<sup data-n=\"737\">34</sup> או\"ר כשלמ\"ה שאור דתורה מתעטה בלבושים כשלמ\"ה וכלי\"ם מכלי\"ם שונים שיהא לו",[["727","24","<b>עד כאן מצות כונה</b>: ברכות יג, א ואילך. וראה פירש\"י שם."],["728","25","<b>בס\"י אם רץ לבך שוב</b>: פ\"א מ\"ח. וראה ג\"כ ת\"ז בהקדמה (ז, א)."],["729","26","<b>והחיות רצוא ושוב</b>: יחזקאל א, יד."],["730","27","<b>בתורה שנקרא' היכלא עילאה דמלכא</b>: זח\"ב ר, א. וראה ג\"כ המשך מים רבים תרל\"ו פקפ\"ו."],["731","28","<b>סולם מוצב ארצה</b>: בראשית כח, יב. וראה זח\"א רסו, ב. זח\"ג רמג, א. שו, ב. ת\"ז תמ\"ה."],["732","29","<b>וכמ\"ש באברהם הלוך ונסוע</b>: בראשית יב, ט."],["733","30","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["734","31","<b>והחיות רו\"ש</b>: יחזקאל א, יד."],["735","32","<b>הלא כה דברי כאש</b>: ירמי' כג, כט."],["736","33","<b>ותורה או\"ר</b>: משלי ו, כג."],["737","34","<b>עוטה אור כשלמה</b>: תהלים קד, ב."]]],[2101000130,"במה להתאחז ולהאיר ואם אין כלי שיתאחז בו אינו נק' או\"ר המאיר כלל אלא עולה לשרשו בהעלם ומקור האור כו', ובחי' הכלים מכלים שונים הן מקרא משנה כו', וזהו ע\"י בחי' שוב בקריא\"ה כנ\"ל שהוא בחי' התלבשות האור בכלי דוקא וד\"ל, וגם לפעמי' נמשלה התורה למים כמ\"ש הוי<sup data-n=\"738\">35</sup> כל צמא לכו למים כידוע וגם בזה יש בחי' אור וכלי כמו באש כנ\"ל שהרי א\"א שיהי' מציאת המים מכונסים אלא דוקא בתוך כלים מכלים שונים כו' ואם לאו לא יוכלו להשיג את המים מן הנהר או הים כך הנה בשרש התורה למעלה כתיב ותמל\"א<sup data-n=\"739\">36</sup> כד\"ה ותעל כ\"ד ספרים דאורייתא שהן בחי' כלים שבהן מתכנס מים מימה של החכמה כמו עד\"מ השואב בכד מים הגדול וזהו אוריי'<sup data-n=\"740\">37</sup> מח\"ע נפקת כו' וד\"ל.\n<b>והנה</b> הטעם שצ\"ל תחלה אהבה ואח\"כ יראה וביטול שהוא בחי' רצוא ואח\"כ שוב כנ\"ל שזהו ואהבת תחלה ואח\"כ והיו כו' ולמה לא להיפך תחלה יראה וביטול ואח\"כ אהבה כו', הנה יובן עפ\"י מה דאיתא בר\"מ דבנוהי<sup data-n=\"741\">38</sup> דאברהם בגלותא דאדום ובנוהי דיצחק בגלותא דישמעאל כו', וזה המאמר לכאורה הוא פלאי דאיך היפך הדבר להיו' בחי' חסד דאברהם בגלותא דאדום שהוא בחי' גבורות ובנוהי דיצחק שהוא בבחי' הגבורו' בגלותא דישמעאל בבחי' חסד כידוע דשרש אברהם ויצחק המה בחי' חו\"ג דקדושה ובחי' אדום וישמעאל הן בחי' חו\"ג דקליפה כמ\"ש בעשו ועל<sup data-n=\"742\">39</sup> חרב\"ך תחיה כו' ושרש ישמעאל מבחי' חסד כמ\"ש לו<sup data-n=\"743\">40</sup> ישמעאל יחי' כו' וכמ\"ש<sup data-n=\"744\">41</sup> בזוהר במא' דרישא דעשו בעטפוהי דיצחק כו', וגם מהו שחילק בין בנוהי דאברהם לבנוהי דיצחק הלא יצחק בן אברהם הוא ואם ר\"ל בבחי' מדרגת החסד או הדין שזה נק' בנוהי דאברהם וזה נק' בנוהי דיצחק כנ\"ל א\"כ קשה למה היפך הדבר כנ\"ל. אך הענין הוא דאין התחלקות גמורה בין חסד לדין לומר שאין בחסד מבחי' הדין כלל ואין בדין מבחי' החסד כלל אלא ודאי יש בחסד גם מבחי' הדין ויש בדין גם מבחי' החסד כי כל א' כלול מזולתו ההפכי כידוע בע\"ח שהחסדי' כלולי' מהגבורות והגבורות כלולי' מהחסדי' אחר בחי' התיקו\"ן שהוא בחי' ההתכללו' ע\"י שם מ\"ה כו', אך מה שזה נק' חסד וזה נק' דין הגם שכל א' כלול מהיפכו זהו מצד בחי' ההתגלות דהנה מה שכל א' כלול מהיפכו היינו שיש בו מהיפכו בהעלם בלבד ולא בגילוי כמו בחסד כלול מבחי' הדין בבחי' ההעלם אבל ההתגלות הוא בחי' החסד דוקא וכמ\"כ בבחי' הדין כלול בו בהעלם דוקא מבחי' החסד אבל ההתגלות הוא בחי' דין דוקא ועד\"ז הוא בחי' התכללות חו\"ג דאברהם",[["738","35","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א. וראה ב\"ק יז, א."],["739","36","<b>ותמל\"א כד\"ה ותעל כ\"ד ספרים דאורייתא</b>: בראשית כד, טו. ראה ת\"ז תכ\"א (מו, ב). אוה\"ת בראשית מח, א."],["740","37","<b>אוריי' מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["741","38","<b>דבנוהי דאברהם בגלותא דאדום</b>: זח\"ג ריח, ב ואילך. ועוד."],["742","39","<b>ועל חרב\"ך תחי'</b>: בראשית כז, מ."],["743","40","<b>לו ישמעאל יחי'</b>: בראשית יז, יח."],["744","41","<b>וכמ\"ש בזוהר במאמר דרישא דעשו</b>: ראה תיב\"ע ויחי נ, יג, לקו\"ש חט\"ו ע' 193. וראה זח\"א קיח, א ואילך. ובהבא להלן ראה ג\"כ תו\"א ותו\"ח ר\"פ תולדות. סה\"מ תקס\"ח ע' תקטז ואילך. יהל אור ע' שעג ואילך."]]],[2101000131,"ויצחק שנק' בשם אוי\"ר כידוע דודאי לא חסר לאברהם מדת היראה והפחד ולא חסר ליצחק מדת האהבה אלא שבאברהם הי' ההתגלו' אהבה ובתוכה כלול בהעלם בחי' היראה והביטול כמו וגיל\"ו<sup data-n=\"745\">42</sup> ברעד\"ה במקום גיל\"ה שם תהא רעד\"ה כו' וביצחק הי' להיפך שההתגלות בו הי' היראה והפחד וכמ\"ש ופח\"ד<sup data-n=\"746\">43</sup> יצחק כו' ובהעלם כלול בפחד זה בחי' האהבה והשמחה כו' עד\"מ היושב באימה במשתה המלך ששמח בלבו ותוכו רצוף אהבה גדולה אל המלך ולא נגלה רק אימה ופחד וכן יש להיפך שנגלה אהבה ושמחה במשתה המלך ותוכו רצוף יראה גדולה כו' וד\"ל.\n<b>וזהו</b> שאמר בנוהי דאברהם שהוא בבחי' האהבה שנק' חסדי' בגלות\"א דאדו\"ם שהוא בחי' היראה ובנוהי דיצחק שהוא בחי' היראה בגלותא דישמעאל בבחי' החסד כו' והיינו מפני שבנוהי דאברהם צ\"ל בגילוי אהבה תחלה ואח\"כ יראה ובנוהי דיצחק צ\"ל יראה תחלה בגילוי ואח\"כ אהבה בהעלם וז\"ש בנוהי דיצחק בגלות\"א דישמעא\"ל וכמו בני א\"י בזמן התנאים ואמוראים שעיקרם<sup data-n=\"747\">44</sup> ביראה כדמוכח בגמ' וזוהר להיותם בגלותא דישמעאל משא\"כ עכשיו בגלותא דאדום שהעיקר הוא האהבה ובנקל היא באה לאדם יותר מן היראה כידוע וד\"ל.\n<b>וז\"ש</b> בס\"י אם ר\"ץ לבך שוב תחלה אהבה ואח\"כ יראה וכן בק\"ש הוסד לנו הסדר בק\"ש ואהבת תחלה ואח\"כ והי' כו' מפני שאצלינו צ\"ל האהבה קודם ליראה (וכמ\"ש בע\"ח דגם שלפעמי' החסדי' קודמי' לגבורו' ולפעמי' הגבורו' קודמי' לחסדי' אבל על הרוב החסדי' קודמי' לגבורות ובפרט באמרו שמע ישראל שהוא למעלה באצי' בחי'<sup data-n=\"748\">45</sup> ז\"א שנק' ישרא\"ל דלעיל\"א שעיקרו מבחי' חסדי' וכידוע<sup data-n=\"749\">46</sup> בזוהר ואתחנן בפ' זו דב\"ן מסט' דאב\"א קאתי כו' וכמ\"ש במ\"א באריכו' וד\"ל).\n<b>וזהו</b> יונתי בחגוי הסלע בסתר המדרגה, פי' יונת\"י הוא הנשמה האלקי' בפרט (ובכלל הוא כנ\"י כנ\"ל) והיא בחגו\"י הסל\"ע בחומר הגוף שנק' סלע להיותו בחי' דומם כסלע עפר מן האדמה אך נשמת חיים שבגופו שרשה מלמעלה כמ\"ש ויפ\"ח<sup data-n=\"750\">47</sup> באפיו כו' כידוע. ומ\"ש עוד בסת\"ר המדרג\"ה הכונה הוא על התלבשות הנשמה האלקי' בנפש הבהמיו' שבגוף כידוע כי הנפש הבהמיו' מסתיר על אור הניצוץ האלקי וע\"כ נק' סת\"ר המדרג\"ה (ומה שנק' מדרג\"ה כי יש בה מדרגות במדות שונות זו מזו זה טבעו כך וזה טבעו כך בחי' ענפין מתפרדי' להיות שרש מדות הנפש הזאת הבהמי' מבחי' התוהו כמשי\"ת), והנה הניצוץ האלקי הרי ירדה בבחי' ירידה גדולה כמו מאיגרא<sup data-n=\"751\">48</sup> רמא כו' שהרי היתה תחלה נהנית מזיו השכינה",[["745","42","<b>וגיל\"ו ברעד\"ה במקום גילה שם תהא רעדה</b>: תהלים ב, יא. ברכות ל, ב."],["746","43","<b>ופח\"ד יצחק</b>: בראשית לב, י."],["747","44","<b>שעיקרם ביראה כדמוכח בגמ' וזוהר</b>: ראה להלן בהביאור למאמר זה (קרוב לתחילתו)."],["748","45","<b>בחי' ז\"א שנק' ישראל דלעילא</b>: ראה ג\"כ תו\"א שמות נ, ד. ובכ\"מ."],["749","46","<b>וכידוע בזוהר ואתחנן</b>: זח\"ג רסב, א ואילך. וראה ביאוה\"ז שם."],["750","47","<b>ויפ\"ח באפיו</b>: בראשית ב, ז. וראה תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["751","48","<b>מאיגרא רמא</b>: חגיגה ה, ב."]]],[2101000132,"בג\"ע ועכשיו מתלבשת בחומר נפש הבהמי' הזאת אמנם ירידה זאת לצורך עליי' היא כמשי\"ת בעזר\"ה.\n<b>אך</b> תחלה יש להבין שרש מחצב הנפש הבהמיו' מלמעלה שהוא מבחי' המרכבה דפני אריה פני שור כו' כידוע בע\"ח דבחי' פני ארי' המקור והשרש לכל מציאות נפשות החיות למטה שנשתלשל מאתו דרך עילה ועלול כו' ובחי' פני שור הוא מקור ושרש לכל נפשות הבהמות למטה וכן פני נשר מקור הראשון להתהוו' מציאת נפש העופות כו' (ומ\"ש תוצא<sup data-n=\"752\">49</sup> הארץ נפש חיה כו' ועו\"ף יעופ\"ף<sup data-n=\"753\">50</sup> כו' ר\"ל בכללות בחי' פני ארי' ופני שור שיומשך אור השפע מעילה לעילה כו' והאר\"ץ הוא בחי' ב\"ן ושרשה בבחי' ב\"ן דתוהו כו') והנה אנו רואי' שהבהמות והחיות למטה אינם רק בבחי' המדות למטה מן הדעת כי אין במדותיהם מבחי' הדעת והשכל כלל משא\"כ האדם שמדותיו מתנהגי' עפ\"י שכל כידוע ומוכרח לומר שמדות הללו שלמטה מן הדעת שרשם הוא ג\"כ במקור חוצבם הראשון שהן בחי' המרכבה דפני ארי' פני שור כו' והיינו כידוע בפי' והחיות<sup data-n=\"754\">51</sup> נושאות את הכסא כו' ששרש המרכבה דפני ארי' כו' הוא בבחי' המדות העליונות דתוהו כמ\"ש ואלה<sup data-n=\"755\">52</sup> המלכי' אשר מלכו לפני מלך מלך לבנ\"י כו' שהן בחי' המדות שלמע' מן הדעת והשכל וז\"ש לפני מלוך מלך לבנ\"י שהוא בחי' התוהו שלמעלה מבחי' מ\"ה בחי' מ\"ה דחכמה דתיקון כו' כי גם שהמדות שבלא דעת למטה הרי הן נקראין למטה מן הדעת אבל שרשם הוא במדות שברצון החזקי' מן הדעת שנק' מדות שלמעלה מן הדעת והחכמה (ולמעלה הוא בחי' המדות שברצון הנק' כתר ובזוהר<sup data-n=\"756\">53</sup> נק' טור\"י חשוכ\"א או ימי קדם והר\"י קד\"ם כמ\"ש במ\"א) וכך בחי' המדות דחיות שבמרכבה גם שהן למטה מן הדעת שרשם הוא במדות דתוהו שלמעלה מן החכמה וע\"כ יש ביכולתם לנשאות את הכס\"א ששם<sup data-n=\"757\">54</sup> ע\"ג הכסא כמראה אד\"ם שהוא בחי' מדות דאצי' שע\"י בחי' מ\"ה דחכמ\"ה כי<sup data-n=\"758\">55</sup> אדם גי' מ\"ה והוא בחי' אד\"ם דתיקון כידוע אבל מפני ששרש החיות דמרכבה למעלה מבחי' אד\"ם דתיקון דהיינו בבחי' המדות העליונות (דכת\"ר) שבבחי' התוהו שלמעלה מן החכמה דאד\"ם שנא' שם כי<sup data-n=\"759\">56</sup> לא אד\"ם הו\"א להנחם כו' לכך המה נושאות לבחי' כס\"א דאד\"ם זה להעלותו למעלה מבחי' אד\"ם כו' וד\"ל. ובכל זה הרי יובן איך שירידת הנשמה האלקי' בנפש הבהמיו' היא לצורך עליי' דוקא כנ\"ל, אך עדיין יש להקדים שרש מחצב של הנשמה האלקי', דהנה אמר לבושין<sup data-n=\"760\">57</sup> תקינת לון דמנהון פרחין נשמתין לב\"נ כו' הרי שרש הנשמות מבחי' לבושין העליוני' בלבד.",[["752","49","<b>תוצא הארץ נפש חי'</b>: בראשית א, כד."],["753","50","<b>ועוף יעופף</b>: בראשית א, כ."],["754","51","<b>והחיות נושאות את הכסא</b>: בחיי תרומה כה, י בשם פדר\"א. וראה פדר\"א ספ\"ד. שמו\"ר ספכ\"ג."],["755","52","<b>ואלה המלכים אשר מלכו</b>: בראשית לו, לא."],["756","53","<b>ובזוהר נק' טורי חשוכא או ימי קדם והרי קדם</b>: זח\"ג רח, ב. קלד, ב. רמט, ב. וראה הנסמן לעיל ע' יז."],["757","54","<b>ששם ע\"ג הכסא כמראה אדם</b>: ראה יחזקאל א, כו."],["758","55","<b>כי אדם גי' מ\"ה</b>: ראה מאו\"א א, קסו."],["759","56","<b>כי לא אדם הוא להנחם</b>: שמואל א טו, כט."],["760","57","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101000133,"<b>וביאור</b> בחי' הלבושי' הנה ידוע דיש ג' מדרגות אורות וכלים פנימי' הנק' גופא דמלכא כמו חסד<sup data-n=\"761\">58</sup> דרועא ימינא וכה\"ג ובחי' כלים חיצוני' הנק' אותיות ובחי' הלבושי' ובל' הגמ' והמשנה נק' גם הלבושים בשם כלים כמו י\"ח<sup data-n=\"762\">59</sup> כלים שמצילין מפני הדליקה שהן י\"ח מיני לבושין וכן בכמה דוכתי משמע שהלבושי' נק' כלים והיינו בחי' כלים החיצוני' שמתאחדי' עם בחי' הלבושי'. וביאור זה הנה ידוע שעצמות המדות חסד דין ורחמים וכה\"ג נק' גופ\"א בחי' חג\"ת דז\"א כו' וכל מדה מתאחדת בכלי שלה כמו החסד שבלב ביד ימין כי א\"א להפריד היד כו' וזהו שנק' גופ\"א כמו הגוף שמתאחד עם החיות והאור אבל בחי' האותיות שהמדה מתלבש בהן הוא דבר נבדל מן הגוף כמו החסד בלב שבא לאותיות הדיבור וכיוצא וגם הרי האותיות מגבילי' לאור וחיות החסד שבלב וזהו הנק' כלים החיצוני' המגבילי' את האור שלא יתפשט ויתגלה כמו שהוא והוא מ\"ש בי'<sup data-n=\"763\">60</sup> מאמרות נברא העולם דוקא ע\"י מאמר בבחי' אותיות כמו יהי אור ע\"י מאמר יהי אור וכה\"ג כי התגלו' בחי' אור חסד עליון דאצי' הנק' גופא להיות בבחי' יש מאין למטה א\"א כ\"א ע\"י צמצום המגביל בחי' אור א\"ס שבחסד עליון הזה שלא יתגלה כמו שהוא ואחר שנתצמצם אורו ע\"י האותיות של מאמר יהי אור אזי יוכל להיו' בריאת אור חסד מאין ליש בבחי' גבול וכך הוא כל ענין המאמרות שנברא העולם על ידן דוקא מטעם זה והוא הנק' ג\"כ בחי' לבושי' (כידוע דמחשבה דלמע' נק' ג\"כ לבושין) וא\"כ גם מה שאמר נעשה<sup data-n=\"764\">61</sup> אדם בצלמינו כו' היינו ע\"י אותיות המאמר הזה דוקא שצמצם אור א\"ס שבחכמה כו' אז נמשך בחי' בריא' אדם מאין ליש והוא מה שאמר דלבושין תקינת לון דמנהון פרחין נשמתין כו' דשרש הנשמות רק מבחי' הלבושי' של המדות דז\"א כמו מאמר נעשה אדם כו' כנ\"ל וד\"ל.\n<b>וכל</b> ענין זה ההפרש בין אורות ללבושי' הוא הנק' בל' המדרש פנימי' ואחוריים כמ\"ש אחו\"ר<sup data-n=\"765\">62</sup> וקד\"ם או פנימי' וחיצוני' בל' הע\"ח כו', כי כל בריאת העולמו' הוא רק מבחי' אותיות שמ\"ו ית' שהוא רק בחי' הארה דהארה ממדותי\"ו כידוע, אבל גם על מהו' ועצמות מדותיו ית' הרי אנו או' לך<sup data-n=\"766\">63</sup> ה' הגדול\"ה והגבור\"ה כו' והמתנש\"א<sup data-n=\"767\">64</sup> מימו\"ת עול\"ם כו' לפי שבאצי' אמרו דאיהו<sup data-n=\"768\">65</sup> וחיוהי חד בבחי' א\"ס כו' וכדמסיים לאו דאית לך צדק ידיעא ולאו מכל אינון מדות כלל כו' וכמ\"ש כי<sup data-n=\"769\">66</sup> לא אדם הוא כו' (ומ\"ש נעשה אדם בצלמינ\"ו כדמותינ\"ו היינו לאחר צמצום האורות בכלים ע\"י בחי' הכלים ולבושים כנ\"ל). ומעתה יובן איך שירידת הנשמות בגוף הוא לצורך עליי' כנ\"ל, דהנה מבואר ששרש הנשמות הוא רק מבחי' הלבושי' וכלים החיצוני' הנק' אותיות המדות והן ס\"ר נשמות ישראל שנמשכי' מו\"ק כל א' כלול מז'",[["761","58","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה שם. ובכ\"מ."],["762","59","<b>י\"ח כלים שמצילין מפני הדליקה</b>: שבת קכ, א."],["763","60","<b>בי' מאמרות נברא העולם</b>: אבות פ\"ה מ\"א."],["764","61","<b>נעשה אדם בצלמנו</b>: בראשית א, כו."],["765","62","<b>אחור וקדם</b>: תהלים קלט, ה."],["766","63","<b>לך ה' הגדולה והגבורה</b>: דה\"א כט, יא."],["767","64","<b>והמתנשא מימות עולם</b>: נוסח ברכות ק\"ש."],["768","65","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["769","66","<b>כי לא אדם הוא</b>: שמואל-א טו, כט."]]],[2101000134,"אלף והן<sup data-n=\"770\">67</sup> בחי' ס\"ר אותיות שבתורה כל אות שרש נשמה א' כידוע וזהו בהיות הנשמה בשרשה למעלה אך בירידתה להתלבש בסת\"ר המדרגה בנפש הבהמי' כנ\"ל הנה עי\"ז יכולה היא לאשתאבא<sup data-n=\"771\">68</sup> בבחי' גופא דמלכא ממש שהוא בחי' עצם המדות דז\"א כנ\"ל להיות נבלע באיברי' דמלכא ממש למהוי<sup data-n=\"772\">69</sup> אח\"ד באח\"ד ממש וז\"ש ומי<sup data-n=\"773\">70</sup> כעמך גוי אח\"ד כו', והטעם הוא כנ\"ל משום דשרש נפש הבהמי' נמשכה מבחי' המרכבה פני ארי' כו' ושרש החיות שבמרכבה הוא בבחי' אורו' דתוהו דז' מלכין קדמאין שלפני התיקון דאד\"ם וע\"כ הן נושאות את הכסא למעלה מבחי' אד\"ם כנ\"ל, ולמטה הוא בחי' אהבה רבה שבאדם שלמעלה מן השכל והדעת כמו בחי' המדות דתוהו שלמעלה מן החכמה כנ\"ל וזהו ע\"י בחי' המדות דנפש הבהמיו' שהן למטה מן הדעת כו' והוא ע\"י אהבת בכל מאד\"ך בלי גבול כלל דהיינו שאין לה מונע ומסתיר כלל ומעורר למעלה בחי' מאד העליון שלמעלה מן ההסתר כו' כי במדה<sup data-n=\"774\">71</sup> שאדם מודד מודדין לו ואם מדתו בלתי מוגבלת בבחי' מאד גם מלמעלה מאיר הארה בלתי מוגבלת שלא יסתיר אורה וגם חוש\"ך לא יחשי\"ך בעדה והוא בחי' גילוי אורות דתוהו שהוא גילוי העלם החושך כמ\"ש מגלה<sup data-n=\"775\">72</sup> עמוקות מני חוש\"ך כי גם שנא' ישת<sup data-n=\"776\">73</sup> חוש\"ך סתר\"ו אבל אור זה בוקע את החושך ומאיר מתוך החושך וכמ\"ש כי<sup data-n=\"777\">74</sup> יתרון האור מן החושך וכמו בזמן מ\"ת דכתיב ויצא<sup data-n=\"778\">75</sup> כברק חצו פי' עד\"מ הברק שמבריק אור מתוך הענן והחושך כו' כך הארת האור דא\"ס בוקע כמו ברק מתוך בחי' החושך וההעלם כמ\"ש ויהי<sup data-n=\"779\">76</sup> קולות וברקים וענן כבד כו' וכך גם עכשיו ע\"י אהבת בכל מאדך למטה שבוקעת כל בחי' הסתר גשמי' מעורר למעלה בחי' בקיעת אור עליון מתוך ההעלם והסתר העליון שנק' חושך העליון כמ\"ש ישת חוש\"ך סתר\"ו ומגל\"ה עמוק\"ו' מני חוש\"ך וזהו ולא<sup data-n=\"780\">77</sup> יכנף עוד מוריך והי' עיניך רואות את מוריך עין בעין<sup data-n=\"781\">78</sup> נראה כו' וזהו בחי' עליי' שבסיבת הירידה (בב' מדריגות הא' לאשתאבא בגופא דמלכא שהוא בחי' אדם והב' למעלה גם מבחי' אדם והוא בבחי' מאד העליון כי לא אדם הוא כו' כנ\"ל וזהו שמא\"ד היפוך אתוון דאד\"ם כו' וד\"ל).\n<b>וזהו</b> הראיני את מראיך השמיעני את קולך כו', וקאי אדסמיך לי' משום דיונת\"י בחגוי הסלע בסתר המדרגה בנפש הבהמי' כנ\"ל ע\"כ הראיני את מראייך כו', והענין הוא כי פי' הראינ\"י השמיענ\"י הוא לשון מפעי\"ל שישראל ממשיכין ועושין",[["770","67","<b>והן בחי' ס\"ר אותיות שבתורה</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 241. לקו\"ת ויקרא מג, ד. הנחות הר\"פ ע' סג וע' עב. תו\"ח תולדות יא, ב. ובכ\"מ."],["771","68","<b>לאשתאבא בבחי' גופא דמלכא</b>: ראה זח\"א ריז, א."],["772","69","<b>למהוי אח\"ד באח\"ד</b>: זח\"ב קלה, א."],["773","70","<b>ומי כעמך גוי אחד</b>: ראה שמואל-ב ז, כג."],["774","71","<b>במדה שאדם מודד מודדין לו</b>: סוטה ח, ב. ובכ\"מ."],["775","72","<b>מגלה עמוקות מני חושך</b>: איוב יב, כב."],["776","73","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["777","74","<b>כי יתרון האור מן החושך</b>: ראה קהלת ב, יג."],["778","75","<b>ויצא כברק חצו</b>: זכרי' ט, יד."],["779","76","<b>ויהי קולות וברקים</b>: שמות יט, טז."],["780","77","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ. וראה זח\"ג רכב, ב."],["781","78","<b>עין בעין נראה</b>: במדבר יד, יד."]]],[2101000135,"למעלה בחי' ראיה ובחי' שמיעה כבי' וע\"ד הידוע בפי' ועשיתם<sup data-n=\"782\">79</sup> את\"ם כאילו עשאונ\"י כבי' כו'. וביאור הדברי' הנה תחלה יש להבין ההפרש<sup data-n=\"783\">80</sup> בין ראי' לשמיעה, דהנה חוש הראי' דק ורוחני בעצמה ומהותה יותר מחוש השמיעה כידוע וגם עפ\"י הסוד שרש ראיי' העין בחכמה ושרש שמיעת האזן בבינה כו' ולכאורה יש לתמוה למה מתפשט פעולת הראי' בהגשמה יותר לראות גם דבר גשמי כעץ ואבן משא\"כ השמיעה שפעולתה רוחנית יותר לשמוע קול רוחני כו'. אך הענין הוא דאדרבה דמשום דשרש הראי' גדולה במעלה משרש השמיעה ע\"כ משפלת התפשטותה למטה מטה יותר גם בהגשמת דברים אבל חוש השמיעה להיותה אינה גדולה במעלה כ\"כ ע\"כ אין ביכולתה להשתלשל ולהתפשט למטה מטה כ\"כ בענין פעולה גשמי' כראי' לראו' דבר גשמי אלא רק בדבר רוחני לשמוע קול וכה\"ג, והטעם לזה ידוע מפני שזהו הכלל בכל מקום שכל הגבוה גבוה במעלה יותר הנה יותר יוכל להשתלשל מטה מטה ביותר ועד\"מ אבן הנופל מן החומה כל שנופל מן הגובה יותר יותר יפול למטה מטה כו' וראי' לדבר זה ממה שאנו רואים שהצומח יחיה לנפש האדם בחי' מדבר הגבוה ממנו באכלו אותו לפי שגם שלמטה נשתלשל וירד הצומח להיו' למטה במדרגה פחותה מבחי' מדבר אך זהו עצמו הוראה שלמעלה בשרשו הוא יותר גבוה משרש בחי' מדבר וע\"כ ירד ונשתלשל למטה במדרגה פחותה יותר משא\"כ בחי' המדבר לפי ששרשו אינו גבוה כ\"כ לא יכול להשתלשל מטה מטה כ\"כ ולזה הטעם יש ביכולת הצומח להחיות למדבר מצד שרשו למעלה כו' (וע\"כ האריה מחיות הטמאות כמ\"ש<sup data-n=\"784\">81</sup> בס' אור החיים) וגם כאן מפני ששרש הראי' גבוה בשרשו יותר ע\"כ ירד למטה בהשתלשלו' יותר לראות גם דבר גשמי כנ\"ל משא\"כ חוש השמיעה להיותה אינה גדולה בשרשה כ\"כ ע\"כ אינה מתפשטת למטה כ\"כ כנ\"ל וד\"ל. והנמשל מזה יובן למעלה בבחי' ראיה ושמיעה העליונים במ\"ש הראינ\"י השמיענ\"י לשון מפעיל כנ\"ל דמשום ששרש בחי' הראי' גבוה במעלה יותר מבחי' השמיעה כנ\"ל במשל ראי' ושמיעה גשמיי' ע\"כ מתפשטת למטה מטה ביותר מבחי' השמיעה והיינו בחי' המצות שמתלבשי' בעניני' גשמיים מאד כמו צמר דציצית וקלף דתפילין וכה\"ג שע\"ז אמר הראינ\"י את מראייך כמשי\"ת בעז\"ה והשמיעני את קולך הוא בחי' קול דתורה ותפלה שהוא בבחי' שמיעה שלמטה במדרגה בשרשה מבחי' הראי' כנ\"ל ע\"כ אינה מתפשטת בדבר גשמי כגשמיות מעשה המצות אלא רק בבחי' קול דתורה וכה\"ג שהוא בחי' רוחניות יותר, וכל זה מטעם כלל הנ\"ל דכל הגבוה יותר יותר בא בהשתלשלות למטה בהגשמה יותר כו' וד\"ל.\n<b>אך</b> הנה מעתה יש להבין מ\"ש הראינ\"י השמיענ\"י לשון מפעיל שממשיכין ועושין למעלה בחי' ראי' כו' איך יוכל להיות זה ע\"י כנ\"י שהן נשמות בגופים גשמיי'",[["782","79","<b>ועשיתם אתם כאילו עשאוני</b>: ויק\"ר פל\"ה, ז. זח\"ג קיג, א."],["783","80","<b>ההפרש בין ראי' לשמיעה</b>: ראה ג\"כ בארוכה תו\"ח ר\"פ משפטים. סה\"מ תקס\"ד ד\"ה להבין שרש ענין ראי' ושמיעה (ע' רו). שער האמונה לאדהאמ\"צ פנ\"ט. אוה\"ת וירא קד, א. אוה\"ת ואתחנן ע' סב. ובכ\"מ."],["784","81","<b>כמ\"ש בס' אור החיים</b>: ויקרא יז, יד. וראה ג\"כ תו\"א וישלח כה, ג. אוה\"ת וארא ע' קסד. ובכ\"מ."]]],[2101000136,"כו', אמנם לזה הוא שמפרש הטעם כ\"י קול\"ך ער\"ב כו'. דהנה ידוע שהקול כלול מג' דברים אש ומים ורוח כי ב' יסודות דאש ומים שבלב מזה נעשה הבל ורוח ממוזג מבין שניהם יחד ואם יתגבר הא' על הפכו ולא יומזג כראוי לא יוכל לדבר כידוע שבהתגברות יסוד האש ניחר גרונו כו' וכך יובן בקול ער\"ב הממוזג יפה מבחי' רו\"ש חדוה ומרירו' והממוצע הוא הרחמנות עי\"ז נמשך בחי' התענוג בשמיעת הקול כו' ולמעלה ג\"כ יש בחי' רו\"ש מלמטה למעלה כמו המתנשא מימות עולם בבחי' הסתלקו' למעלה ובחי' שוב מלמעלה למטה כמו המאיר לארץ כו' והרחמי' הוא בחי' ממוצע וז\"ש אלקי עולם<sup data-n=\"785\">82</sup> ברחמי\"ך הרבים וכיוצא וד\"ל. ובדרך כלל הנה התפלה הוא קול שבבחי' רצוא מלמטה למעלה וקול דתורה הוא בחי' שוב מלמעלה למטה כידוע דהקורא בתורה הוא ממשיך גילוי אור א\"ס בחכמה מלמעלה למטה כי אוריי'<sup data-n=\"786\">83</sup> מחכ\"ע נפק' וישראל<sup data-n=\"787\">84</sup> מתקשראן באוריי' ואוריי' בקודב\"ה ונמצא הרי אוריי' עצמה ממוצע בין קול דישראל שמלמטה למעלה ובין גילוי המשכת א\"ס בתורה כו' וד\"ל.\n<b>וזהו</b> השמיעני את קולך כי קולך ערב פי' ע\"י קול דתורה ותפלה הנ\"ל להיותו בחי' ממוצע וממוזג יפה מבחי' רו\"ש הנק' קול ער\"ב הנה עי\"ז נעשה ונמשך בחי' שמיעה למעלה כמ\"ש השמיעני לשון מפעיל כנ\"ל כי נמשך בחי' עונג העליון בבינה ע\"י שמיעת קול ערב זה (דהיינו שנמשך אור עתיק בבינה) (ומזה נברא העוה\"ב כמו שאמרו ביו\"ד<sup data-n=\"788\">85</sup> נברא העוה\"ב כי העוה\"ב הוא בחי' תענוג עליון הנמשך מן החכמה בהשגה דבינה כידוע ונמשך ע\"י בחי'<sup data-n=\"789\">86</sup> יו\"ד דחכמה דוקא כמ\"ש ונהר<sup data-n=\"790\">87</sup> יוצא מעדן וכמשי\"ת) וזהו השמיענ\"י שנעשה בחי' שמיעה דבינה מהארת עונג העליון בבינה ע\"י קול\"ך ער\"ב דתור\"ה כו' וד\"ל. אך הנה בחי' עריבו' הקול שממשיך בחי' עריבות עונג העליון אינו בא רק לנשמו' בג\"ע ליהנות מזיו העונג הזה בבחי' התגלות פנימי' דהיינו רק התגלו' אור וזי\"ו פנימי, הנק' זי\"ו השכינ\"ה (והוא בחי' זיווא עילא' דע\"י שבבינה כו') ולא יוכל לבא גילוי זה למטה יותר כמו בגוף גשמי בעונג מורגש כו' רק נעשה מזה ג\"ע רוחני לנשמות שבלא גופי' בלבד והוא מטעם הנ\"ל שאין בכח השמיעה לירד למטה מטה כ\"כ אבל בחי' הראי' למעלה שהוא בחי' המצות מפני שהראי' גבוה יותר יכול להתפשט ולבא גם למטה מטה בלבוש גשמי והוא בחי' קבלת שכר בעוה\"ב מהיו\"ד שבו נברא שע\"י מעשה המצות גם לגופים גשמיים כמ\"ש כל<sup data-n=\"791\">88</sup> ישראל יש להם חלק לעוה\"ב שנא' ועמך כולם צדיקי' כי גם<sup data-n=\"792\">89</sup> פושעי ישראל",[["785","82","<b>המתנשא. . המאיר. . אלקי עולם</b>: נוסח ברכות ק\"ש."],["786","83","<b>אוריי' מחכ\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["787","84","<b>וישראל מתקשראן באורייתא</b>: ראה זח\"ג עג, א."],["788","85","<b>ביו\"ד נברא העוה\"ב</b>: מנחות כט, ב. ירושלמי חגיגה פ\"ב ה\"א. זח\"א ד, א. ובכ\"מ. וראה אגה\"ק ס\"ה ובליקוט פירושים ומ\"מ שם."],["789","86","<b>בחי' יו\"ד דחכמה</b>: ראה זח\"ג רצ, ב. ובכ\"מ."],["790","87","<b>ונהר יוצא מעדן</b>: בראשית ב, י. וראה זח\"ב קכג, ב. ובכ\"מ."],["791","88","<b>כל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין צ, א."],["792","89","<b>גם פושעי ישראל מלאי' מצות</b>: עירובין יט, א."]]],[2101000137,"מלאי' מצות מעשיו' כו' וז\"ש ביו\"ד דחכמה נברא העוה\"ב מאין ליש מצד שרש בחי' הראי' דחכמ\"ה דוקא וד\"ל.\n<b>וזהו</b> הראינ\"י בבחי' ראי\"ה את מראיי\"ך כו' ע\"י המצות כנ\"ל, דהנה שרש<sup data-n=\"793\">90</sup> המצות הוא בבחי' כת\"ר תר\"ך עמודי אור עד\"מ העמוד שמחבר הגג אל הקרקע ויש בו מעלה ומטה כך שרש המצות נעוץ ראשן למעלה מעלה בחי' כת\"ר עליון וירדו למטה ונשתלשלו בהתלבשו' בעשי' גשמית כמו מצות סוכה בסכך גשמי ומצות תפילין בקלף גשמי וכה\"ג והיא הנותנת דמשום ששרש המצות למעלה מאד ע\"כ אין התלבשותן למטה רק במעשה גשמית כי כל הגבוה יותר יותר לא יוכל להתלבש כ\"א במדרגה היותר תחתונה (וע\"ד דוגמא אנו רואי' ממה שהאריה הוא מן החיות הטמאות שלמטה מבחי' נוג\"ה שהרי טמא לגמרי ולא בבחי' נוג\"ה שמעורב טו\"ר שיש בו מבחי' הטו\"ב ג\"כ והן חיות הטהורות כי מפני שרש האריה למעלה גבוה מאד ע\"כ לא נמצא לו כלי רק למטה מטה ביותר והוא בחיות הטמאות כמ\"ש<sup data-n=\"794\">91</sup> בס' אור החיים) וביאור ענין כת\"ר עליון היינו בחי' רצון העליון שלמעלה מבחי' החכמה וע\"כ שרש המצו' למעלה משרש התורה כי אוריי' מח\"ע נפקת וכתי' והחכמ\"ה תחי' בעלי\"ה<sup data-n=\"795\">92</sup> פי' בעלי\"ה דחכמ\"ה הוא בחי' רצון העליון עד\"מ באדם הרי הרצון למעלה מן השכל והטעם כי הרצון לא יבא בבחי' גבול כלל וכמו שאמר בגמ' שתוק<sup data-n=\"796\">93</sup> כך עלה במחשבה לפני כי אע\"פ שאין השכל והטעם מורה כך מ\"מ שתוק כי זהו למעלה מן השכל והטעם רק כך ההסכם ברצון שלמעלה מן גדרי הגבלת השכל כו' וז\"ש כך עלה במחשבה שהוא הרצון שנק' כת\"ר כו' וזהו שלא נמנו<sup data-n=\"797\">94</sup> וגמרו דתלמוד גדול מן המעשה רק מפני הטעם שמפרש לפי שמביא לידי מעשה בלבד הרי המעשה עיקר להיותו גדול בשרשו מן החכמה כי תרי\"ג<sup data-n=\"798\">95</sup> מצות דאורייתא וז' דרבנן שרשם בתרי\"ג ארחי' דגלגלתא דא\"א שלמעלה גם מבחי' ח\"ס דא\"א שרש חכמה שבתורה כידוע וע\"כ ירדו המצות בהתלבשו' במעשה גשמי' והתורה לא ירדה למטה כ\"כ רק בקול כנ\"ל וד\"ל. וזהו שהמצות נק' מראיי\"ך כו' דהנה ידוע דבחכמה<sup data-n=\"799\">96</sup> אתברירו דהיינו בחי' שם מ\"ה דחכמה שמברר לבחי' ב\"ן כו' כי הנה ודאי המברר גדול מן המתברר אך לאחר שנתברר הרי המתברר עולה לשרשו קודם שנפל בשבירה הרי נעשה במדרגה גבוה מן המברר כידוע<sup data-n=\"800\">97</sup> דז' מלכין קדמאין דתוהו הן בבחי' ז\"ת דנקודי' כו' שהוא בחי' ס\"ג ונפלו בעולם הבריאה שהוא בחי' ב\"ן המתברר משם מ\"ה דתיקון כמ\"ש בחכמ\"ה אתבריר\"ו אך לאחר תשלום הבירור",[["793","90","<b>שרש המצוות הוא בבחי' כתר תר\"ך</b>: ראה פרדס ש\"ח פ\"ג. אגה\"ק סכ\"ט."],["794","91","<b>כמ\"ש בס' אור החיים</b>: ויקרא יז, יד."],["795","92","<b>והחכ' תחי' בעליה</b>: קהלת ז, יב."],["796","93","<b>שתוק כך עלה במח'</b>: מנחות כט, ב."],["797","94","<b>נמנו וגמרו דתלמוד גדול</b>: קדושין מ, ב."],["798","95","<b>תרי\"ג מצוות. . ארחין דגלגלתא</b>: ראה זח\"ג קכט, א ובביאור האריז\"ל שם. מ\"ח מס' א\"א ספ\"ד. לקו\"ת ראה כד, א."],["799","96","<b>דבחכמה אתברירו</b>: ראה זח\"ב רנד, ב. ע\"ח שי\"ח פ\"ה ועוד. מבו\"ש ש\"ה ח\"א פ\"ב. אגה\"ק סכ\"ח. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 206."],["800","97","<b>כידוע דז' מלכין קדמאין</b>: ראה ע\"ח ש\"ה פ\"א. ש\"י פ\"ג. ש\"מ פ\"ד. אוה\"ת בראשית מ, ב. ובכ\"מ."]]],[2101000138,"הרי עולה המתברר לשרשו בבחי' ס\"ג דתוהו שלמעלה מבחי' מ\"ה דתיקון וז\"ש אשת<sup data-n=\"801\">98</sup> חי\"ל שהוא בחי' ב\"ן לאחר הבירור נעשי' עטרת לבעלה בחי' מ\"ה דתיקון כו'.\n<b>וביאור</b> הדבר בפרט הנה יובן ממצות תפילין ע\"ג הקלף הרי הקלף הוא מעור בהמה טהורה ששרש מחצבה בבחי' פני שור שבמרכבה כו' כידוע דשרש פני שור מקור כל הבהמות ופני ארי' מקור כל החיות כו' והנה כאשר כותבין פ' קדש שהיא בבחי' חכ' ע\"ג הקלף הזה הרי מתברר שרש בחי' פני שור ע\"י בחי' החכמ\"ה שבפ' קדש כי האותיות דפ' זו הן מבחי' מ\"ה דחכ' דתיקון כו' אך הנה עצם מעשה המצוה כשמניח התפילין ע\"ג הראש הרי כבר נתעלה הקלף לשרשו בבחי' התוהו שלמעלה מבחי' החכמה דתיקון ונעשה למעלה במדרגה גם מאותיו' דפ' קדש המבררו וזהו ע\"י העשי' דוקא והיינו ההפרש בין בחי' חכמה שבתורה שצוה לכתוב תפילין על הקלף מעור בהמה כו' שאינו אלא בחי' חכמה המברר כו' לגוף מעשה המצוה שעולה עי\"ז למעלה מבחי' החכמה שמברר והוא שרש המעשה של המצו' למעלה בבחי' כת\"ר עליון כנ\"ל וד\"ל, וזהו שנמשלו המצות למראה עד\"מ המראה דבר מה ברמז שהוא מפני שא\"א לגלות עומק הענין כמו שהוא בדיבור כי לא יכילנו כלי השכל וכלי הדיבור ע\"כ לא יוכל לגלותו רק ברמז וכמו שאמר די<sup data-n=\"802\">99</sup> לחכימא ברמיזא כו' וזהו נק' לשון מראה כמו האדם שמראה ומרמז באצבעו כו' כך המצו' מפני שרשם למעלה מן החכמה כנ\"ל ע\"כ לא יוכלו להתגלות רק בבחי' עשי' דוקא שהוא כמו הרמז בלבד דהיינו שהן מרמזין למעלה מעלה בשרשם בבחי' אורו' דתוהו שלפני מלוך מלך לבנ\"י כו' ודוקא ע\"י עשיה גשמי' נרמז שרש המצוה כמו שהיא בבחי' הכתר כו' ולא ע\"י בחי' קול ודיבור כנ\"ל הטעם וד\"ל. וזהו שאמר הראינ\"י לשון מפעיל שמפעיל למעלה בחי' ראי\"ה דחכמה ע\"י מראיי\"ך שהוא בחי' מעשה המצו' שנק' רמז ומראה שעי\"ז נעשה למעלה בחי' הארת הכת\"ר בחכמ\"ה, וז\"ש הראינ\"י שנולד בחי' רא\"י' מאי\"ן ליש וכמ\"ש והחכמ\"ה<sup data-n=\"803\">100</sup> מאי\"ן תמצא כו' והענין הוא כי בחי' המראה שמראין ומרמזין למעלה<sup data-n=\"804\">101</sup> בבחי' הכתר ע\"י המצו' נמשך ונגלה גם בחכמ\"ה והוא הנק' גילוי אור הכתר וז\"ש הראינ\"י את מראי\"ך כו' וד\"ל ודוקא ע\"י עשי' גשמי' ולא ע\"י קול דתורה ותפלה שאינן נקראי' בחי' מראה ורמז כו' כנ\"ל ואח\"כ אמר השמיעני את קולך קול דתורה שהוא למטה מן המצו' כנ\"ל הטעם וד\"ל.\n<b>כי</b> קולך ערב ומראך נאוה, פי' נאו\"ה הוא היופי וההידור שאינו אלא דוקא מהתכללות ב' גוונין הפכיים כמו העטרה שעושין בראש המלך מאבני יקר הרי עיקר היופי וההידור אינו אלא כשהאבנים יש בהן גוונין שונים אדומי' ולבנים וירוקי' כלולי' באופן נאה שנחמד לעין כו' כך בחי' כת\"ר עליון שנעשה ממעשה",[["801","98","<b>אשת חי\"ל</b>: משלי יב, ד."],["802","99","<b>די לחכימא ברמיזא</b>: מדרש משלי כב. זח\"ג רכט, ב. רפ, ב. ת\"ז תי\"ח (לו, א). תס\"ט (קז, ב. קטז, א). ועוד."],["803","100","<b>והחכמ\"ה מאי\"ן תמצא</b>: איוב כח, יב."],["804","101","<b>למעלה</b>: כ\"ה בהכת\"י."]]],[2101000139,"המצו' למעלה הוא בבחי' היופי וההידור כמ\"ש בעטר\"ה<sup data-n=\"805\">102</sup> שעטר\"ה לו אמו ביום חתונת\"ו כו' וכן כתי' א\"ח עט\"ב כנ\"ל והעטרת היא ע\"ג הראש למעלה מבחי' החכמה שבראש שרש התורה כנ\"ל ובעטרה זאת ניכר המלוכה ונק' כת\"ר מלכו\"ת כידוע המאמר כת\"ר<sup data-n=\"806\">103</sup> עליון דאיהו כת\"ר מלכו\"ת ואין זה רק מהתכללו' העלאו' והמשכו' שהן כמו שינוי הגוונין אדום ולבן בחי' חו\"ג כו' והן המצו' שיש הרבה מהן בבחי' קו הימין חח\"נ כמו המשכו' עליונו' שבסוכה ותפילין וכה\"ג מלמעלה למטה ויש מהן בבחי' העלא' מלמטה למעלה בקרבנות ואריה<sup data-n=\"807\">104</sup> דאכיל קרבנין הוא בחי' המשכה כו' ועד\"ז כל המצות בכלל וכמ\"ש דקודב\"ה <sup data-n=\"808\">105</sup>לא שרי' רק באתר שלים התכללו' דכר ונוק' מ\"ה וב\"ן שהן חו\"ג כו' וז\"ש ומרא\"ך נאו\"ה בבחי' התכללו' חו\"ג (והתפלה<sup data-n=\"809\">106</sup> שבמקום קרבנות ג\"כ יש ארי' דאכיל כו' שהוא מלמעלה למטה כו').\n<b>והנה</b> עפ\"י כל הנ\"ל הרי לכאורה אינו מובן מה שהקדים לומר כי קולך ערב ואח\"כ מראך נאוה מאחר שהמצו' גבוהים בשרשם מן הקול דתורה כנ\"ל, אך הענין הוא דבאמת בזאת אנו רואי' מעלת המצות מאחר שעל ידם תחיי' המתים לגוף גשמי ליהנו' ולחיו' מאור א\"ס ב\"ה שא\"א כ\"א מפני ששרש המצות הוא למעלה בבחי' כת\"ר עליון ע\"כ יכולי' להאיר גם בגוף המת כו' וכנ\"ל בענין העוה\"ב דגם פושעי ישראל מלאי' מצות כו' וזהו מ\"ש טל<sup data-n=\"810\">107</sup> אורות טלך טלא<sup data-n=\"811\">108</sup> דבדולחא דנטיף מע\"י כו' שבו<sup data-n=\"812\">109</sup> עתיד להחיו' המתים ולא יהי' הגוף נהנה מאכילה ושתי' רק ליהנו' מזיו השכינה וכמ\"ש רז\"ל העוה\"ב<sup data-n=\"813\">110</sup> אין בו אכילה כו' וז\"ש ולא<sup data-n=\"814\">111</sup> יכנף עוד מוריך והיו עיניך רואות כו' כי גם גוף גשמי יוכל לראות כו' כי לא יהי' מסך מבדיל כלל מאחר שיבוער הרע מכל וכל ולא יהי' לקליפו' מציאת כלל וזהו הכל ע\"י מעשה המצות דעכשיו בעשי' גשמי' עי\"ז יהי' בחי' התגלות לחיצוניו' דהיינו שיהי' התגלו' אור א\"ס גם בגוף גשמי ע\"י טל של תחיה עד שלא יהי' נצרך לאכילה ושתי' כלל, אבל בחי' קולך ערב ע\"י קול דתורה הוא בחי' התגלות פנימי' לבחי' הפנימי' דהיינו לנשמות בג\"ע שיהיו נהנין מזיו כו' כי מפני ששרש התורה אינו גבוה כ\"כ לא יוכל לבא בהתגלו' גם בחיצוניו' כמו להתלבש בגוף גשמי רק לפנימי' כמו לנשמות וע\"כ הקדים לומר כי קול\"ך ערב לנשמו' בפנימי' ומראיך נאוה על המצות בחיצוניו' כו' ועד\"מ המראה שאינה אלא חיצוניו' והקול הוא כח פנימי יותר כו' וד\"ל. ובכל זה",[["805","102","<b>בעטרה שעטרה לו אמו ביום חתונתו</b>: שה\"ש ג, יא."],["806","103","<b>כתר עליון דאיהו כתר מלכות</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["807","104","<b>וארי' דאכיל קרבנין</b>: ראה זח\"א ו, א. זח\"ב רעח, א. זח\"ג יז, א."],["808","105","<b>דקוב\"ה לא שריא רק באתר שלים</b>: זח\"א רטז, ב."],["809","106","<b>והתפלה שבמקום קרבנות</b>: ברכות כו, ב. ובכ\"מ."],["810","107","<b>טל אורות טליך</b>: ישעי' כו, יט."],["811","108","<b>טלא דבדולחא דנטיף מע\"י</b>: ראה זח\"ג קכח, ב. קלה, ב."],["812","109","<b>שבו עתיד להחיות המתים</b>: חגיגה יב, ב. ירושלמי ברכות פ\"ה ה\"ב. וראה סנהדרין צ, ב. נצוצי זהר להקדמת ת\"ז (יב, א)."],["813","110","<b>העוה\"ב אין בו אכילה</b>: ברכות יז, א."],["814","111","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ. וראה זח\"ג רכב, ב."]]],[2101000140,"יובן ג\"כ מארז\"ל עתידי'<sup data-n=\"815\">112</sup> צדיקים שיאמרו לפניהם קדוש כי הצדיקים יתעלו אז בעילוי אחר עילוי לקבל מהארת הכת\"ר עליון ע\"כ יאמרו לפניהם קדו\"ש מובדלי' בערך כו' וד\"ל.",[["815","112","<b>עתידי' צדיקים שיאמרו לפניהם קדוש</b>: ב\"ב עה, ב."]]],[2101000141,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b> שרשי הדברי' הנ\"ל. הנה מבואר למעלה דיונתי הוא הנשמה ובחגוי הסלע הוא הגוף שקשה כסלע להיות שרשו מבחי' התוהו ששם האורות קשין וחזקין (כמ\"ש במ\"א בענין לעולם<sup data-n=\"816\">1</sup> יהא אדם רך כקנה שהוא בחי' התיקון ואל יהא קשה כארז שהוא בחי' התוהו), והנה כפל לומר ב' דברי' בחגוי סלע ובסתר המדרגה והיינו הגוף ונפשו הבהמיות ולפי ששרש נפש הבהמיו' נמשך מבחי' צמצום והסתר דנוג\"ה דעשי' ששם האור בתכלית ההסתר וההעלם כידוע ע\"כ נק' סת\"ר המדרג\"ה (ואמנם ירידה צורך עלי' היא כמשי\"ת בסמוך ע\"כ נק' סת\"ר המדרג\"ה מטעם אחר כמו המדרגה שעולין בה בהסתר ולא נגלית לעין האדם וכמשי\"ת בע\"ה), ותחלה יש להבין שרש ענין הפסוק שאח\"ז הראיני את מראיך השמיעני את קולך כי קולך ערב ומראך נאוה דהנה לכאורה יש לדקדק בסדר הדברי' מה ששינה בסדרן דמאחר שהקדים תחלה הראיני את מראיך ואח\"כ השמיעני את קולך היה לו להקדים ג\"כ בטעם הדברי' ג\"כ בענין המראה קודם לענין הקול והל\"ל כי מראך נאוה וקולך ערב ולמה שינה והקדים לומר כי קולך ערב ואח\"כ כי מראך נאוה כו', ומה גם לפי מה שמבואר למעלה בפי' הראיני את מראיך שהן המצות והשמיעני את קולך שהוא קול דתורה יותר יפלא למה שינה והקדים כי קולך ערב דתורה קודם למראך נאוה דמצות אחר שהקדים בענין המצות תחלה וגם היא גופא קשיא למה הקדים המצות לתורה ואם הקדים בתחלה למה שינה אח\"כ והקדים תורה למצות והל\"ל כי מראך נאוה כו', אך הנה פסוק זה קאי אדסמיך לי' יונתי בחגוי הסלע כו' ופי' יונת\"י הוא הנשמה כנ\"ל והטעם שנמשלה ליונה וכן כללות נש\"י נמשלה ליונה כמ\"ש אחת<sup data-n=\"817\">2</sup> היא יונתי כו' וכן כתי' עיניך<sup data-n=\"818\">3</sup> יונים והוא השבח שהקדב\"ה משבח לכנ\"י כידוע והענין ידוע שהוא עד\"מ היונים שמסתכלין זה בזה ומתענגין זה מזה בהסתכלות זאת כו' כך כנ\"י מתענגת בתענוג גדול בבחי' הסתכלות שמסתכלת בגדולת ה' כמ\"ש<sup data-n=\"819\">4</sup> בזוהר לאסתכלא ביקרא דמלכא כידוע ולמעלה היינו בחי' הסתכלות דישראל דלעילא",[["816","1","<b>לעולם יהא אדם רך כקנה</b>: תענית כ, ב. וראה ג\"כ תו\"ח בראשית יג, ב ואילך. לקו\"ת מטות פז, ב. סה\"מ תקס\"ח ע' ו. ובכ\"מ."],["817","2","<b>אחת היא יונתי</b>: שה\"ש ו, ט."],["818","3","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["819","4","<b>כמ\"ש בזהר לאסתכלא ביקרא דמלכא</b>: זח\"ב רמז, ב."]]],[2101000142,"שהוא בחי' ז\"א במצחא דא\"א כמ\"ש<sup data-n=\"820\">5</sup> בע\"ח בפי' כי יקרא קן צפור כו' דק\"נ נהורין נמשך באור אבא כו' ובאד\"ר<sup data-n=\"821\">6</sup> מבואר דבאסתכלותא דז\"א במצחא דע\"י מקבל ש\"ע נהורין כו' ולמטה בנשמות ישראל שבגופי' הנה בחי' ההסתכלות היינו בהתבוננו' בשמחה ותענוג להתענג על ה' בהסתכלות זאת ביקרא דמלכא כו' הוא הנק' יונת\"י כמ\"ש עיני\"ך יוני\"ם בכללות נש\"י וכדכתיב עיני<sup data-n=\"822\">7</sup> כל אליך כו' וכתיב הסיבי<sup data-n=\"823\">8</sup> עיני\"ך מנגדי כו' וזהו שאמר יונת\"י בחגוי הסלע פי' הנשמה מסתכלת ביקרא דמלכא ומתענגת מאד בהסתכלות זאת והיינו דוקא בהיותה מוסתרת בגוף ונפש הבהמיו' שנק' חגוי הסלע וסתר המדרגה כנ\"ל מטעם שירידה זו צורך עלי' היא כמשי\"ת בסמוך באריכות, ועל קוטב הזה הוסדה כל סדר התפלה בפסוקי דזמרה ושתים לפניה עד ק\"ש שהן רק בחי' התבוננו' והסתכלו' בגדולת ה' כמו הללו את ה' מן השמים כו' ואיך שהמלאכים אומרים קדוש וברוך וכיוצא עד שמבחי' ההסתכלות הזאת בתענוג נפלא נולד מזה בחי' המדות אוי\"ר בק\"ש באמרו ואהב\"ת כו' ואח\"כ והיו הדברים האלה כו' וד\"ל.\n<b>והנה</b> בק\"ש אמר תחלה ואהבת כו' ואח\"כ והיו הדברים האלה כו' ודברת בם כו' דהיינו אהבה ואח\"כ יראה בקיום התורה והמצות וכמ\"ש והחיות<sup data-n=\"824\">9</sup> רצוא באהבה ואח\"כ שוב ביראה כו', אך הנה לכאורה דבר זה סותר (לכאורה) למה שמצינו בגמ' ובזוהר במקומות רבים שהיראה קודמת לאהבה כמ\"ש<sup data-n=\"825\">10</sup> בזוהר ע\"פ בזאת יבא אהרן ביראה שנק' זא\"ת כו' וכן בגמ' היראה נק' מפתחות<sup data-n=\"826\">11</sup> החיצוניו' כידוע. אך הנה הענין יובן עפ\"י המבואר למעלה בענין המאמר דבנוהי<sup data-n=\"827\">12</sup> דאברהם בגלותא דאדום ובנוהי דיצחק בגלותא דישמעאל כו' דלכאורה אין הבנה למאמר זה דהלא יצחק בנו של אברהם היה ולמה יחלק בבניהם להיו' זה נק' בנוהי דאברהם וזה בנוהי דיצחק וגם למה יתהפך הדבר להיות מדרגת האהבה דחסד דאברהם בגלותא דאדום שהוא בחי' גבורות ובנוהי דיצחק שהוא בחי' היראה בגלותא דישמעאל ששרשו מבחי' החסד דאברהם כידוע במ\"ש לו<sup data-n=\"828\">13</sup> ישמעאל יחי' לפניך ובמקום אחר אמר בזוהר בהיפוך דרישא<sup data-n=\"829\">14</sup> דעשו בעטפוהי דיצחק כו' וכמ\"ש ויאהב<sup data-n=\"830\">15</sup> יצחק את עשו כי ציד בפיו והיינו מפני שהוא נמשך מבחי' פסולת הגבורות דיצחק כידוע.",[["820","5","<b>כמ\"ש בע\"ח בפי' כי יקרא קן צפור</b>: ע\"ח ש' הזווגים פ\"ז ואילך."],["821","6","<b>ובאד\"ר מבואר</b>: ראה תו\"א ויחי מח, ב. פלח הרמון שמות שסב, א. ובהנסמן שם."],["822","7","<b>עיני כל אליך</b>: תהלים קמה, טו."],["823","8","<b>הסבי עיניך מנגדי</b>: שה\"ש ו, ה."],["824","9","<b>והחיות רצוא</b>: יחזקאל א, יד."],["825","10","<b>כמ\"ש בזוהר ע\"פ בזאת יבא אהרן</b>: זח\"ג נו, ב. וראה זח\"א יא, ב, ובכ\"מ."],["826","11","<b>וכן בגמ'. . מפתחות החיצוניות</b>: שבת לא, ב."],["827","12","<b>דבנוהי דאברהם בגלותא דאדום</b>: ראה ת\"ז תט\"ו (ל, ב)."],["828","13","<b>לו ישמעאל יחי' לפניך</b>: בראשית יז, יח."],["829","14","<b>דרישא דעשיו בעטפוהי דיצחק</b>: ראה תיב\"ע ויחי נ, יג. לקו\"ש חט\"ו ע' 193. וראה בהנסמן לעיל ע' צט."],["830","15","<b>ויאהב יצחק את עשו</b>: בראשית כה, כח."]]],[2101000143,"<b>אך</b> כ\"ז יובן בהקדים ענין א' הידוע שיש ב' מיני אהבות הא' הנק' אהבה זוטא והב' הנק' אהבה רבה כמ\"ש בזהר, והנה בחי' אהבה זוטא היא שנמשכה מן השכל וההתבוננו' כידוע מלמטה למעלה ועלי' נאמר והחיות רצוא כו' וכמ\"ש<sup data-n=\"831\">16</sup> בס\"י אם ר\"ץ לב\"ך כו' והיא הקודמת לבא באדם לפני היראה וכמ\"ש רצוא בתחלה ואח\"כ שוב שהוא בחי' הפחד והביטול דיראה דהיינו בחי' הריחוק שמתרחק אחר הקירוב דאהבה וכמו וינועו<sup data-n=\"832\">17</sup> ויעמדו מרחוק כו' אבל בחי' אהבה רבה שלמעלה מן השכל וההתבוננות כידוע שהיא באה מלמעלה למטה היא המתאחרת לבא אחר היראה דוקא וע\"ז אמרו בזוהר ובגמ' דהיראה קודמת לאהבה כמ\"ש בזא\"ת יבא אהרן כו' כנ\"ל והטעם הוא לפי שהכלל הוא שדרכו<sup data-n=\"833\">18</sup> של איש לחזור אחר אשה פי' אשה היא בחי' נוקבא דהיינו בחי' היראה שנק' אשה יראת ה' כידוע וכאשר יש באדם בחי' יראה שנק' אשה אזי דוקא יחזור אחריה האי\"ש שהוא בחי' אהבה רבה שנשפעת מלמעלה למטה בבחי' דכ\"ר לפי שדרכו של אי\"ש לחזור אחר אש\"ה אבל כאשר אין בו יראה אינו נשפע לו בחי' אהבה רבה זו שלא נשפעת אלא מלמעלה דהיינו מבחי' ז\"א לנוק' כמ\"ש אהבת\"י<sup data-n=\"834\">19</sup> אתכם כו' ומזה נולד אהבה ברצון האדם שהוא למעלה מן השכל וזהו שאמרו בזוהר ובגמ' בכמה דוכתי דהיראה קודמת לאהבה כמ\"ש בזא\"ת כו' שהיא בחי' נוק' שקודמת לדכ\"ר כי דרכ\"ו של אי\"ש לחזור אשה ואין דרכה של אשה לחזור<sup data-n=\"835\">20</sup> איש כו' וכל זה באהבה רבה שבאה ונמשכה מלמעלה למטה בבחי' דכ\"ר אז צריך להיו' בחי' היראה מקודם כנ\"ל אבל מלמטה למעלה מכנ\"י להקדב\"ה אדרבה האהבה קודמת ליראה דהיינו האהבה שנולד מן השכל שנק' אהבה זוטא וז\"ש והחיות רצוא ואח\"כ שוב וז\"ש בק\"ש ואהב\"ת תחלה ואח\"כ ודבר\"ת ב\"ם שהוא בחי' שו\"ב כנ\"ל וד\"ל.\n<b>ובכל</b> זה יובן ענין המאמר הנ\"ל דבנוהי דאברהם הוא בגלותא דאדום כו', דהנה לכאורה יפלא מה שאנו רואין בגלותינו זה שבנקל יותר לכאו\"א מישראל להתפעל באהבה מלהתפעל ביראה ועפ\"י הרוב האהבה תקדם ליראה בכאו\"א לפי מדרגתו ולכאורה אנו מוצאי' בזוהר ובגמ' היפך זה שבכמה מקומו' אמרו דהיראה צ\"ל קודם כנ\"ל אך הענין הוא דהזוהר והגמ' מדברי' בהיותם בא\"י שהוא בחי' גלות ישמעאל ע\"כ היראה קודמת לאהבה ואנחנו בגלותא דאדום צ\"ל האהבה קודמת ליראה כו' והענין הוא כנ\"ל דלגבי בחי' אהבה רבה צ\"ל היראה קודמת מטעם שדרכו של איש לחזור אחר אשה כנ\"ל ע\"כ הזהירו בזוהר ובגמ' על היראה בתחלה אבל אנחנו בנוהי דאברהם בגלותא דאדום צ\"ל האהבה קודם כי הנה שרש אברהם ויצחק ידוע שבחי' אהבה דאברהם כלולה ג\"כ מיראה ופחד דיצחק וכן יראה דיצחק כלולה מאהבה דאברהם רק שבאברהם האהבה בגילוי והיראה בהעלם וביצחק הוא להיפך דהיראה בגילוי והאהבה בהעלם וזהו ענין עקידת יצחק שנכלל בחסד",[["831","16","<b>וכמ\"ש בס\"י אם רץ לבך</b>: פ\"א מ\"ח. וראה ג\"כ ת\"ז בהקדמה (ז, א)."],["832","17","<b>וינועו ויעמדו מרחוק</b>: שמות כ, יח."],["833","18","<b>שדרכו של איש לחזור אחר אשה</b>: קדושין ב, ב. וראה תניא פמ\"ג. ובכ\"מ."],["834","19","<b>אהבת\"י אתכם</b>: מלאכי א, ב."],["835","20","<b>לחזור אשה. . לחזור איש</b>: כ\"ה בגוכי\"ק."]]],[2101000144,"דאברהם בחי' גבורו' דיצחק וכן כתיב אברהם<sup data-n=\"836\">21</sup> הוליד את יצחק והוא בחי' השוב שאחר הרצוא מלמטה למעלה כנ\"ל וזהו פי' בנוה\"י דאברה\"ם שהוא בחי' אהבה זוטא הנק' רצוא מלמטה למעלה שזהו שרש בחי' חסד דאברהם הוא בגלותא דאדום דוקא דהיינו להיות מתלבשת בבחי' היראה שהוא בחי' השוב שאחר הרצוא אבל בנוהי דיצחק שהוא בחי' היראה והפחד בגלותא דישמעאל דוקא להיות מסתעף ממנה לבחי' אהבה רבה שלמעלה מן השכל מטעם שדרכו של איש לחזור אחר אשה כנ\"ל. ובזה מתורץ מה שחילק בין בנוהי דאברהם לבנוהי דיצחק אע\"פ שכלולי' זה מזה כי אדרבה לפי שכלולי' זה בזה ע\"כ מתהפך להיות כאו\"א מתלבש בהיפכו דוקא אבל לא יתכן להיו' בנוהי דאברהם בגלותא דישמעאל ובנוהי דיצחק בגלותא דאדום מאחר שישמעאל נמשך ממותרי החסדי' דאברהם ועשו נמשך ממותרי הגבורו' וכמו שאמר רישא דעשו כו' אין זה בחי' התכללו' מהיפכו ואדרבה יוכל להיו' מזה תוס' יניקה לעשו וישמעאל, ובכל זה מובן ג\"כ מה שבגלותינו בנקל יותר להתפעל באהבה מביראה דהיינו בחי' אהבה זוטא כי אנחנו בנוהי דאברהם בגלותא דאדום דהיינו בבחי' רצוא ואח\"כ שוב אבל בני א\"י מפני שהן בנוהי דיצחק בגלותא דישמעאל ע\"כ היראה קודמת לבחי' אהבה רבה מטעם הנ\"ל שדרכו של איש כו' וע\"כ הזהירו בזוהר על היראה בתחלה דוקא כנ\"ל (ומ\"ש בק\"ש ואהבת ואח\"כ ודברת בם כו' אע\"פ שפ' ק\"ש שוה לכל הענין הוא כי ואהב\"ת<sup data-n=\"837\">22</sup> גי' ב\"פ אור דהיינו בחי' א\"י דהיינו אהבה רבה הנ\"ל ובאמרו בשכמל\"ו הוא בחי' היראה שקדמה לא\"ר והב' בחי' א\"ח שהוא בחי' הרצוא שלפני השוב וד\"ל).\n<b>והנה</b> הנשמה שמתלבשת בגוף נק' חגוי הסלע מטעם שקשה כסלע להיות שרש מחצב הגוף מבחי' אורות התוהו שנפלו בשבירה כנ\"ל וזהו פי' יונת\"י בחגוי הסלע בסתר המדרגה פי' בסתר המדרגה עד\"מ המדרגה הגשמית שיש ב' מיני מדרגות הא' המדרגה העשוי' בגילוי שנגלה לעין כל כשעולין בה כמו הסולם שעומד מבחוץ וכיוצא והב' המדרגה העשוי' בהעלם ובסתר גדול שלא נגלה לשום אדם רק ליחידי סגולה שיודעין בהליכתה (כמו המדרגה שעשוי' בהיקף סביב לעץ ועמוד שפתאום יעלה העולה בה מעט מעט מבלי ירגיש שעלה כו' והוא הנק' בל\"א שווינד\"ל טרע\"פ<sup data-n=\"838\">23</sup> כו' וכמ\"ש במ\"א) והנמשל למעלה יובן בעבודה שבלב זו תפלה שיש ב' מיני עליות הנק' מדרגה הא' עליית הנשמה האלקי' ממדרגה למדרגה ומהשגה להשגה כו' כמ\"ש ילכו<sup data-n=\"839\">24</sup> מחיל אל חיל כו' כמו בעמוד שעולין בג\"ע העליון וכן התפלה נק' סולם כמ\"ש<sup data-n=\"840\">25</sup> בזוהר ע\"פ סולם מוצב ארצה וראשו מגיע השמימה ומלאכי אלקי' עולין ויורדין בו כו' והיא בחי' מדרגה נגלית כשעולין בה דהיינו שיש עליי' לכולם בה כמו מלאכי אלקי' שעולין בה כו' וכך ע\"י התפלה שנק' סולם עולין",[["836","21","<b>אברהם הוליד את יצחק</b>: בראשית כה, יט."],["837","22","<b>ואהב\"ת גי' ב\"פ אור</b>: שער הכוונות כוונת ק\"ש. פע\"ח שער הק\"ש פכ\"ג וכ\"ה. ועוד."],["838","23","<b>כמו המדרגה. . שווינד\"ל טרע\"פ</b>: ראה סה\"מ תקס\"ה ע' ריד ואילך."],["839","24","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח. וראה ברכות סד א."],["840","25","<b>כמ\"ש בזוהר ע\"פ סולם מוצב ארצה</b>: בראשית כח, יב, וראה זח\"א רסו, ב. זח\"ג רמג, א. שו, ב. ת\"ז תמ\"ה."]]],[2101000145,"כל העולמו' ונשמות והמלאכי' כו' ובחי' מדרגה הב' היא הנק' סת\"ר המדרג\"ה שלא נגלית לכל כי היא עשוי' בבחי' ההעלם וההסתר כו' והוא בחי' עליית הנפש הבהמיו' ע\"י אוי\"ר טבעיי' כו' שעליי' זאת בבחי' ההעלם וההסתר עמוק עמוק מאד לפי ששרש הנפש הבהמיו' שבגוף נפל מבחי' אורו' דתוהו שהן למעלה מעלה מאד ופתאום תעלה הנפש הבהמיו' לבחי' התוהו ותצא מבחי' הצמצום דנוג\"ה בלתי נראה ונגלה איזה ענין העלאה ממדרגה למדרגה (ועד\"מ<sup data-n=\"841\">26</sup> המרכבה שנושא את הרוכב פתאום מבלי ירגיש הרוכב כלל כך הנפש הבהמי' כשתתעלה לשרשה בתוהו הרי היא בחי' לבוש ומרכבה לנפש האלקי' להעלותה פתאום מה שלא הי' כלל ביכולת הנפש האלקי' לילך מעצמה במדרגה שנק' סול\"ם הנ\"ל וזהו ענין ירידה צורך עליי' הנ\"ל בנפש האלקי' שלזאת ירדה ונתלבשה בגוף בעוה\"ז לצורך עליי' גדולה יותר מכמו שהיתה תחלה נהנית מזיו השכינה בג\"ע העליון כו', דהנה בחי' זיו השכינה בג\"ע הוא נמשך מבחי' כ\"ב אתוון דאוריי' כידוע וכל נשמה יש לה מדרגה מיוחדת כפי שרשה בס\"ר אותיות שבתורה<sup data-n=\"842\">27</sup> כי ידוע דס\"ר נשמות ישראל נאחזי' ומושרשי' בס\"ר אותיות שבתורה משום דתלת<sup data-n=\"843\">28</sup> קשרין הן ישראל מתקשראן באוריי' ואוריי' בקודב\"ה כו' והנה ידוע דבחי' האותיות נקראי' בחי' כלים לאורות עליוני' כמו עד\"מ אותיות השכל שהשכל נק' אור והאותיות הן בחי' כלים מגבילי' את אור השכל שהרי אור המושכל יכול להתמשך בכמה אופנים שונים וע\"י האותיות מוגבל הוא באופן פרטי וגם במהות אור השכל שלמעלה מן אותיות המחשבה הרי אין בו בחי' הגשמה והתחלקות עדיין משא\"כ בבוא השכל באותיות המחשבה וכן המדות שבלב הרי כחות פשוטים המה עדיין מבלי נרגשין ליש כלל ומבלי התחלקות והגבלה עדיין אך בבואם לבחי' הכלי כמו אותיות המחשבה כשמהרהר מה שלבו חפץ שמשתנה מהות אור המדה שבלב מכמו שהיא ונעשית באופן פרטי כפי אופן המחשבה ונעשית מוגבלת ומתחלקת כו' וכמו שנראה בחוש שאהבה אשר בלב האדם לאיזה דבר מה בחי' כח היולי הוא עדיין רק בהרהור שבלבו ומוחו נעשה לה בחי' כלי\"ם מכלי\"ם שוני\"ם להתלבש באופני' פרטים לפעמים כך ולפעמים כך כו' וכך יובן בדרך כללות בבחי' האותיות העליוני' שהן בחי' כלים מגבילי' לבחי' אורות עליוני' שהן בחי' המדות והשכל כו' והיינו בחי' ס\"ר אותיות שבתורה שמשם מקבלי' ס\"ר הנשמות כנ\"ל ומהם נעשה בחי' הרקי\"ע דג\"ע וכמ\"ש ועל<sup data-n=\"844\">29</sup> ראשי החיות רקיע<sup data-n=\"845\">30</sup> כו' וכמ\"ש במ\"א בפי' או\"ר מי\"ם רקי\"ע וד\"ל.\n<b>אך</b> הנה ע\"י ירידת הנשמה בגוף תתעלה בעילוי יותר גבוה והוא מה שתתעלה ע\"י אמצעות נפש הבהמיו' דנוג\"ה שנק' סת\"ר המדרג\"ה כנ\"ל מטעם ששרשה בבחי' פנימי' אורו' דתוהו שלמעלה מבחי' ההגבלה וההתחלקות בריבוי כלי\"ם כידוע",[["841","26","<b>ועד\"מ</b>: בגוכי\"ק חסר סיום המוסגר."],["842","27","<b>דס\"ר נשמות ישראל. . בס\"ר אותיות שבתורה</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 241. וראה בהנסמן לעיל ע' קג."],["843","28","<b>דתלת קשרין הן</b>: ראה זח\"ג עג, א."],["844","29","<b>ועל ראשי החיות רקיע</b>: ראה יחזקאל א, כב."],["845","30","<b>בפי' אור מים רקיע</b>: ראה זח\"ב קסז, א ואילך. וראה ס' הערכים חב\"ד כרך ג' ע' תא ואילך."]]],[2101000146,"וזהו ענין סמיכות הדברים בפסוקים האלה דיונתי בחגוי הסלע כו' הראיני את מראיך כו' דקאי אדסמיך לי' יונתי בחגוי הסלע שהוא הגוף שקשה כסלע להיות שרשו מבחי' התוהו וע\"כ תעלה בסת\"ר המדרג\"ה למעלה מכמו שהיתה בג\"ע כנ\"ל ע\"כ אמר הראיני את מראייך כו' וד\"ל. וכמו\"כ יובן כ\"ז ג\"כ בשרש כללות נש\"י למע' שהוא בחי' מל' דאצי' שנקראת יונתי כמ\"ש אחת<sup data-n=\"846\">31</sup> היא יונת\"י כו' וששים<sup data-n=\"847\">32</sup> מלכו\"ת הן ס' מסכתות וכו' אך אחת היא בחי' מל' דאצי' דוקא בהיותה מתלבשת למטה בירידת המדרגה שנק' חגוי הסלע והוא בבחי' צמצומי' דשם אלקי' היותר אחרוני' שהן צמצומים קשין כסל\"ע ששם נא' אתה<sup data-n=\"848\">33</sup> א\"ל מסתת\"ר כו' וירידה זו צורך עלי' הוא כדמיון נשמה הפרטי' שמסתתרת בחומר הגופני שקשה כסלע כנ\"ל (כמ\"ש במ\"א בפי' הפסוק מושיבי<sup data-n=\"849\">34</sup> עקרת הבית ואמרו ז\"ל כחולדה<sup data-n=\"850\">35</sup> זו הדרה בעיקרי בתים כו') ושם היא עולה בסת\"ר המדרג\"ה דהיינו ע\"ד הנ\"ל בנשמה שבגוף שתתעלה עי\"ז בעילוי יותר גבוה מכמו שהיתה בתחלה והוא מטעם המבואר במ\"א בענין והחיות<sup data-n=\"851\">36</sup> נושאו\"ת הכסא כו' כמשל המרכבה שנושא את הרוכב למעלה מיכולתו בעצמו לעלות כו' כך בחי' החיו' שבמרכבה שבחי' המל' מתלבשת בהן כמו הנשמה שמתלבשת בגוף נושאו' ומעלות לבחי' המל' עד רום המעלות מצד שרשן בבחי' החיו' והבהמו' שבבחי' התוהו כידוע וזהו פי' בסת\"ר המדרג\"ה שהיא בחי' עליי' נעלמת מאד ולא כמו עליי' המל' ע\"י התפלה שנק' סול\"ם כנ\"ל בנשמה פרטי' שבגוף כו' וד\"ל וע\"כ אמר הראיני את מראיך כו' וקאי אדסמיך לי' יונתי בחגוי הסלע משום דהא בהא תליא כנ\"ל וד\"ל.\n<b>ומעתה</b><sup data-n=\"852\">37</sup> יש לבאר שרש ענין הראיני את מראיך והשמיעני את קולך וכו', דהנה לכאורה הטעם פשוט בשרש ענין מראה וקול דתורה ומצות לפי שהמצות נתלבשו בענינים גשמיים כמו צמר דציצית וקלף דתפילין וכה\"ג אבל התורה היא בחי' חכמה ושכל רוחני גם שמלובשת באותיות מ\"מ יותר רוחני הוא ממעשה המצות כו' ע\"כ נמשלה התורה לבחי' קול שהוא רוחני כי חוש השמיעה הוא רוחני יותר מחוש הראיה שהרי חוש השמיעה אשר מאזין ומקשיב לקולות הרי הקול רוחני הוא וקליטת הקול בתוך חללי ניקבי האזן הוא בחי' כח רוחני המבחין בין קול לקול משא\"כ חוש הראיה הנה מתפשטת על דבר גשמי כמו לראות על אבן ועץ וכה\"ג כי הראיה הוא כח התופס לדברים גשמיים וכח תפיסת הגשם הוא כח גשמי בהכרח ולהיות כי המצות נעשי' בעשי' גשמי' כנ\"ל ע\"כ אמר הראיני את מראיך בבחי' ראי' שהוא כח גשמי אבל על התורה שהיא בחי' חכמה רוחנית אמר",[["846","31","<b>אחת היא יונתי</b>: שה\"ש ו, ט."],["847","32","<b>וששים מלכות הן ס' מסכתות</b>: שה\"ש ו, ח. שהש\"ר שם."],["848","33","<b>אתה א-ל מסתתר</b>: ישעי' מה, טו."],["849","34","<b>מושיבי עקרת הבית</b>: תהלים קיג, ט."],["850","35","<b>כחולדה זו הדרה בעיקרי בתים</b>: פסחים קיח, ב. וראה לקו\"ת צו יא, ג. סה\"מ תקס\"ה ע' תלה. ובכ\"מ."],["851","36","<b>והחיות נושאות הכסא</b>: ראה בחיי תרומה כה, יו\"ד בשם פדר\"א. וראה פדר\"א ספ\"ד. שמו\"ר ספכ\"ג."],["852","37","<b>ומעתה יש לבאר שרש ענין הראיני</b>: להבא להלן ראה גם ד\"ה הראיני בסה\"מ תרס\"ב ע' רנא ואילך."]]],[2101000147,"השמיענ\"י את קול\"ך כו' שהוא בחי' כח רוחני יותר כנ\"ל וד\"ל. אך הנה יש להבין עדיין בשרש ענין הראיה והשמיעה דלכאורה יפלא מאד למה כח הראי' תופסת הגשם כנ\"ל הלא שרש כח הראיה גבוה במדרגה מכח השמיעה כידוע ששרש הראיה בבחי' חכמה וכמ\"ש במשה ויר\"א <sup data-n=\"853\">38</sup> ראשית לו כו' וכל הסתכלות היא בחכמה דוקא כמו לאסתכלא<sup data-n=\"854\">39</sup> ביקרא דמלכא וכיוצא והחכמים<sup data-n=\"855\">40</sup> נק' עינ\"י העדה כידוע ושרש השמיעה הוא רק בבחי' בינה כידוע דאז\"ן בגי' ס\"ג עם ה\"ג דבינה כמ\"ש בע\"ח וא\"כ למה הראיה תופסת הגשם והשמיעה קולטת דבר הרוחני דקול כנ\"ל, אך הענין יובן בהקדים תחלה לבאר שרש ענין כח הראיה וכח השמיעה מה הן דהנה אנו רואי' בפעולת כח הראיה ופעולת כח השמיעה שפעולת שניהם הוא לחבר הדבר הנבדל מן האדם שיתקרב ויהי' לו חיבור וקירוב אל האדם כו' כמו כח הראיה שמתפשטת להביט ולעיין בצורת דבר גשמי כמו צורת הבנין או על איזה שטח מקום בארץ הרחוק מן האדם הרי אותו הדבר הגשמי שרחוק מן האדם נתקרב יותר אל האדם ע\"י הראיה וההבטה עליו כי זה הבנין או שטח ארץ או איזה איש שעומדי' מרחוק ע\"י ההבטה עליהם יש להם חיבור וקירוב יותר מבתחלה עד שמצייר במוחו לאותן הדברי' המופרדי' ומרוחקים ממנו ואע\"פ שאין זה חיבור אמיתי כי אותן הדברי' גם לאחר הראיה עליהם עומדי' מרחוק אך לגבי האדם יש דמיון קירוב וחיבור לאותן הדברי' כשתופסם בראיה כידוע וכמ\"כ בחוש השמיעה שקולטת הקול שפעולתו לקרב ולקלוט קול הנשמע מרחוק הרבה וגם הרי ישמע לקול ודיבור של זולתו עד שמצטיירי' האותיות והצרופי' במחשבתו ומשיג אותם בהשגה במוחו ונמצא אותן הקולות והדיבורי' של זולתו שהיו מופרדי' ממנו נתקרבו ונתחברו בכלי השגתו וכן קליטת קול מרחוק הרי מתקרב נקלט בניקבי אזנו כו' וא\"כ הרי מובן עכ\"פ שפעולות ב' הכוחות הללו דראי' ושמיעה הוא לקרב ולחבר את הנפרד והמרוחק, אך כח<sup data-n=\"856\">41</sup> הראיה מתפשטת יותר למרחוק לקרב ולחבר גם דבר העומד רחוק בערך ס' מילין כידוע והשמיעה אינה מגעת למרחוק כ\"כ כידוע וד\"ל.\n<b>והנה</b> לכאורה יש להבין למה בחי' כח המחבר שבעין הרואה מתפשט יותר למרחוק וגם יורד ונשפל למטה בדברים גשמיים כמו שמבואר למעלה בטבע כח הראיה שתופס הגשמת דבר מה כו'. אך הענין הוא דאדרבה היא הנותנת דמשום ששרש כח הראי' גבוה מכח השמיעה דהיינו ששרשה נמשך מבחי' החכמה שבנפש שהיא כח פנימי מפנימי' הנפש יותר כידוע ע\"כ יש בכח הראי' לירד ולהתפשט למטה מטה ביותר כמו לתפוס את הגשם ולהתפשט יותר למרחוק כנ\"ל משא\"כ בחי' כח המחבר שבאזן שאינה נמשכת מפנימי' הנפש כ\"כ כי שרשה בנפש אינו אלא מבחי' בינה שבנפש כנ\"ל (וכידוע בפי' דבר<sup data-n=\"857\">42</sup> כי שומ\"ע עבדך כלומר מבי\"ן וכן פי' שמ\"ע ישראל היינו הבן ושמע שהוא ענין האזנת דברים להבינם ולהשיגם היטב כמו",[["853","38","<b>וירא ראשית לו</b>: דברים לג, כא."],["854","39","<b>לאסתכלא ביקרא דמלכא</b>: זח\"ב רמז, ב."],["855","40","<b>והחכמים נק' עיני העדה</b>: ראה במדבר טו, כד. וראה ג\"כ אגה\"ק סי\"ד."],["856","41","<b>כח הראי' מתפשטת. . בערך ס' מילין</b>: ראה ג\"כ אוה\"ת בראשית כרך ו' תתרלט, א. סה\"מ תרל\"ב ע' קסג ובמילואים להמ\"מ שם ע' שלב."],["857","42","<b>דבר כי שומע עבדך</b>: שמואל-א ג, ט ואילך."]]],[2101000148,"האזינו<sup data-n=\"858\">43</sup> השמים כו' וא\"כ הרי שרש השמיעה באזן הוא בבחי' בינה דהיינו להבין ולהשיג במוחו ההשכלה ששומע באזנו כו') וידוע שבחי' החכמה גבוה מבחי' בינה כי החכמ\"ה נק' אי\"ן והבינה נק' י\"ש וזהו<sup data-n=\"859\">44</sup> הכלל גדול בכל מקום שכל הגבוה גבוה יותר יותר יש בכחו לירד ולהשפיל א\"ע למטה מטה יותר והמופתים לכלל זה רבים המה הא' ממשל נפילת האבן מראש גובה החומה למרחק שכל שהאבן נופל ממקום הגבוה ביותר יותר יהי' נפילתו למטה למרחק יותר כי אם יפול מן האמצע לא יפול למרחוק כ\"כ ולא בנמוך כ\"כ כמו אם יפול מראש החומה כידוע, והב' ממשל רוחני יותר והוא ג\"כ עולה בסגנון א' עם ענין נפילת אבן הנ\"ל והוא מאשר אנו רואים שכל מי שדעתו וכח שכלו עמוק עמוק במעלה ומדרגה מופלגת ביותר יותר יש בכחו להוריד ולהשפיל כל שכל וסברא עמוקה להלבישה בכמה לבושים נמוכים עד שיוכל גם קצר הדעת כמו התינוק להשיגה והוא כמו ענין ריבוי המשלים למצוא משל למשל כמ\"ש בשלמה וידבר<sup data-n=\"860\">45</sup> ג' אלפים משל כו' וכמ\"כ שבחוהו חכמים לרבי<sup data-n=\"861\">46</sup> מאיר שהי' אומר ג' מאות משלי שועלי' כו' לפי שזהו הוראה על עוצם מעלת עומק החכמה לפי שכל מי שמשכיל פנימי' המושכל ביותר יותר יוכל להמציא לבושי' ומשלים רבים וה\"ז ממש כמו משל ירידת ונפילת האבן הנ\"ל מפני שכל הגבוה גבוה יותר יותר יוכל להשפיל א\"ע וע\"כ אנו רואי' בחוש שכל מי שמבין פנימי' ועומק השכל יותר הוא יכול ללמדו ולהסבירו גם לזולתו אבל מי שאינו משיג לעומקו אע\"פ שמבין ומשיגו כשלומד לעצמו אך לא יוכל לפרש הדבר וללמדו לזולתו הקטן ממנו ונמצא כל הגדול בחכמה יותר יותר יוכל להשפיע שפע שכל למטה מטה דהיינו גם לתלמיד קטן השכל מאד, והג' והוא אמיתית יותר לענין דכאן בטעם ירידת כח הראיה למטה יותר מכח השמיעה כנ\"ל והוא כמו משל מי שעומד במקום הגבוה ביותר כמו על הר או גג גבוה ביותר יותר יוכל לראות במקום המרוחק ומקום השפל כמו בבקעה ונחל ואם אינו עומד במקום גבוה כ\"כ לא יוכל להביט במקום השפל או למרחוק כ\"כ כו' והדוגמא מזה ג\"כ ברוחניו' שכל שמעלתו ברוחניות גבוה יותר יותר יתפשט למטה גם במדרגה היותר נמוך כנ\"ל.\n<b>(ושרש</b> הדברי' יובן ממה שמצינו במוח שבראש שהוא המתפשט גם בעקבי הרגלים כמו להרגיש גם הכאב דצפרן הרגל ג\"כ לפי שהוא בחי' כח כללי שכולל כל הפרטי' של האיברי' כו' וע\"כ אמר משה רבינו ע\"ע ת\"ר<sup data-n=\"862\">47</sup> אלף רגל\"י העם אשר אנכ\"י בקרב\"ו כי הי' בחי' המוחין שכולל לס\"ר נשמות ישראל כו' וכמ\"ש במ\"א שכל שהוא כללי יותר יותר ירגיש גם את הנמוך במדרגה כמו גם נשמו' דעקביי' כו' וזהו ג\"כ הטעם דכל הגבוה במעלה כללית יותר יותר יוכל להשיג גם את העומד למטה במדרגה מאד כי הוא כולל בעצמו כל ריבוי מיני הסתעפות והמשכו' מדרגות זו אחר זו עד גם היותר אחרוני' ומצומצמי' שמסתיימי' בסוף כל",[["858","43","<b>האזינו השמים</b>: דברים לב, א."],["859","44","<b>וזהו הכלל גדול. . שכל הגבוה גבוה</b>: ראה ג\"כ שערי אורה נח, א. פה, א. אוה\"ת שה\"ש ע' רס. ובכ\"מ."],["860","45","<b>וידבר ג' אלפים משל</b>: מלכים-א ה, יב."],["861","46","<b>לרבי מאיר שהי' אומר ג' מאות משלי שועלים</b>: סנהדרין לח, ב."],["862","47","<b>ת\"ר אלף רגלי העם</b>: במדבר יא, כא."]]],[2101000149,"המדרגו' כו' משא\"כ מי שאינו במעלה כללית כ\"כ לא ישיג רק עד מקום ומדרגה שמתכללת בו ולא למטה יותר כו' וד\"ל וע\"כ העומד למעלה יותר יביט למטה יותר כו' והוא עיקר ענין טעם כח ירידת החכם הגדול ביותר למדרגות הנמוכו' ביותר כנ\"ל כי הוא כח כולל ביותר גם כל בחי' צמצום השכל הקטן ביותר משא\"כ מי שאינו חכם כ\"כ שאינו שכלו כולל כ\"כ ואינו מתחלק לצמצומי' רבים בירידו' המדרגות כ\"כ כו' וד\"ל) והנמשל מכל אלה יובן למשכיל ג\"כ בטעם ירידת כח הראי' למטה יותר מכח השמיעה כנ\"ל לפי שהוא כח גבוה יותר להיותו בבחי' החכמ\"ה שלמעלה מבחי' בינה כנ\"ל ע\"כ ביכולתו לירד למטה יותר לחבר גם מהות גשמי ומתפשט למרחוק יותר כנ\"ל מטעם כלל הנ\"ל וד\"ל.\n<b>ועם</b> כל הנ\"ל יובן ג\"כ בטעם ענין השמיעני את קולך שהוא קול דתורה והראיני את מראיך שהן המצות כנ\"ל, להיות כי ידוע דשרש המצות למעלה הן גבוהי' מאד למעלה גם מבחי' חכמה שבתורה שהרי שרש דחכמה שבתורה למעלה הוא בחי' חכמה סתימא' דא\"א שנק' חכים<sup data-n=\"863\">48</sup> ולא בחכמה ידיעא והתורה נק' נובלות ח\"ס כידוע אבל שרש המצות למע' מבחי' מו\"ס דא\"א וכידוע דבחי' י\"ג חוורתי דע\"י הוא<sup data-n=\"864\">49</sup> שרש תרי\"ג מצות שנק' תרי\"ג ארחין דגלגלתא דא\"א ובחי' עתיק נחשב מסוף עולם הא\"ס ממש והחכמה אינה אלא רק בחי' הארה בעלמא ממנו וכמ\"ש והחכמה<sup data-n=\"865\">50</sup> מאין תמצא אפי' ח\"ס בכלל ולזה הטעם ירדו המצות ונתלבשו בדברי' גשמיי' דנוג\"ה דעשי' מפני טעם כלל הנ\"ל דכל הגבוה יותר יותר ירד למטה וכמו כח המחבר שבכח הראי' שמתפשט למטה יותר וע\"כ אמר על המצות לשון מראה וראיה אבל על החכמה שבתורה שלמטה במדרגה דהיינו מבחי' ח\"ס דא\"א אמר השמיענ\"י את קול\"ך שנמשל לבחי' כח השמיעה הרוחנית שאינו מתפשט למטה כ\"כ להיותה למטה במדרגה מכח הראי' כנ\"ל וע\"כ אינו נתפס בדבר גשם כ\"כ כו' והוא בחי' הקול שהוא רוחני יותר וא\"כ הרי מובן דגם שבשרש המצות גבוהי' הן למעלה מן חכמה שבתורה אך מ\"מ למטה הרי חכמה שבתורה מלובש בענין ומדרגה רוחני' דקול משא\"כ התלבשו' המצות שהן בעשי' גשמי' והוא לפי שלמטה התורה למעלה במדרגה מן המצות וע\"כ אמרו דתלמוד<sup data-n=\"866\">51</sup> גדול שמביא לידי מעשה וכן אמרו דת\"ת<sup data-n=\"867\">52</sup> כנגד כולן כו' וכמ\"ש במ\"א בפי' והחכמ\"ה<sup data-n=\"868\">53</sup> תחי' בעלי\"ה כו' וד\"ל.\n<b>וזהו</b> השמיעני את קולך כי קולך ערב פי' קול הוא בחי' הממוצע הכולל ב' הפכי' כי הקול הגשמי הוא מורכב מאש ומים ורוח כנודע שכאשר היסוד האש שבלב גובר אזי הקול גס ועב וכמ\"ש נח\"ר <sup data-n=\"869\">54</sup> גרוני כו' ובאשר יסוד המים שבלב גובר",[["863","48","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["864","49","<b>הוא שרש תרי\"ג מצות שנק' תרי\"ג ארחין</b>: ראה זח\"ג קכט, ב ובביאור האריז\"ל שם. מ\"ח מס' א\"א ספ\"ד. לקו\"ת ראה כד, א."],["865","50","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["866","51","<b>דתלמוד גדול שמביא לידי מעשה</b>: קדושין מ, ב. ובכ\"מ."],["867","52","<b>דת\"ת כנגד כולן</b>: פאה פ\"א מ\"א."],["868","53","<b>והחכמה תחי' בעליה</b>: קהלת ז, יב."],["869","54","<b>נחר גרוני</b>: תהלים סט, ד."]]],[2101000150,"אזי הקול צלול ובהיר והרוח שבקול הוא הממוצע המורכב מאש ומים יחד וז\"ש יביע<sup data-n=\"870\">55</sup> אמ\"ר א\"ש מי\"ם רו\"ח דקול ולמעלה היינו בחי' הת\"ת שכולל לחו\"ג ונק' קול יעקב והוא בחי' הרחמים כידוע והענין הוא כי בחי' רצו\"א ושו\"ב חו\"ג הן ב' הפכי' כמו אש ומים שזה עולה וזה יורד כו' כידוע והממוצע המחברם יחד הוא הממוצע בין חו\"ג שהוא מדת הרחמים לפי שמדת הרחמים מחייבת לזכות גם את החייב עפ\"י מדת הדין מצד הרחמנו' ולא מצד חיוב זכות של חסד אלא רק מפני הרחמנות בלבד לומר דאע\"פ שאין עליו זכות לפוטרו מ\"מ מצד הרחמנות יש לפוטרו כו' ונמצא כלול ברחמים מחו\"ג כו' וד\"ל, והנה עד\"ז גם בבחי' קול דתורה הוא בבחי' ממוצע מאחר שמורכב מאש מים רוח ג\"כ והענין הוא כידוע בפי' המאמר תלת<sup data-n=\"871\">56</sup> קשרין הן ישראל מתקשראן באוריי' ואוריי' בקודב\"ה כו' ונמצא אוריי' היא בחי' ממוצע בין ישראל לקודב\"ה מאחר דישראל מתקשראן בה והתורה מתקשרת בקודב\"ה להיותה בחי' חכמתו העצמית כנודע וענין התקשרות ישראל באורייתא הוא בבחי' העלאה מלמטה למעלה שהוא מצות ההגיון כמ\"ש והגית<sup data-n=\"872\">57</sup> בה יומם ולילה וכידוע שמצות העיון בתורה הוא התקשרות הנפש והתכללותה בחכמה שבתורה ומצות הקריאה בתורה בקול ודיבור הוא בחי' המשכת אור א\"ס בחכמה שבתורה מלמעלה למטה והממוצע המחבר להעלאה והמשכה זאת הוא בחי' קול דתורה כשאדם קורא בקול בדבר<sup data-n=\"873\">58</sup> ה' זו הלכה כו' והיינו גופה של ההלכה שבה נמשך אור א\"ס מלמעלה למטה ובה נכלל ניצוץ האלקי בבחי' עיון והגיון כנ\"ל ווהו ענין קשר האמצעי דאורייתא בין קודב\"ה לישראל וד\"ל, וזהו השמיענ\"י את קול\"ך פי' הקדב\"ה אומר לכנ\"י השמיענ\"י קול דתורה שהוא בחי' מל' דאצי' שמעלה מ\"ן בבחי' קול דתורה שהוא בחי' ממוצע מחו\"ג ע\"ד הנ\"ל בקול דתפלה שכולל רצוא ושוב כו' וזהו כי קול\"ך ערב<sup data-n=\"874\">59</sup> פי' קול ערב הוא עד\"מ הקול הגשמי כשהוא ממוזג מב' קולות הפכיי' חדוה ומרירות יחד הוא הנק' קול ער\"ב ומתוק להשיב נפש השומע כו' כך למעלה מעוררי' כנ\"י בקול דתורה הנ\"ל בחי' עריבות ומתיקו' העונג העליון הנק' עתיקא וסתימא' והוא בחי' התגלות העוגג העליון דע\"י בבינה שנק' קו\"ל ער\"ב מטעם הנ\"ל דקול דתורה ממוזג מחו\"ג כו' וזהו כי קול\"ך ערב.\n<b>ומראך</b> נאוה, הנה מבואר שיש בפי' מראה שני פירושי', הא' ענין מראה ודמות כפשוטו כמו איש תואר שמתואר בצורה נאה נק' יפה תואר, ואם ציור הגוונים בעצם יפים נק' יפה מראה דהיינו שעצם הציור נאה הגוונים נאים אדום וסומק כמו התפוח שגוון אדום ולבן שבו הן יפים למראה והוא הנק' יפה מראה משא\"כ יפת תואר שאינו אלא אופן הציור שמצוייר ומתואר באופן נאה, ויש איש יפה תואר ואינו יפה מראה לפי שאין הגוונין בעצם יפים רק התואר הוא יפה כמו שחורה<sup data-n=\"875\">60</sup> אני ונאוה שהמראה שחור שאינו יפה אבל מ\"מ נאוה אני בתואר עד שנק'",[["870","55","<b>יביע אמר</b>: תהלים יט, ג."],["871","56","<b>תלת קשרין הן</b>: ראה זח\"ג עג, א."],["872","57","<b>והגית בה יומם ולילה</b>: יהושע א, ח."],["873","58","<b>בדבר ה' זו הלכה</b>: שבת קלח, ב."],["874","59","<b>ערב</b>: ע\"כ נעתק מגוכי\"ק. ומכאן ואילך נעתק עפ\"י כת\"י מעתיק."],["875","60","<b>שחורה אני ונאוה</b>: שה\"ש א, ה."]]],[2101000151,"צורה של חן כמו ותהי<sup data-n=\"876\">61</sup> אסתר נושאת חן כו', ויש יפה מראה ואינו יפה תואר דהיינו שהגוונין בעצם יפי' אבל אין הצורות התואר יפה וביוסף נאמר יפ\"ה<sup data-n=\"877\">62</sup> תואר ויפ\"ה מרא\"ה וכן ברחל אבל ברבקה נאמר וטובת<sup data-n=\"878\">63</sup> מראה מאד ולא נז' טובת תואר אבל באסתר והנערה<sup data-n=\"879\">64</sup> יפת תואר ויפת מראה כו', ושרש הענין לפי שהתואר שהוא טוב הציור מורה על בחי' הכלים המגבילים ומתארים את האור כו' והמראה שהוא עצם הגוונין מורה על בחי' האורות העצמי' כמו חכמת<sup data-n=\"880\">65</sup> אדם תאיר פניו שע\"י התענוג שבשכל נמשך באדם הארת פנים כידוע בענין צהבו<sup data-n=\"881\">66</sup> פניו דר' אבהו כו' דהיינו בחי' בקיעות האורות והמוחי' הפנימי' שמאירים בפנים ובוקעים בעור הפנים כמו קרן<sup data-n=\"882\">67</sup> עור פני משה כו' אבל אופן ציור הגוונין שבוקעי' מבחי' הפנימי' של האדם הוא רק בחי' הכלי המגביל ומתאר בתואר וצורה, אך בבחי' הכלי' דוקא ניכר ונגלה ערך מעלת האור עד\"מ באותיות השכל או בכלי המוח הטוב יותר שם ישכון אור השכל ביותר, אך יוכל להיות לפעמי' שאין הכלי לפי ערך מעלת האור, ולפעמי' להיפוך שאין האור לפי מעלת הכלי ע\"כ יוכל להיות יפה מראה ולא יפה תואר או להיפוך יפה תואר ולא יפה מראה, אבל כאשר יתחבר האור והכלי בערך א' אז נק' יפ\"ה תוא\"ר ויפ\"ה מרא\"ה כמ\"ש ביוסף ורחל דהיינו בחי' אורות וכלים שבפנים העליוני' שצדיק<sup data-n=\"883\">68</sup> עליון שנק' יוסף וכן במל' דאצי' שנק' רח\"ל שנק' עקר\"ת הבית אבל באסת\"ר ורבק\"ה נא' טובות מראה כו' וד\"ל.\n<b>והנה</b> עיקר היופי הוא בשני דברים הללו בתואר ומראה כמ\"ש יפה תואר ויפה מראה כנראה בציור דבר מה שעיקר היופי תלוי בב' דברים הא' בעצם הגוונין אם הם נאים ומהודרים והב' באופן טוב ציורם (והחן הוא הכולל משניהם יחד כאשר המה במזיגה נכונה מאד והוא בחי' עצם הטוב שבנפש שמאיר בפנים וע\"כ יש שאינו טוב תואר ולא טוב מראה והוא נחמד ונושא חן בעיני כל וע\"כ שקר<sup data-n=\"884\">69</sup> החן והבל היופי דמשמע שהן ב' דברים כו') אך הנה עיקר היופי במראה יותר מבתואר, ועיקר החן בתואר יותר מבמראה לפי שעיקר התפארת הוא טוב המראה בגווני' נאים בעצם וע\"כ נא' באסתר ח\"ן לפי שנאמר בה יפה תוא\"ר וטובת מראה ולא נא' יפ\"ת מראה כמו ברחל שנק' יפת תואר ויפת מראה כי אסתר היא בחי' מל' דבריאה או מל' דאצי' שמסתתרת בראש הבריאה ואין בה בחי' יופי המראה מצד בחי' עצמות אורות גונין דמדת וחכ' עילאה רק נק' טוב\"ת מראה דהיינו שמאירי' בבחי' טוב החסדי' עד\"מ כשהמלך בטוב לבב יאיר פניו ג\"כ בפנים צהובות ואז נק' מרא\"ה טו\"ב ולא מרא\"ה יפ\"ה שהוא יפה בעצם ולא מצד בחי' טוב וחסד כו' אבל בתואר שהוא בחי' הכלי' דמל' דבריאה נק' יפ\"ת תוא\"ר כידוע בענין שש משזר",[["876","61","<b>ותהי אסתר נושאת חן</b>: מג\"א ב, טו."],["877","62","<b>יפ\"ה תואר ויפ\"ה מראה</b>: בראשית לט, ו. כט, יז."],["878","63","<b>וטובת מראה מאד</b>: ראה בראשית כד, טז."],["879","64","<b>והנערה יפת תואר</b>: ראה אסתר ב, ז."],["880","65","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["881","66","<b>צהבו פניו דר' אבהו</b>: ירושלמי שבת פ\"ח ה\"א."],["882","67","<b>קרן עור פני משה</b>: שמות לד, לה."],["883","68","<b>שצדיק עליון שנק' יוסף</b>: ראה זח\"א קנג, ב. ובכ\"מ"],["884","69","<b>שקר החן והבל היופי</b>: משלי לא, ל."]]],[2101000152,"תכלת כו' שהן הגוונין דמל' דאצי' בבריאה כמשל התגלות המדות באותיות הדיבור אבל בחי' מל' דאצי' שנק' רחל הוא ג\"כ יפ\"ת מרא\"ה מצד בחי' עצם האורות, ורבקה נק' רק טוב\"ת מרא\"ה על שם עוצם רב טוב וחסד עליון שמאיר במוחין ומדות שבה וזהו טובת מראה מאד כו' והוא שרש בחי' הח\"ן שהוא שורה בטוב המראה או ביופי התואר אבל לא ביופי המראה שביופי המרא\"ה העיקר הוא בחי' התפארת וכמ\"ש ותשא<sup data-n=\"885\">70</sup> חן וחסד הזן<sup data-n=\"886\">71</sup> בחן ובחסד הרי עיקר החן הוא הטוב והחסד משא\"כ היופי לא שייך בבחי' החסד והטוב כלל, ומ'ש שחורה אני ונאוה היינו מצד בחי' החן ששורה בטוב תואר דוקא, וכן כלה<sup data-n=\"887\">72</sup> נא\"ה וחסודה ר\"ל ב' דברים נא\"ה מצד היופי במראה ותואר וחסוד\"ה בבחי' החן שחוט<sup data-n=\"888\">73</sup> של חסד משוך עלי' כמו באסתר דכתי' בה ותהי<sup data-n=\"889\">74</sup> נושאת ח\"ן כו', אבל הנה בחי' החן שבתואר והיופי שבמראה כלולי' כא' ומתגלים בדמות וצלם כל דבר המצויר ג\"כ כמו פני אדם הנראי' בציור ביופ\"י או במראה (הנק' שפיגל בל\"א) ומ\"מ יותר ימצא חן לפניו אדם עצמו בפניו הנראה במראה או בציור, וכן יהי' היופי בפני אדם עצמו מפניו הנראי' בציור או במראה, לפי שפנים העצמי' הן מראי' בחי' עצמות האור והחיות יותר מציור דמותו להיותו תואר ומראה עצמית והוא ההפרש בין צלם ודמות כידוע ומבואר במ\"א וד\"ל. והנה הפי' הב' במרא\"ה לשון הוראה כמו מראה באצבע ולכאורה שני הפירושים רחוקים זמ\"ז דלשון הוראה אינו מענין דמות ומראה כלל, אבל באמת שניהם שרש וענין א' הוא, דהנה ענין ההוראה כמו כאשר מורה באצבע על איזה איש הרי ההוראה הזאת על מהותו ועצמותו של אותו האיש דהיינו על פנימי' נפשו וכוחותיו ולא על גופו ואברים החיצוני' בלבד, אך הנה מ\"מ דבר המורה על עצמותו ומהותו הרי היא ע\"י הוראת האצבע על גופו דהיינו על ציור תמונתו הגופנ\"י כי הנה במה יוכר ויופרש בין ראובן לשמעון וכיוצא הרי אין ההוראת<sup data-n=\"890\">75</sup> זה ההפרש רק בציור התמונה של גוף ראובן שהוא נבדל ומשונה מציור ותמונה של גוף שמעון וכאשר מראה באצבע על ראובן עיקר הוראתו על ציור תמונתו שמורה על עצמותו ומהותו כו', וא\"כ הרי מובן עכ\"פ מכל זה שההוראה באצבע על ציור התמונה ענין א' עם ההוראה מה שהתמונה מורה כי התמונה מורה על העצמיו' ע\"כ מורה באצבע עליו וע\"כ ממילא מובן ג\"כ שהתמונה נק' מראה מב' טעמים הא' לשון מראה ודמות שהוא ציור התמונה בלבד כפשוטו והב' לשון הוראה מפני שהתמונה והדמות מורה על בחי' העצמיות והמהות דוקא והוא ענין ב' הפירושים שבמראה לשון הוראה ולשון דמות ששניהם עולין בקנה א' ושרש א' להם וד\"ל.\n<b>אך</b> הנה לכאורה יפלא על עיקר הענין איך יתכן לומר שציור התמונה והדמות בלבד יורה על בחי' העצמות דוקא הלא כל עיקר ציור והתמונה של הגוף אינו אלא בעור גשמי שהוא נבדל לגמרי בערך מכחות הנפש גם מכחות אברים החיצוני' שבה ומכש\"כ באברי' הפנימי' כו'. אמנם הענין יובן עפ\"י הנ\"ל בענין שרש מראה",[["885","70","<b>ותשא חן וחסד</b>: מג\"א ב, יז."],["886","71","<b>הזן בחן ובחסד</b>: נוסח ברכת המזון."],["887","72","<b>כלה נאה וחסודה</b>: כתובות יז, א."],["888","73","<b>שחוט של חסד משוך עליה</b>: מגילה יג, א."],["889","74","<b>ותהי נושאת ח\"ן</b>: מג\"א ב, טו."],["890","75","<b>ההוראת</b>: כ\"ה בהכת\"י. ובכת\"י ב: הוראה."]]],[2101000153,"ותואר שהמראה בגוונין כאדמימות ולבנונית שבפנים הגם שאינו אלא מראה גוון חיצוני' מ\"מ הגווני' הללו כשהן יפים הם מורים על בחי' העצמי' דהיינו כמו בחי' הארת התענוג שבחכ' שבמוח שמאיר בלחיים שבפנים שתאיר פנים כמ\"ש חכמת<sup data-n=\"891\">76</sup> אדם תאיר פניו וכמו כי<sup data-n=\"892\">77</sup> קרן עור פני משה כו', לפי שבחי' אורות המוחין בוקעין ומתגלין בעור הפנים ממש ומזה נתעורר פנימי' החיות אשר בדם הוא הנפש ומאיר בגוון אדום וגוון לבן כו' וכנראה לעין שכאשר יגידו לאדם בשורה טובה יצהבו פניו ויאירו בגוון שונים מפני שפנימי' אורות נפשו באין מן ההעלם לגילוי בפניו, וכן ע\"י התענוג שבחכ' חדשה כנ\"ל, וא\"כ הגם שאינו אלא מראה חיצונית מ\"מ מלובש בה כל בחי' הפנימי' והעצמיות ומזה יובן ג\"כ גם בלי התחכמות ועונג בשורה שמראה וציור תמונת הפנים מורה על בחי' עצמי' הנפש וכמ\"ש<sup data-n=\"893\">78</sup> בזהר יתרו ואתה תחזה כו', עד שכל עיקר מהות האדם אינו ניכר רק ע\"י ציור תמונת אברי גופו, והעיקר הוא בתמונת הפנים, שהרי לא יוכר בין ראובן לשמעון רק ע\"י ציור תמונת הפנים והגוף כנ\"ל. ואעפ\"י שאין הציור הזה רק הוראה בלבד איננה בחי' חיצוני' כמו מראה ודמות בלבד שאין בה מבחי' חיות הפנימי כלל אלא אדרבא כל בחי' הפנימי והעצמיות מלובש בציור ותמונה זאת, והמופת לזה מגוון התפוח שמורה ג\"כ על עצם מהותו כמו אם הגוון של התפוח אדום מורה על עצם טעמו שהוא חומץ ואם גוון לבן מורה על עצם טעמו שהוא מתוק כידוע, ובוודאי אין טעם חמיצות ומתיקות כלל בגוון אדום או לבן שעל התפוח מבחוץ כי אינו אלא מראה וגוון חיצוני בלבד, רק בעצם גופו של תפוח נרגש טעם מתיקות או חמיצות, ואעפי\"כ יש בגוון הללו בחי' התלבשות מעצם התפוח אחר שלעולם לא ימצא בהיפוך שהתפוח לבן יהי' חומץ כו' א\"כ הלובן עצם מתיקות טעמו מלובש בו כו' כי התמונה היא עצמות הדבר כו'.\n<b>ויובן</b> זה בתוס' ביאור מאשר אנו רואי' הפרש גדול בעצמות ומהות של נפש ראובן לנפש שמעון וכיוצא שנפש ראובן שלימה בכל המעלות בחכ' ומדות טובות וכה\"ג ונפש שמעון חסירה מכל מעלה שאינו חכם ולא בעל מדות טובות או ההפרש בין נפש זכר לנפש נקבה או בין נפש שר ומלך לעני וחולי וכה\"ג הרי כל ההיכרות ההפרש הזה אינו ניכר רק בציור ותמונה בלבד דהיינו כאשר מכבר יודעים ומכירים ציור תמונת ראובן הידוע במעלתו ומדותיו ויודעים בציור תמונת של שמעון החסר מכל כו' אזי יבדילו ביניהם ויכירו ההפרש ביניהם שזה חכם ושלם בכל וזה חסר מכל, וא\"כ לא יוכר בין שלימות עצם הנפש לפחיתת ערכו רק ע\"י הציור והתמונה והיינו מ\"ש בזהר ע\"פ ואתה תחזה שניכר כל מדה בתמונה וציור בפנים במצחא ובעיניו (רק ששם מבואר בהכרת פנימיות הכחות וכל הצלחתו בכל ימי חייו כו' ע\"ש שזהו מורה על בחי' אורות המקיפי' שנק' צלם וכמ\"ש אך<sup data-n=\"894\">79</sup> בצלם יתהלך איש והצלם הזה בחי' עצמו' שורה דוקא בבחי' הציור והתמונה בלבד שהוא הנק' תואר ולא מראה כנ\"ל באריכות והוא הגבלת הכלים ששרשם בבחי' מקיפי',",[["891","76","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["892","77","<b>כי קרן עור פני משה</b>: שמות לד, לה."],["893","78","<b>וכמ\"ש בזהר יתרו ואתה תחזה</b>: זח\"ב ע, א."],["894","79","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז."]]],[2101000154,"דהנה נראה בחוש שיוכל האדם להתפעל מזולתו מתנועות ידיו ורמזי עיניו וקמטי מצחא או לטוב או לרע מאשר הי' מגלה לו בדבור כמו בשמחה גדולה שסופק בכפיו ובהיפך בכעס גדול עד שתוקע לחבירו, שהוא גדול הרבה מכעס או שמחה המתיישבת בלב בבחי' או\"פ ובא לדבור, להיותו בבחי' מקיפי' כידוע וזהו ניכר בכלל בהשתנות פנים במראה מלובן לאודם או מאודם ללובן כמו המבייש דאזיל<sup data-n=\"895\">80</sup> סומקא כו', ולהיפך השמח בשמחה שיאירו ויתאדמו פניו, וכן השתנות מראה הפנים בכעס ללובן, ובהיפוך בטוב לבו יאיר פניו באודם, וכן יוכר השינוי במצחו ובעיניו כמו כשהוא טוב עין או צר עין או מצחו קשה במדות הדין או להיפוך מצחו רצוי ברצון טוב כמ\"ש<sup data-n=\"896\">81</sup> באד\"ר דבמצחא אתגלי' רעוא דכל רעוין כו', וכ\"ז השינוי במראה הגוונין להיות ששרש בחי' המקיפי' נמשכי' ונתלבשו בגוונין הללו וע\"כ יוכר כל מהות נפש האדם במראה שלו כנ\"ל, אך ההפרש בין מראה לתואר שהתואר מורה על עצם אורו' המקיפי' שנק' צולמא דב\"ן במהותם ואיכותם העצמי כמו לאיזה דבר הוא מוצלח אם לעושר או לחכ' וכמבואר בזהר שם, אבל המראה הוא בחי' התלבשות המקיפי' בשינוים שונים והיינו מה שעצם בחי' המקיפי' מראין בגוונין בלבד, אבל התואר מורה על עצם צולמא דב\"נ כו' וכמ\"ש ביוסף יפ\"ה תואר ויפ\"ה מראה היינו בין בעצם הצלם ובין בהתגלותו בגוונין (וכאשר הצלם שורה כבר בפנים נק' המראה בחי' אור והתוא\"ר נק' בחי' הכלי המתאר ומגביל לאור כנ\"ל באריכות, אך בשורש עצם הנפש התואר מורה על עצמיו' ממש משא\"כ המראה שאינו אלא דמות הצלם כו' וד\"ל). ועכ\"ז יובן יותר ענין הנ\"ל בהפרש שבין חן ליופי שהחן עיקרו בטוב תוא\"ר, וכמו ההפרש בין טוב<sup data-n=\"897\">82</sup> תוא\"ר מאד שנז' באדוניהו בן חגי\"ת, ובין טובת<sup data-n=\"898\">83</sup> מראה מאד שנז' ברבקה או טוב<sup data-n=\"899\">84</sup> מראה שנז' בדוד כו', לפי שבחי' הח\"ן מאיר מעצם צלם הנפש והוא התואר והיופ\"י נמשך בדמות הגווני\"ן המראין מעצם כו' וד\"ל). ונמצא מובן כ\"ז שבציור ומראה התמונה אעפ\"י שאינה אלא בעור חיצוני מ\"מ נתפס ומלובש בה כל בחי' העצמיות דצלם ומקיפי' דכל בחי' אורות הפנימי' ביותר כנ\"ל עד שיוכל האדם להבין ולהכיר במצח ועין פנימי' הרצון והחכ' ולהכיר בתואר וציור הפנים כל מהותו הפנימי' כו' כנ\"ל באריכות.\n<b>והנמשל</b> מכל אלה יובן למשכיל למע' בשורש ענין ההפרש בין תורה למצות שהמצות נק' מרא\"ה כנ\"ל והתו' נק' קול וז\"ש הראיני את מראיך שהן המצות כמ\"ש במראה ב' פירושים הא' לשון דמות והב' לשון מראה, ושניהם ענין אחד להיות כי הדמות והמראה מורה על בחי' העצמיות דוקא כנ\"ל, וגם המצות שנק' בשם מראה היינו שהן רק בבחי' דמות ומראה כבוד ה' הפנימי' דאצי' במקיפי' כו' אך הנה מ\"מ הרי נתפס בהן כל בחי' העצמיות והפנימי' דהוי' כו' כמובן מתוך הנ\"ל. וביאור הדברים הנה באמת מעשה המצות למטה הן מלובשי' בענינים גשמי'",[["895","80","<b>דאזיל סומקא</b>: ב\"מ נח, ב."],["896","81","<b>כמ\"ש באד\"ר דבמצחא אתגליא</b>: זח\"ג קכט, א."],["897","82","<b>טוב תואר מאד</b>: מלכים א א, ו."],["898","83","<b>טובת מראה מאד</b>: בראשית כד, טז."],["899","84","<b>טוב מראה שנזכר בדוד</b>: ראה שמואל א טז, יב."]]],[2101000155,"מאד כמו מצות תפילין בד' פרשיות כתובי' בדיו וקלף גשמי ומונחים בד' בתים גשמי' וכן מצות ציצית בצמר דכבש גשמי ול\"ב חוטין גשמיי' כו' וכה\"ג כל המצות כמו מצות הצדקה בחסד גשמי' כו' ומצות ת\"ת בלימוד עניני' גשמי' כו', אך הנה ידוע שכל מצוה גשמיי' מרמזת ומורה על ענין וסוד ה' פנימי למע' באצי' כמו מצות התפילין למטה בד' פרשיות בד' בתים רומזי' על בחי' ד' מוחין עליוני' כו' ול\"ב חוטין דציצית רומזים על בחי' ל\"ב נתיבות ח\"ע שנמשכי' מבחי' או\"מ דטלית כו' וכה\"ג בכל המצות כולן הן רק כמו הרמז בלבד עד\"מ אדם שמרמז בדבר גשמי שיבינו ממנו ענין פנימי כמו די<sup data-n=\"900\">85</sup> לחכימא ברמיזא כו' שהוא כאשר לא יוכלו להסביר הדבר בדיבור ירמזו ברמז ובאותו הרמז נתלבש אותו דבר המעמיק שבודאי אין ערך לרמז הגשמי לאותו הענין הפנימי הנרמז עלי' כו' כך כל המצות הן רק בחי' רמזי' בלבד אך בהן מתלבש כל בחי' הפנימי' של האורות העליוני' כמו בד' פרשיות תפילין מתלבשי' בחי' פנימי' ד' מוחין ובל\"ב חוטין דציצית מתלבש ל\"ב נתיבות דמקיפי' כו', דהנה אעפ\"י שאין המצות רק בחי' רמזי' בלבד מ\"מ כל עיקר בחי' העצמות והמהות דאוא\"ס שבאצי' באורות וכלים הכלולי' בשם הוי' כו' נתפס ומלובש בהן כי הן נמשלי' לבחי' מראה ודמות שהוא בחי' הוראה על בחי' העצמות כנ\"ל דהיינו שבחי' העצמות נתפס בהן כנ\"ל ממשל עור פני האדם שבתמונתו יכירו כל עצמותו כו' וכן המצות<sup data-n=\"901\">86</sup> הרי נקראו בשם רמ\"ח אברי' דמלכא דהיינו דוקא בחי' גילוי ציור התמונה של כל אבר כמו האור של החסד הפנימי' שמתלבש בתמונת אברים ונק'<sup data-n=\"902\">87</sup> החסד דרועא ימינא כו' ולמטה הוא מצות הצדקה שמלובשת ברמז כו' להורות על בחי' חסד עליון שבדרועא ימינא כו', וכן מצות התפילין הן בחי' ד' מוחין שמצטיירי' בד' חללי גלגלתא וכמו שא' חכ' מוחא וניכרין דוקא במצח שעל הראש ע\"י התפילין הבולטי' שם וכמ\"ש במ\"א באריכות וכן כל המצות הן נק' בחי' מראה ותמונה דהיינו שהן מראין על בחי' הפנימי' והעצמי' דמקיפי' עליוני' דא\"א ואו\"א כו' שמלובש ונתפס בהן כו' עד\"מ שנתפס כל מהות נפש האדם בציור תמונתו, וע\"ז אמר בפקודיך<sup data-n=\"903\">88</sup> אשיחה אביטה אורחותיך פי' אורחות דשם הוי' דאצי' הן תרי\"ג ארחין שבגלגלתא ששם משכן צלם המקיפי' שאינן נכרין אלא בבחי' מראה וציור הנגלה ברמ\"ח איברים דמלכא כו' וכמבואר ומובן מתוך כל הנ\"ל בענין המראה, וז\"ש הראיני את מראיך שהן מרא\"ה המצות כו' וד\"ל.\n<b>וז\"ש</b> השמיעני את קולך כי קולך ערב ומראך נאוה ולכאו' הל\"ל כי מראך נאוה תחלה ואח\"כ כי קולך ערב כמו שהקדים הראיני את מראיך ואח\"כ השמיעני כו' כנ\"ל, אך הענין הוא משום דבחי' קול דתורה שרשו בבחי' ח\"ע סתימאה ובה מלובש בחי' עונג העליון שנק' בחי' עתיקא סתימאה וז\"ש כי קולך ערב בבחי'",[["900","85","<b>די לחכימא ברמיזא</b>: מדרש משלי כב. זח\"ג רכט, ב. רפ, ב. ת\"ז תי\"ח (לו, א). תס\"ט (קז, ב. קטז, א). ועוד."],["901","86","<b>המצות. . רמ\"ח אברי' דמלכא</b>: ראה ת\"ז תי' ל. זח\"ב קיח, א. תניא פ\"ד ובליקוט פירושים ומ\"מ שם."],["902","87","<b>ונק' החסד דרועא ימינא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["903","88","<b>בפקודיך אשיחה אביטה אורחותיך</b>: תהלים קיט, טו."]]],[2101000156,"עריבות דעונג העליון והוא בחי' או\"פ ביותר ממעשה המצות שהן בבחי' מראה ורמז חיצוני בלבד כנ\"ל, וע\"כ א' תחלה כי קולך ערב, אך שרש בחי' מראה דמצות הרי הוא בבחי' הוראה על עיקר העצמות דהיינו על בחי' צלם המקיפי' שבתרי\"ג ארחין דגלגלתא דא\"א ששם הוא בחי' תענוג הפשוט שברצון הפשוט הכלול בעצמות אוא\"ס ממש שלמע' הרבה גם מבחי' הארת עונג העליון הנעלם שמלובש בח\"ס דא\"א בקול דתו' ע\"כ הקדים תחלה הראיני את מראיך שבמעשה המצות כדי לעורר בחי' מקיפי' דתענוג הפשוט ששורה על הגלגלתא דא\"א בבחי' מקיף כמ\"ש למע' בענין צלם המקיף דאיש למטה כמ\"ש אך בצלם יתהלך כו' ואח\"כ השמיעני את קולך קול דתורה שהוא בחי' עונג הנעלם דע\"י הממוזג מחו\"ג ונק' קול ערב כנ\"ל, וזה בקשת עצמות המאציל מכנ\"י שנק' מל' דאצי' בהיותה מסתתרת בבי\"ע בהתלבשות גשמי' כו' ואמר בנתינת טעם תחלה כי קולך ערב כו' משום דבבחי' ההעלאה מלמטה למעלה בבחי' או\"ח הרי בחי' קול דתורה עולה תחלה ואח\"כ מראה דמצות משא\"כ בבחי' המשכה מלמעלה למטה מעצמות המאציל לכנ\"י אומר הראיני את מראיך תחלה לפי שנעוץ תחלת המח' בסו\"מ דוקא כידוע וד\"ל.\n<b>ומ\"ש</b> כי קולך ער\"ב ומראיך נאוה הנה שניהם שרש וענין א' דהיינו בחי' המזיגה מכמה הפכי' יחד, ואמנם בקול הוא הממוזג מכמה קולות הפכי' חדוה ומרירות כו' נק' קול ערב כידוע ובקול דתורה היינו בחי' תלת קשרין הנ\"ל או מצד בחי' התכללות חו\"ג שעפ\"י חכ' שבתורה או מצד בחי' העונג שבחכ' שכלול מכמה הפכי' כו' ובמזיגה זו שנק' תפארת מלובש ג\"כ מבחי' עצמות העונג כידוע, אך במזיגה דמראה מכמה גוונין הפכי' עד שנק' יפה מראה או יפה תואר הנה הוא בחי' הוראה על עצם התענוג הפשוט ממש כנ\"ל וז\"ש ומרא\"ך נאו\"ה פי' בחי' מראה דמצות שמלובש ונתפס בהן כל בחי' העצמות ע\"כ בחי' המראה הזאת נאו\"ה היא בבחי' התפארת שבעצמות המאציל ממש להיותו בצלמו ודמותו ממש כמובן מתוך כל הנ\"ל וד\"ל.\n<b>ובכל</b> הנ\"ל יובן ענין אחד והוא אשר לכאורה יפלא מאוד במה שמצינו הפרש גדול בין תורה למצות כענין השכר לעוה\"ב שאמרו ז\"ל דכל<sup data-n=\"904\">89</sup> ישראל יש להם חלק לעוה\"ב שנאמר ועמך כולם צדיקים כו' ומשמע אפי' רשעים גמורים שעברו על כל התורה כו' מלבד אותן שנמנו בפירוש שאין להם חלק לעוה\"ב והן ד' מלכים משום שעוה\"ב עיקרו על מעשה המצות והרי אפילו<sup data-n=\"905\">90</sup> פושעי ישראל מלאים מצות כרימון ואפילו לא למד תו' כלל וכלל יש לו חלק לעוה\"ב אם עשה מצוה א' ושתי' כידוע ואם לא עשה מצוה כלל אפי' למד תורה הרבה אין לו חלק לעוה\"ב, ולהיפוך בעונש האבדון לדראון עולם נא' הפושעי' בי והיינו רק בהעדר מעשה המצות וכמ\"ש<sup data-n=\"906\">92</sup> בזהר הפושעים<sup data-n=\"907\">91</sup> בי בגופא דמלכא ובדברי רז\"ל מרומז ג\"כ שאמרו",[["904","89","<b>דכל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין צ, א."],["905","90","<b>אפילו פושעי ישראל מלאים מצוות</b>: עירובין יט, א."],["906","92","<b>וכמ\"ש בזהר הפושעים בי בגופא דמלכא</b>: זח\"ב פה, ב."],["907","91","<b>הפושעים בי</b>: ישעי' סו, כד."]]],[2101000157,"פושעי<sup data-n=\"908\">93</sup> ישראל בגופן זה קרקפתא דלא מנח תפילין כו', אבל לא על ביטול תו' הגם דמצות ת\"ת כנגד כולן כו', והענין הוא מטעם הנ\"ל לפי ששרש מעשה המצות למעלה הוא רק בחי' מראה דגופא דמלכא אך שרש המראה מגיע בבחי' העצמות ממש, ולזה רמזו רז\"ל ע\"פ אדם אתם<sup data-n=\"909\">94</sup> קרוי' אדם ע\"י המצות ולא אוה\"ע כו' וכן ועשיתם<sup data-n=\"910\">95</sup> אותם כאילו עשאוני כו' ופי'<sup data-n=\"911\">96</sup> אדם אדמה לעליון דהיינו לבחי' קדמון לכל הקדומי' כו', וע\"כ כל העושה מצוה נק' אדם בדמות אדם העליון הקדמון לכל הקדומי' כו' ויזכה לחלק לעוה\"ב שאז נא' עין בעין<sup data-n=\"912\">97</sup> נראה אתה כו', וכמארז\"ל כאו\"א<sup data-n=\"913\">98</sup> מראה באצבעו הנה אלקינו זה כו', ובהיפוך בהעדר המצות נק' הפושעי' בי בי ממש, אבל מצות ת\"ת אינה אלא ענין ומדריגה אחת פרטי' והוא בבחי' החכ' שבראש שהיא כוללת ג\"כ כל האברי' עד שנק' אדם אבל אינה מגעת אל בחי' צלם העצמות ממש רק שכולל כל בחי' אור וחיות שמלובש בכלי ולא בחי' צלם העצמי' וכנ\"ל בענין המראה והקול, וע\"כ בהעדר מצות ת\"ת אינו נק' פושעי' בי ממש ובקיומה לא יחייב שכר בעוה\"ב לראות עי\"ן בעי\"ן בבחי' תפארת עצמות המאציל, וכן מ\"ש ישראל<sup data-n=\"914\">99</sup> אשר בך אתפאר היינו ג\"כ ע\"י מעשה המצות דוקא שנק' תפארת<sup data-n=\"915\">100</sup> לעושי\"ה כו', ולזה רמזו רז\"ל דבעוה\"ב<sup data-n=\"916\">101</sup> צדיקים יושבים ועטרותיהן בראשיהן דהיינו ממעשה המצות דוקא ומטעם הנ\"ל וד\"ל.",[["908","93","<b>פושעי ישראל בגופן</b>: ר\"ה יז, א."],["909","94","<b>אתם קרוי' אדם</b>: יבמות סא, א."],["910","95","<b>ועשיתם אותם כאילו עשאוני</b>: זח\"ג קיג, א. וראה ויק\"ר פל\"ה, ז."],["911","96","<b>ופי' אדם אדמה לעליון</b>: ראה ס' עשרה מאמרות מאמר אם כל חי ח\"ב פל\"ג. ובכ\"מ."],["912","97","<b>עין בעין נראה אתה</b>: ראה במדבר יד, יד."],["913","98","<b>כאו\"א מראה באצבעו</b>: תענית לא, א."],["914","99","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["915","100","<b>תפארת לעושיה</b>: אבות פ\"ב מ\"א."],["916","101","<b>דבעוה\"ב צדיקים יושבים</b>: ברכות יז, א."]]],[2101000158,"<h3>להבין שרש ענין יונתי</h3>\n<b></b><b>ביאור על תורה יונתי בחגוי הסלע</b>\n<b>להבין</b><sup data-n=\"917\">1</sup> שרש ענין יונתי<sup data-n=\"918\">2</sup> בחגוי הסלע כו', שכנס\"י נמשלה ליונה כמ\"ש עיניך<sup data-n=\"919\">3</sup> יונים כו', הנה כתיב אשא<sup data-n=\"920\">4</sup> עיני אל ההרים מאין יבא עזרי עזרי כו', פי' שרש<sup data-n=\"921\">5</sup> נפש דוד הוא מבחי' מל' דאצי' כידוע, וע\"כ הוא אומר אשא עיני אל ההרים בבחי' הסתכלות עינים כלפי מעלה, כמ\"ש עיני<sup data-n=\"922\">6</sup> כל כו', עינינו<sup data-n=\"923\">7</sup> אל ה' אלקינו, ואל",[["917","1","<b>להבין</b>: ביאור זה נמצא בכמה כת\"י, אבל לא בהמשך למאמרים הקודמים. בכת\"י ב רשום עליו: ביאור שני על תורה יונתי בחגוי הסלע. ומתוכן הדברים נראה שהוא ביאור להנ\"ל. אמנם לא ברור לע\"ע אם ביאור זה הוא מאדה\"ז או מאדהאמ\"צ.\nראה גם ד\"ה ויאמר גו' לך לך, בסה\"מ תרס\"ב ע' רמא ואילך. (ובהמקבילות אליו)."],["918","2","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["919","3","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["920","4","<b>אשא עיני אל ההרים</b>: תהלים קכא, א."],["921","5","<b>שרש נפש דוד הוא מבחי' מל' דאצי'</b>: ראה פרדס שעה\"כ וקה\"י בערכו."],["922","6","<b>עיני כל</b>: תהלים קמה, טו."],["923","7","<b>עינינו אל ה' אלקינו</b>: תהלים קכג, ב."]]],[2101000159,"ההרים הן בחי' המדות שבכתר שהן הרים העליונים ביותר (ובזוהר<sup data-n=\"924\">8</sup> נק' טורי חשוכא) מאין יבוא עזרי מבחי' אין דכתר יבוא עזרי והוא בחי' הסתכלות מלמעלה למטה כמ\"ש הנה<sup data-n=\"925\">9</sup> עין ה' אל יריאיו כו' עיניו<sup data-n=\"926\">10</sup> כיונים כו', ובהסתכלות זו מקבלת המלכות ש\"ע נהורין ולפעמים ק\"נ נהורין כמ\"ש<sup data-n=\"927\">11</sup> בע\"ח בפי' כי יקרא קן ציפור כו'. ולהבין זה הנה יש להקדים בשרש בחי' הסתכלות הראי' בעין מה היא דהנה אנו רואים שיש התלבשות כח התענוג בחוש הראי' יותר משאר החושים כי גם שיש הארת העונג בכל החושי' כמו בחוש הריח שמריח דבר בושם טוב שיערב לנפש מאד וכן חוש השמיעה כששומע קול ערב שמתענג מאד בנפשו הנה כ\"ז אין לו ערך לגבי כח התענוג שמתענג בנפשו מהסתכלות העין בדבר ציור נאה, כמו דירה נאה מאד או בגדי ת\"ת למראה או אבנים טובות מבהיקי' ביופי וכל דבר נחמד למראה ביותר שהרי אמרז\"ל העין<sup data-n=\"928\">12</sup> רואה והלב חומד הרי שהקדי' העין רואה ללב חומד כי ההתפעלות שבלב בחמדה ותשוקה נפלאה הגם שזהו התפעלות כל הנפש עד שתדבק כל נפשו בדבר הנחמד כמו ותדבק<sup data-n=\"929\">13</sup> נפשו בדינה כו', וכמו שאמר במי<sup data-n=\"930\">14</sup> שהעלה בלבו טינא על שנתן עיניו באשה א' כו' שהוא מסוכן בעיני הרופאים כו' וכידוע עכ\"ז העין הרואה בדבר הנחמד שם מלובש כח התענוג ביותר עד שמחמתו נתפעל החימוד בלב וז\"ש ולא<sup data-n=\"931\">15</sup> תתורו כו' לפי שיש בו בחי' כח חזק מן הארת התענוג עד שימשיך את הלב לחימוד (כמו בחי' ערך אור המקיף על הפנימי שהפנימי' נכלל במקיף כך החמדה בלב אעפ\"י שהוא בחי' או\"פ ובא בבחי' פנימי' ההרגשה יותר אבל כח התענוג שבראיה כולל כל מיני חמדה שהרי מסתעפים מחמת הראי' דוקא כמה מיני אופני חמדה בלב לפי ראי' העין דוקא דהיינו לפ\"ע התלבשות כח התענוג בעין הרואה אם מעט או הרבה כו', והטעם הוא כי בעין יומשך כל עצם הנפש ממש והחמדה היא רק הארה פרטי' מסתעפת ממנו כו', לפי ששרש הראי' בחכ' שבנפש שכל תענוג עצם הנפש כלולה בה כו'), וכנראה בעליל שהאדם יוציא כל רכושו על דירה נאה ואבני חפץ יותר מתענוגי המאכלים העריבים ודברי בושם כו', וגם בע\"ח מבואר אות ומופת לזה מן העוף הידוע ששמו ראה<sup data-n=\"932\">16</sup> והטעם שנק' בשם זה הוא מצד חוש כח הראי' שבו שהיא חזקה בחוש זה ביותר עד שיש התגברות בחוש הראי' שלו להוליד כי בהסתכלות הזכר על הנקבה והנקבה בזכר נמשך כח הולדה בהם כמו שנמשך ע\"י השפעת זרע לפי שכמו שהנקבה מתעברת מזרע הזכר מפני המשכת כח התענוג שבטיפת זרעם כך נמשך כ\"כ בהסתכלותם זע\"ז כו', עד שהנקיבה מתעברת מזה כמו שהיתה מקבלת שפע זרע וזה ידוע גם בספרי הרפואה שיוכל להתקבץ כל כח הנפש מכל הכוחות הפרטי' בכח בחוש א' בלבד ואז יהי' אותו החוש בחוזק גדול מאד, ונמצא הרי יוכל להיות",[["924","8","<b>ובזוהר נק' טורי חשוכא</b>: זח\"ג רמט, ב."],["925","9","<b>הנה עין ה' אל יריאיו</b>: תהלים לג, יח."],["926","10","<b>עיניו כיונים</b>: שה\"ש ה, יב."],["927","11","<b>כמ\"ש בע\"ח בפי' כי יקרא קן ציפור</b>: ע\"ח ש' הזווגים. וראה תו\"א ויחי מח, א. פלח הרמון שמות שסב, א."],["928","12","<b>העין רואה והלב חומד</b>: במדב\"ר פ\"י, ב."],["929","13","<b>ותדבק נפשו בדינה</b>: בראשית לד, ג."],["930","14","<b>במי שהעלה בלבו טינא</b>: סנהדרין עה, א."],["931","15","<b>ולא תתורו</b>: במדבר טו, לט."],["932","16","<b>ראה</b>: בכת\"י ב: דאה."]]],[2101000160,"התלבשות העונג בחוש הראות ביותר מכל החושי' כו' אמנם זה א\"א לומר בסיבת התלבשות התענוג ביותר שבא מצד עצם מהות הראי' (דא\"כ הי' מהראוי שיהי' כח הראי' חזק בכח פנימי' ביותר ואינו כן שהרי החוש הריח פנימי' ביותר) שהרי אנו רואי' להיפוך שהראי' חיצוני' יותר משאר החושים כי הלא המשכת וחיבור הנפש עם דבר הנראה לעין כל בבחי' נבדל כי הרי הדבר נבדל מן האדם הרואהו ואעפ\"י שהעין מחברו ומקרבו א\"ז קירוב באמת רק שמצטייר הדבר במוח בדמיון בלבד אבל הדבר נבדל ועומד במקומו מרחוק לאדם משא\"כ חוש הריח שהבושם שמריח נכנס מהות כח הריח ועולה במוח ממש לחזק ולהחיות הנפש כידוע בענין הריח<sup data-n=\"933\">17</sup> שהנשמה נהנית ממנו וכן בבחי' חוש השמיעה נכנס באוזן ממש בחללים הקולות העריבים ומתאחד במוח שהרי אותיות הקול ממש נחקקים במוח כששומע כידוע, אך האמת הוא דבחי' התחברות חוש הראי' מתחברת לנפש בחיצוני' יותר אבל זהו רק מצד עצם מהות הראיה עצמה אך מצד בחי' התלבשות עונג הנפש אשר בחוש הראי' הנה מתלבש בה כל עונג פנימי' מעצם הנפש ביותר עד שנמשך כל הנפש אחר הדבר הנחמד למראה העין כנ\"ל בענין העין רואה והלב חומד דעיקר התאווה בא מעין אל הלב כמ\"ש וכי<sup data-n=\"934\">18</sup> תאווה הוא לעינים כו', (ולפי\"ז יש כאן ב' דברים התחברות הנפש והמשכת הנפש, ההתחברות<sup data-n=\"935\">19</sup> שהוא מצד עצם חוש הראי' היא חיצוני' יותר<sup data-n=\"936\">20</sup> מ\"מ החיבור הנפש יש בראיה יותר מצד אור התענוג המלובש בה ולא מצד עצם מהות הראי' שהרי עצם מהות הראי' אינו למעלה במדריגה מחוש הריח או השמיעה וכיוצא).\n<b>והנמשל</b> מכ\"ז יובן למעלה בבחי' מל' דאצילות דכתיב אשא<sup data-n=\"937\">21</sup> עיני אל ההרים כו' שבהסתכלות זאת מקבלת המל' הארת הכתר בחי' ש\"ע נהורין כנ\"ל, הנה לכאורה א\"ז מובן כלל דהלא בחי' מל' נק' סופא דכ\"ד בחי' אחרונה ביותר ובחי' הכתר הוא בחי' האור העליון ביותר מכולם כידוע, ואיך תקבל המל' הכתר בבחי' ההסתכלות וגם הלא ידוע ומבואר בע\"ח תמיד בסדר ההשתלשלות והתלבשות הפרצופים דכדי שיבוא אור השפע בבחי' מל' דאצי' הנה צריך לירד ע\"י כמה התלבשות וצמצומים דהיינו ע\"י שבחי' נה\"י שבעליון בלבד נעשה מוחין לתחתון כמו מבחי' נה\"י דא\"א מתלבש באו\"א נעשה להם מוחין ומבחי' נה\"י דאו\"א מתלבש בז\"א ונעשה לו מוחי' ומבחי' ז\"א מתלבש רק בבחי' נה\"י שבו בנוק' דז\"א ונעשה לה מוחין כו', נמצא גם בחי' מוחין הפנימי' שבמל' נמשך ובא מבחי' הכתר שהוא בחי' א\"א ע\"י בחי' ריבוי הלבושי' והצמצומי' בהתלבשות א\"א רק בבחי' נה\"י באו\"א כו' ואיך אמר אשא עיני אל ההרים כו' עיניך יונים כו' וכה\"ג לקבל מבחי' א\"א וכמ\"כ איך אמר יאר<sup data-n=\"938\">22</sup> ה' פניו אליך שהוא בחי' הארת פנים דא\"א אל המל' מקור כנס\"י כידוע שהוא בחי' ההסתכלות מלמעלה למטה כנ\"ל איך יכול להיות בחי' דילוג",[["933","17","<b>הריח שהנשמה נהנית ממנו</b>: ברכות מג, ב."],["934","18","<b>וכי תאוה הוא לעינים</b>: בראשית ג, ו."],["935","19","<b>ההתחברות</b>: בכת\"י ג: בהתחברות."],["936","20","<b>יותר. . יש בראיה</b>: בשאר הכת\"י: יותר מבכל החושים והמשכת הנפש יש בראי'."],["937","21","<b>אשא עיני אל ההרים</b>: תהלים קכא, א."],["938","22","<b>יאר ה' פניך אליך</b>: במדבר ו, כה."]]],[2101000161,"המדריגות כ\"כ מעליון ביותר לתחתון ביותר כו'. אך הענין הוא שיש בבחי' המל' ב' אופנים בבחי' קבלת השפע א' בהיותה מקבלת האור בבחי' קירוב הערך דהיינו שנעשה לה מוחין ואור וחיות ממש בבחי' פנימי' ותוכיו' ממש כו' כמו מבחי' נה\"י ז\"א שנעשה לה מוחין ממש עד\"מ התהוות השכל בדיבור בפה לזולתו שנק' חכ' שבדיבור (בחי' מוחין דנוק') שהוא נמשך מבחי' הבל הלב כו' וכן עד\"מ מבחי' נה\"י דאו\"א נעשה מוחין לז\"א היינו בבחי' עו\"ע שהוא בחי' אור ושפע המתקבל במקבל בבחי' קירוב הערך בבחי' אור וחיות ממש, עד\"מ התהוות חיות ואור ושכל וטעם למדות שבלב מן החו\"ב שבמוח ועד\"ז מבחי' נה\"י דא\"א נעשה בחי' מוחין לאו\"א שהוא בחי' חיצוני' הרצון המתלבש להיות מזה התהוות אור וחיות למציאות החכ' כידוע במשל כי השוחד יעור כו', ונמצא בחי' אור השפע דא\"א נמשך עד בחי' מל' דרך עו\"ע אך אעפ\"י שבא אור השפע בבחי' מוחין פנימי' שבמל' כנ\"ל אבל מפני ריבוי ההתלבשות מעילה לעילה נתצמצם ונתעלם האור מאד עד שבהגיע האור לבחי' מל' הוא בבחי' צמצום האור במאד כנראה לעין שאור מהות הרצון בא בדיבור בשינוי המהות מפני ריבוי ההעלמות מרצון לשכל ומשכל למדות כו' לפי שא\"א שיבוא לידי גילוי או\"פ במל' מבחי' הכתר א\"ל שירד האור והתצמצם בריבוי צמצומים כו', אבל באופן הב' בבחי' קבלת השפע שלא ע\"י השתלשלות והתלבשות הפרצופי' זב\"ז כו', אלא מבחי' אור הכתר יאיר במל' שלא ע\"י לבושים והעלמות אמנם אין אור זה בא בבחי' פנימי' במל' רק מרחוק בבחי' מקיף והוא בחי' הסתכלות, כמ\"ש יאר ה' פניו אליך שהוא בחי' ההסתכלות מלמעלה למטה כנ\"ל, דהנה בחי' הסתכלות זאת שנק' הארת פנים העליונים דא\"א אינו בחי' המשכה פנימי' רק חיצוני' כמו עד\"מ הבטה והסתכלות העין באדם למטה ע\"ד הנבדל חוץ ממנו כנ\"ל, שבבחי' התחברות הוא בבחי' חיצוני' בלבד כו' ואי\"ז כמו קירוב השפע שבבחי' עו\"ע הנ\"ל בבחי' התלבשות אור הכתר בחו\"ב ומחו\"ב למדות כו' כי גם בהסתכלות זאת הרי בחי' אור זה נבדל מבלתי נכנס בתוך להיות כמו בחי' המוחין כו' רק מאיר על המל' בבחי' מקיף וה\"ז כאדם גדול מאד שרואה ומסתכל בהארת פנים על הקטן מאד המרוחק בערך שמקבל הקטן עי\"ז הארה גדולה עד שיצהבו פניו ברוב אורה ושמחה כו' ובזה מתחזק כחו ביותר ולפי שאין ערך ביניהם כלל שיקבל הקטן הערך השפעה פנימי' ע\"כ מסתכל עליו מרחוק אמנם בחי' מקיף זה גדול כחו מכל מיני שפע שיהי' מגיע לו ע\"י התלבשות רבות וכדוגמא זו יובן למעלה שבחי' הארת פנים דהסתכלות א\"א במל' אעפ\"י שאינו נכנס בבחי' או\"פ אבל גדול כחו לחזק כח המל' יותר מקבלת השפע ע\"י בחי' השתלשלות והתלבשות מכתר למל' אעפ\"י שבא דרך עו\"ע בבחי' פנימי' לפי שע\"י הראי' יכול להתפשט האור להאיר גם למרחוק הערך וז\"ש יאר ה' פניו אליך וכמ\"ש<sup data-n=\"939\">23</sup> בע\"ח דעיקר הארת פנים דמל' מקבל מא\"א ע\"י הסתכלות ולזה רמזו רז\"ל דאין<sup data-n=\"940\">24</sup> אשה אלא ליופי שהוא בחי' המל' שמקבלת היופי מבחי' יופי העליון דא\"א (כמ\"ש במ\"א דלזה הטעם בנשים למטה נמצא היופי יותר מבאנשים כו'), וכמו\"כ בבחי' הסתכלות דמל' מלמטה",[["939","23","<b>וכמ\"ש בע\"ח דעיקר הארת פנים</b>: שער הזיווגים."],["940","24","<b>דאין אשה אלא ליופי</b>: תענית לא, א."]]],[2101000162,"למעלה בא\"א כמ\"ש אשא עיני אל ההרים כו' עיניך יונים וכה\"ג שבהסתכלות זאת מקבל אור דא\"א בלתי התלבשות והשתלשלות אעפ\"י שהוא חיצוני' אבל זהו עצמו הטעם שתוכל המל' לקבל גם מאור היותר עליון שהוא בחי' הכתר אעפ\"י שאין ערך ביניהם, עד\"מ העני השפל יוכל להנות מהסתכלות במלך גדול או פחות הערך מקבל אור מהסתכלות בצדיק גדול אעפ\"י שאין ערכו לקבל בבחי' השפעה פנימי' כו', וכן בנשמות הצדיקים מקבלים מאור זיו השכינה רק בבחי' הסתכלות בלבד לאסתכלא<sup data-n=\"941\">25</sup> ביקרא דמלכא כו', כך כתיב אשא עיני כו' מאין יבוא עזרי אח\"כ מהארת פנים מהסתכלות דא\"א במל' לחזק כחו ביתר שאת וז\"ש יבוא עזרי לפי שהמל' בסתר המדריגה צריכה חיזוק ממקום גבוה ביותר כו' וד\"ל.\n<b>אך</b> הנה מבואר למעלה במשל הראי' גשמיות שמצד מהות הראי' עצמו הוא חיבור חיצוני' אבל מצד בחי' התלבשות התענוג בה הנה יכול להיות בחי' הארת עצם התענוג מעצמות כל הנפש יותר מבכל החושי' וראי' מעוף ששמו ראה<sup data-n=\"942\">26</sup> כו' כך יובן ג\"כ למעלה בבחי' הסתכלות מלמעלה למטה כמ\"ש הנה<sup data-n=\"943\">27</sup> עיני ה' כו' וכן עיניו כיונים וכה\"ג שכל פנימי' אור עצמו' המאציל מתלבש בראי' זו יותר מהתלבשותו ברצון ושכל ומדות כו' לפי שבחי' עצם התענוג הפשוט מתלבש<sup data-n=\"944\">28</sup> למעלה בהסתכלות זאת משא\"כ בחי' אור התענוג ברצון ובחכ' שאינו אלא הארה חיצוני' ולא כל עצמותו כנ\"ל, וכמו\"כ ממטה למעלה בהסתכלות ממטה למעלה מבחי' המל' בכתר מתלבש בחי' כל עצמות אור המל' דהיינו כל בחי' עצם התענוג כו' כנ\"ל בענין העין רואה והלב חומד כו' שגם<sup data-n=\"945\">29</sup> התענוג שבחמדת הלב תלוי לפי אופן כח התענוג שבראי' אם מעט או הרבה כו' וגם בבחי' תענוג המל' לאסתכלא למעלה באור הכתר הוא מקור הכללי לבחי' חמדת שבלב המל' כמ\"ש לך<sup data-n=\"946\">30</sup> אמר לבי בקשו כו' לפי שכל עצמותו נמשך בהסתכלות זו וע\"כ אמר הסבי<sup data-n=\"947\">31</sup> עיניך מנגדי כו', ולא אמר כן בכל העלאת מ\"נ כמו ואל<sup data-n=\"948\">32</sup> אישך תשוקתך כו' לפי שבהסתכלות עינים יש כח העלאת כל העצמיות יותר מכל העלאת מ\"נ כו', וז\"ש שהמה הרהיבוני כו' לעורר בחי' העצמו' ממש, וז\"ש אחת<sup data-n=\"949\">33</sup> שאלתי כו' לחזות בנועם ה' כו' וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל מבחי' מל' דאצי' כללות נש\"י שיש בה ב' אופנים כנ\"ל, כך יש בכל ניצוץ בפרט ב' מדריגות הנ\"ל הא' בחי' המוחין שנמשך לה בבחי' השגה בבחי' פנימי' ומן ההשגה נולדה המדות אהוי\"ר ונק' דו\"ר שכליים וכידוע, וזהו מצות ואהבת דק\"ש שהוא אהוי\"ר שאחר ההתבוננות ביחו\"ע דק\"ש כידוע ואור השגה זו בא מלמעלה ע\"י ריבוי העלמות בכל חד לפוש\"ד כמ\"ש<sup data-n=\"950\">34</sup> בזוהר ע\"פ נודע",[["941","25","<b>לאסתכלא ביקרא דמלכא</b>: ראה זח\"ב רמז, ב."],["942","26","<b>ראה</b>: בכת\"י ב: דאה."],["943","27","<b>הנה עיני ה'</b>: ראה תהלים לג, יח. לד, טז."],["944","28","<b>מתלבש למעלה</b>: בכת\"י ב וכת\"י ג: מתלבש בבחי' הסתכלות."],["945","29","<b>שגם</b>: בכת\"י ב: שכח. ובכת\"י ג: שכל."],["946","30","<b>לך אמר לבי</b>: תהלים כז, ח."],["947","31","<b>הסבי עיניך מנגדי</b>: שה\"ש ו, ה."],["948","32","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["949","33","<b>אחת שאלתי</b>: תהלים כז, ד."],["950","34","<b>כמ\"ש בזוהר ע\"פ נודע בשערים בעלה</b>: זח\"א קג, א."]]],[2101000163,"בשערים בעלה כו' בתרעין תתאין דמל' ומשם נמשך לנשמות בפרט כמו השגת דנשמה בג\"ע דבריאה מבחי' בינה שבמל' שנמשך לכאו\"א כפי מדריגתו וכל<sup data-n=\"951\">35</sup> א' נכווה מחופתו של חבירו כו' והיינו עפ\"י השתלשלות נש\"ב דמל' כו' ועד\"ז משתלשל כמה מדריגות אהוי\"ר בנשמות ומלאכי' דיצי' ועשי' עד נשמות שבגופים בעוה\"ז כו', ומדריגה הב' הוא בחי' הסתכלות כמ\"ש<sup data-n=\"952\">36</sup> בזוהר לאסתכלא ביקרא דמלכא כו', והוא שרש ענין פסוד\"ז שלפני ק\"ש והוא ע\"ד הנ\"ל בבחי' הסתכלות דמל' בא\"א כמ\"ש אשא עיני כו' עיני כל אליך כו'.\n<b>וביאור</b> הדברים הנה י\"ל מארז\"ל במה שגזרו אומר דלעולם<sup data-n=\"953\">37</sup> יסדר אדם שבחו של מקום ואח\"כ יתפלל, והענין הוא כי כוונתם שהתפלה תלויה בסידור השבחים בפסוד\"ז תחילה וא\"ל לא יוכל להתפלל כלל, והטעם הוא כי הנה ע\"ד הפשוט הנה עיקר התפילה הוא בחי' אוי\"ר שנולדה מהתבוננות דיחו\"ע בק\"ש ועי\"ז נמשך בחי' מוחין פנימי' בניצוץ דהיינו מה שבחי' השגה אלקי' ביחו\"ע ויחו\"ת נכנסה בתוך פנימי' המוחין והלב כמו לאהוב את ה' כי הוא חייך בבחי' ממלא וסובב כו', הרי נמשך עי\"ז בחי' גילוי אור ה' דסובב וממלא בכל ניצוץ בתוך תוכו בבחי' הפנימי' כנ\"ל, אבל בחי' סידור השבחי' בפסוד\"ז אין ענין התפעלות אהוי\"ר הבאים מהתפעלות השגה כלל אלא רק שמספר ומסדר שבחו של מקום כמו עד\"מ איש שמספר באיזו גדולת מלך גדול שמפליג בשבחו שאי\"ז ענין אהבה או יראה מן<sup data-n=\"954\">38</sup> התפעלות שכל רק מפליג מאד בשבחו אבל הפלגה זו כוללת כל מה שצריך להתפעל במורא כו' וה\"ז כמו המסתכל בגדולת המלך שמפני הסתכלותו בעוצם יקר ת\"ת הגדולה נמשך כל נפשו בהתפעלות התענוג והוא למעלה מבחי' האהוי\"ר שבא מן ההשגה בצמצום ערכו כו'.\n<b>אך</b> עדיין י\"ל למה צריך לספר בשבחים אחר שאין אלא ענין לאסתכלא ביקרא דמלכא כו', אמנם הענין הוא כי ע\"י השבח מעורר למדת משבח מבחי' העלמה בעצמות המאציל שתבוא לידי גילוי עד\"מ כשמשבחין לאיש שהוא חכם מעוררי' בשורש ומקור חכמתו כמו שהיא כלולה בעצמות נפשו וכן מדת החסד יעורר בשרש ומקור מדת חסדו כו', וראי' לד\"ז ממה שיתפעל המלך להיטיב חסדו יותר מכפי המדה כו' כמ\"ש במ\"א באריכות ולזה הטעם הוסד סדר השבחי' כדי לעורר מדותיו ית' הכלולים וגנוזים בעצמותו ממש וגילוי ההעלם הזה נק' אור המאיר ומקור הגילוי הזה מקור כל אור המאיר כמו הצור שיוציאו ממנו אור הוא העלם האור כו' (וכמ\"ש<sup data-n=\"955\">39</sup> במ\"א בענין הלל וברכה כו'), ולזה הטעם נבחרו מזמורים שהן בשם הללוי\"ה בתחילה וסוף כי פי' הלל מלשון בהילו<sup data-n=\"956\">40</sup> נרו שהוא מקור הבהקת גילוי אור",[["951","35","<b>וכל א' נכוה מחופתו של חבירו</b>: ב\"ב עה, א."],["952","36","<b>כמ\"ש בזוהר לאסתכלא ביקרא דמלכא</b>: ראה זח\"ב רמז, ב."],["953","37","<b>דלעולם יסדר אדם שבחו של מקום</b>: ברכות לב, א. ובכ\"מ."],["954","38","<b>מן</b>: בכת\"י ב וכת\"י ג: או."],["955","39","<b>וכמ\"ש במ\"א בענין הלל וברכה</b>: ראה תו\"א ל, א. סה\"מ תקס\"ח ע' שע. שערי אורה יח, א. יהל אור ע' תקנח."],["956","40","<b>בהילו נרו</b>: איוב כט, ג."]]]]});
